void amrex::SetErrorHandler (amrex::ErrorHandler f) {
    amrex::system::error_handler = f;
}

void
amrex::write_to_stderr_without_buffering (const char* str)
{
    //
    // Flush all buffers.
    //
    std::fflush(nullptr);

    if (str)
    {
        std::ostringstream procall;
        procall << ParallelDescriptor::MyProc() << "::";
        auto const tmp = procall.view();
        const char * const end = " !!!\n";
        std::fwrite(tmp.data(), tmp.size(), 1, stderr);
        std::fwrite(str, strlen(str), 1, stderr);
        std::fwrite(end, strlen(end), 1, stderr);
    }
}

void
write_lib_id(const char* msg)
{
    std::fflush(nullptr);
    const char* const s = "amrex::";
    std::fwrite(s, strlen(s), 1, stderr);
    if ( msg )
    {
        std::fwrite(msg, strlen(msg), 1, stderr);
        std::fwrite("::", 2, 1, stderr);
    }
}

void
amrex::Error_host (const char* type, const char * msg)
{
    amrex::ignore_unused(type);
#ifdef AMREX_USE_COVERITY
    amrex_coverity_abort();
#else
    if (system::error_handler) {
        system::error_handler(msg);
    } else if (system::throw_exception) {
        throw RuntimeError(msg ? msg : type);
    } else {
        write_lib_id(type);
        write_to_stderr_without_buffering(msg);
#ifdef AMREX_USE_OMP
#pragma omp critical (amrex_abort_omp_critical)
#endif
        ParallelDescriptor::Abort();
    }
#endif
}

void
amrex::Warning_host (const char * msg)
{
    if (msg) {
        amrex::Print(Print::AllProcs,amrex::ErrorStream()) << msg << '!' << '\n';
    }
}

void
amrex::Assert_host (const char* EX, const char* file, int line, const char* msg,
                    std::size_t msg_size)
{
#ifdef AMREX_USE_COVERITY
    amrex_coverity_abort();
#else
    const std::size_t N = 512 + msg_size;

    std::vector<char> buf(N);

    if (msg) {
        snprintf(buf.data(),
                 N,
                 "Assertion `%s' failed, file \"%s\", line %d, Msg: %s",
                 EX,
                 file,
                 line,
                 msg);
    } else {
        snprintf(buf.data(),
                 N,
                 "Assertion `%s' failed, file \"%s\", line %d",
                 EX,
                 file,
                 line);
    }

    if (system::error_handler) {
        system::error_handler(buf.data());
    } else if (system::throw_exception) {
        throw RuntimeError(buf.data());
    } else {
       write_to_stderr_without_buffering(buf.data());
#ifdef AMREX_USE_OMP
#pragma omp critical (amrex_abort_omp_critical)
#endif
       ParallelDescriptor::Abort();
   }
#endif
}

void
amrex::ExecOnFinalize (std::function<void()> f)
{
    The_Finalize_Function_Stack.push(std::move(f));
}

void
amrex::ExecOnInitialize (std::function<void()> f)
{
    The_Initialize_Function_Stack.push(std::move(f));
}

amrex::AMReX*
amrex::Initialize (MPI_Comm mpi_comm,
                   std::ostream& a_osout, std::ostream& a_oserr,
                   ErrorHandler a_errhandler, int a_device_id)
{
    int argc = 0;
    char** argv = nullptr;
    return Initialize(argc, argv, false, mpi_comm, {}, a_osout, a_oserr,
                      a_errhandler, a_device_id);
}

amrex::AMReX*
amrex::Initialize (int& argc, char**& argv,
                   const std::function<void()>& func_parm_parse,
                   std::ostream& a_osout, std::ostream& a_oserr,
                   ErrorHandler a_errhandler, int a_device_id)
{
    return Initialize(argc, argv, true, MPI_COMM_WORLD, func_parm_parse,
                      a_osout, a_oserr, a_errhandler, a_device_id);
}

amrex::AMReX*
amrex::Initialize (int& argc, char**& argv, bool build_parm_parse,
                   MPI_Comm mpi_comm, const std::function<void()>& func_parm_parse,
                   std::ostream& a_osout, std::ostream& a_oserr,
                   ErrorHandler a_errhandler, int a_device_id)
{
    system::exename.clear();
    if (initialization_by_init_minimal) {
        system::verbose = 0;
        system::regtest_reduction = false;
        system::signal_handling = false;
        system::handle_sigsegv = false;
        system::handle_sigterm = false;
        system::handle_sigint  = false;
        system::handle_sigabrt = false;
        system::handle_sigfpe  = false;
        system::handle_sigill  = false;
        system::handle_crt_reports = false;
        system::call_addr2line = false;
        system::throw_exception = false;
        system::osout = &std::cout;
        system::oserr = &std::cerr;
        system::error_handler = nullptr;
    } else {
//    system::verbose = 0;
        system::regtest_reduction = false;
        system::signal_handling = true;
        system::handle_sigsegv = true;
        system::handle_sigterm = false;
        system::handle_sigint  = true;
        system::handle_sigabrt = true;
        system::handle_sigfpe  = true;
        system::handle_sigill  = true;
        system::handle_crt_reports = true;
        system::call_addr2line = true;
        system::throw_exception = false;
        system::osout = &a_osout;
        system::oserr = &a_oserr;
        system::error_handler = a_errhandler;
    }

#ifdef AMREX_USE_MPI
    // MPI_Init may set up GPU communication on the current GPU.
    if (! initialization_by_init_minimal && a_device_id < 0) {
        Gpu::SelectDeviceBeforeMPIInit();
    }
#endif

    ParallelDescriptor::StartParallel(&argc, &argv, mpi_comm);

    prev_out_precision = system::osout->precision(10);
    prev_err_precision = system::oserr->precision(10);

#ifdef AMREX_PMI
    ParallelDescriptor::PMI_Initialize();

#ifdef AMREX_PMI
    ParallelDescriptor::PMI_Initialize();
#endif

    //
    // Make sure to catch new failures.
    //
    prev_new_handler = std::set_new_handler(amrex::OutOfMemory);

    command_line.clear();
    command_arguments.clear();

    if (argc > 0)
    {
        if (argv[0][0] != '/') {
            auto cwd = FileSystem::CurrentPath();
            if (!cwd.empty()) {
                system::exename = std::move(cwd);
                system::exename += "/";
            }
        }
        system::exename += argv[0];

        for (int i = 0; i < argc; ++i) {
            if (i != 0) { command_line.append(" "); }
            command_line.append(argv[i]);
            command_arguments.emplace_back(argv[i]);
        }
    }

#if defined(AMREX_USE_UPCXX)
    upcxx::init();
#endif

    while ( ! The_Initialize_Function_Stack.empty())
    {
        //
        // Remove the function from the stack before calling it, so that a function
        // that calls ExecOnInitialize itself neither runs twice nor drops the newly
        // registered function.
        //
        auto f = std::move(The_Initialize_Function_Stack.top());
        The_Initialize_Function_Stack.pop();
        f();
    }

    BL_PROFILE_INITIALIZE();

#ifndef BL_AMRPROF
    if (build_parm_parse)
    {
        if (argc <= 1)
        {
            // No command line to parse. argc == 0 is the library/embedded entry
            // point (e.g. language bindings), argc == 1 the executable name only.
            ParmParse::Initialize(0,nullptr,nullptr);
        }
        else
        {
            if (argv[1][0] == '-')
            {
                // If arguments list starts with "-", do not use ParmParse.
                // Application code can then parse the command line. This will
                // prevent "-h" or "--help" from creating errors in ParmParse,
                // but only if it's the first argument after the executable.
                ParmParse::Initialize(0,nullptr,nullptr);

                // prevent "-h" or "--help" from creating errors in ParmParse,
                // but only if it's the first argument after the executable.
                ParmParse::Initialize(0,nullptr,nullptr);
            }
            else
            {
                // This counts command line arguments before a "--"
                // and only sends the preceding arguments to ParmParse;
                // the rest get ignored.
                int ppargc = 1;
                for (; ppargc < argc; ++ppargc) {
                    if (std::strcmp(argv[ppargc], "--") == 0) { break; }
                }
                if (ppargc > 1)
                {
                    if (std::strchr(argv[1],'=') || (argc > 2 ? argv[2][0] == '=' : false) )
                    {
                        // No inputs file to parse
                        ParmParse::Initialize(ppargc-1,argv+1,nullptr);
                    }
                    else
                    {
                        // argv[1] is an inputs file
                        ParmParse::Initialize(ppargc-2,argv+2,argv[1]);
                    }
                }
            }
        }
    } else {
        ParmParse::Initialize(0,nullptr,nullptr);
    }

    if (func_parm_parse) {
        func_parm_parse();
    }

    {
        ParmParse pp("amrex");
        if (! pp.query("verbose", "v", system::verbose)) {
            pp.add("verbose", system::verbose);
        }
        pp.queryAdd("init_snan", system::init_snan);
    }

    if (system::verbose > 0) {
        amrex::Print() << "Initializing AMReX (" << amrex::Version() << ")...\n";
    }

#ifdef AMREX_USE_MPI
    if (system::verbose > 0) {
        amrex::Print() << "MPI initialized with "
                       << ParallelDescriptor::NProcs()
                       << " MPI processes\n";
        int provided = -1;
        MPI_Query_thread(&provided);
        amrex::Print() << "MPI initialized with thread support level " << provided << '\n';
    }
#endif

    }
#endif

#ifdef AMREX_USE_OMP
    amrex::OpenMP::Initialize();

    // status output
    if (system::verbose > 0) {

void
amrex::Finalize (amrex::AMReX* pamrex)
{
#ifdef AMREX_USE_GPU
    Gpu::streamSynchronizeAll();
#endif

    AMReX::erase(pamrex);

#ifdef AMREX_USE_PETSC
    if (petsc_initialized_by_amrex) {
        PetscFinalize();
        petsc_initialized_by_amrex = false;
    }
#endif

#ifdef AMREX_USE_HYPRE
    if (init_hypre) { HYPRE_Finalize(); }
#endif

    BL_TINY_PROFILE_FINALIZE();
    BL_PROFILE_FINALIZE();

#ifdef AMREX_USE_GPU
    amrex::DeallocateRandomSeedDevArray();
#endif

#ifdef BL_LAZY
    Lazy::Finalize();
#endif

    while (!The_Finalize_Function_Stack.empty())
    {
        //
        // Remove the function from the stack before calling it, so that a function
        // that calls ExecOnFinalize itself neither runs twice nor drops the newly
        // registered function.
        //
        auto f = std::move(The_Finalize_Function_Stack.top());
        The_Finalize_Function_Stack.pop();
        f();
    }

    // The MemPool stuff is not using The_Finalize_Function_Stack so that
    // it can be used in Fortran BoxLib.
#ifndef BL_AMRPROF
    if (amrex::system::verbose > 1)
    {
        int mp_min, mp_max, mp_tot;
        amrex_mempool_get_stats(mp_min, mp_max, mp_tot);  // in MB
        if (ParallelDescriptor::NProcs() == 1) {
            if (mp_tot > 0) {
                amrex::Print() << "MemPool: "
#ifdef AMREX_USE_OMP
                               << "min used in a thread: " << mp_min << " MB, "
                               << "max used in a thread: " << mp_max << " MB, "
#endif
                               << "tot used: " << mp_tot << " MB." << '\n';
            }
        } else {
            int global_max = mp_tot;
            int global_min = mp_tot;
            ParallelDescriptor::ReduceIntMax(global_max);
            if (global_max > 0) {
                ParallelDescriptor::ReduceIntMin(global_min);
                amrex::Print() << "MemPool: "
                               << "min used in a rank: " << global_min << " MB, "

                ParallelDescriptor::ReduceIntMin(global_min);
                amrex::Print() << "MemPool: "
                               << "min used in a rank: " << global_min << " MB, "
                               << "max used in a rank: " << global_max << " MB.\n";
            }
        }
    }
#endif

#ifdef AMREX_MEM_PROFILING
    MemProfiler::report("Final");
    MemProfiler::Finalize();
#endif

#ifdef AMREX_USE_SUNDIALS
    sundials::Finalize();
#endif

    BL_TINY_PROFILE_MEMORYFINALIZE();

    amrex_mempool_finalize();
    Arena::Finalize();

#ifndef BL_AMRPROF
    if (system::signal_handling)
    {
        if (prev_handler_sigsegv != SIG_ERR) { std::signal(SIGSEGV, prev_handler_sigsegv); } // NOLINT(performance-no-int-to-ptr)
        if (prev_handler_sigterm != SIG_ERR) { std::signal(SIGTERM, prev_handler_sigterm); } // NOLINT(performance-no-int-to-ptr)
        if (prev_handler_sigint  != SIG_ERR) { std::signal(SIGINT , prev_handler_sigint);  } // NOLINT(performance-no-int-to-ptr)
        if (prev_handler_sigabrt != SIG_ERR) {
            // restore the CRT report of abort() together with the previous handler
            detail::CrtReportSkipAbortReport(false);
            std::signal(SIGABRT, prev_handler_sigabrt); // NOLINT(performance-no-int-to-ptr)
        }
        if (prev_handler_sigfpe  != SIG_ERR) { std::signal(SIGFPE , prev_handler_sigfpe);  } // NOLINT(performance-no-int-to-ptr)
        if (prev_handler_sigill  != SIG_ERR) { std::signal(SIGILL , prev_handler_sigill);  } // NOLINT(performance-no-int-to-ptr)
#if defined(__linux__) && defined(__GLIBC__)
#if !defined(__PGI) || (__PGIC__ >= 16)
        if (curr_fpe_excepts != 0) {
            fedisableexcept(curr_fpe_excepts);
            feenableexcept(prev_fpe_excepts);
        }
#endif
#elif defined(__APPLE__) && defined(__x86_64__)
        if (curr_fpe_excepts != 0u) {
            _MM_SET_EXCEPTION_MASK(prev_fpe_mask);
        }
#endif
    }
#endif

#ifdef AMREX_USE_GPU

#endif

#ifdef AMREX_USE_GPU
    Gpu::Device::Finalize();
#endif

#ifdef AMREX_USE_OMP
    amrex::OpenMP::Finalize();
#endif

#if defined(AMREX_USE_UPCXX)
    upcxx::finalize();
#endif

    std::set_new_handler(prev_new_handler);

    amrex::OutStream().precision(prev_out_precision);
    amrex::ErrorStream().precision(prev_err_precision);

    bool is_ioproc = ParallelDescriptor::IOProcessor();

    /* Don't shut down MPI if GASNet is still using MPI */
#ifndef GASNET_CONDUIT_MPI
    ParallelDescriptor::EndParallel();
#endif

    if (amrex::system::verbose > 0 && is_ioproc) {
        amrex::OutStream() << "AMReX (" << amrex::Version() << ") finalized" << '\n';
    }

    // last, also before this (possibly dynamically loaded) library is unloaded
    detail::CrtReportFinalize();
}

int
amrex::command_argument_count ()
{
    return std::max(0, static_cast<int>(command_arguments.size())-1);
}

std::string
amrex::get_command_argument (int number)
{
    if (number >= 0 && number < std::ssize(command_arguments)) {
        return command_arguments[number];
    } else {
        return std::string();
    }
}

void
AMReX::push (AMReX* pamrex)
{
    auto r = std::find_if(m_instance.begin(), m_instance.end(),
                          [=] (const std::unique_ptr<AMReX>& x) -> bool
                          { return x.get() == pamrex; });
    if (r == m_instance.end()) {
        m_instance.emplace_back(pamrex);
    } else if (r+1 != m_instance.end()) {
        std::rotate(r, r+1, m_instance.end());
    }
}

void
AMReX::push (std::unique_ptr<AMReX> pamrex)
{
    m_instance.push_back(std::move(pamrex));
}

void
AMReX::erase (AMReX* pamrex)
{
    auto r = std::find_if(m_instance.begin(), m_instance.end(),
                          [=] (const std::unique_ptr<AMReX>& x) -> bool
                          { return x.get() == pamrex; });
    if (r != m_instance.end()) {
        m_instance.erase(r);
    }
}

/* macOS has no fe{get,enable,disable}except, so we read and write the
     * trap bits of the floating point control register directly. */
    FPExcept apple_get_fpexcept ()
    {
        auto r = FPExcept::none;
#if defined(__x86_64__)
        // A set mask bit means the exception is masked, i.e. not trapped.
        auto const mask = _MM_GET_EXCEPTION_MASK();
        if (!(mask & _MM_MASK_INVALID )) { r = r | FPExcept::invalid ; }
        if (!(mask & _MM_MASK_DIV_ZERO)) { r = r | FPExcept::zero    ; }
        if (!(mask & _MM_MASK_OVERFLOW)) { r = r | FPExcept::overflow; }
#else
        fenv_t env;
        fegetenv(&env);
        if (env.__fpcr & __fpcr_trap_invalid  ) { r = r | FPExcept::invalid ; }
        if (env.__fpcr & __fpcr_trap_divbyzero) { r = r | FPExcept::zero    ; }
        if (env.__fpcr & __fpcr_trap_overflow ) { r = r | FPExcept::overflow; }
#endif
        return r;
    }

//! Enable trapping of the exceptions in `on`, disable those in `off`.
    void apple_set_fpexcept (FPExcept on, FPExcept off)
    {
        unsigned int on_bits = 0U;
        unsigned int off_bits = 0U;
#if defined(__x86_64__)
        if (any(on  & FPExcept::invalid )) { on_bits  |= _MM_MASK_INVALID ; }
        if (any(on  & FPExcept::zero    )) { on_bits  |= _MM_MASK_DIV_ZERO; }
        if (any(on  & FPExcept::overflow)) { on_bits  |= _MM_MASK_OVERFLOW; }
        if (any(off & FPExcept::invalid )) { off_bits |= _MM_MASK_INVALID ; }
        if (any(off & FPExcept::zero    )) { off_bits |= _MM_MASK_DIV_ZERO; }
        if (any(off & FPExcept::overflow)) { off_bits |= _MM_MASK_OVERFLOW; }
        auto mask = _MM_GET_EXCEPTION_MASK();
        mask |= off_bits;   // masked, i.e. not trapped
        mask &= ~on_bits;   // unmasked, i.e. trapped
        _MM_SET_EXCEPTION_MASK(mask);
#else
        if (any(on  & FPExcept::invalid )) { on_bits  |= __fpcr_trap_invalid  ; }
        if (any(on  & FPExcept::zero    )) { on_bits  |= __fpcr_trap_divbyzero; }
        if (any(on  & FPExcept::overflow)) { on_bits  |= __fpcr_trap_overflow ; }
        if (any(off & FPExcept::invalid )) { off_bits |= __fpcr_trap_invalid  ; }
        if (any(off & FPExcept::zero    )) { off_bits |= __fpcr_trap_divbyzero; }
        if (any(off & FPExcept::overflow)) { off_bits |= __fpcr_trap_overflow ; }
        fenv_t env;
        fegetenv(&env);
        env.__fpcr &= ~static_cast<unsigned long long>(off_bits);
        env.__fpcr |= on_bits;
        fesetenv(&env);
#endif
    }

FPExcept getFPExcept ()
{
    auto r = FPExcept::none;
#if defined(__linux__) && defined(__GLIBC__)
    auto excepts = fegetexcept();
    if (excepts & FE_INVALID  ) { r = r | FPExcept::invalid ; }
    if (excepts & FE_DIVBYZERO) { r = r | FPExcept::zero    ; }
    if (excepts & FE_OVERFLOW ) { r = r | FPExcept::overflow; }
#elif defined(__APPLE__) && (defined(__x86_64__) || defined(__aarch64__))
    r = apple_get_fpexcept();
#endif
    return r;
}

FPExcept setFPExcept (FPExcept excepts)
{
    auto prev = getFPExcept();
#if defined(__linux__) && defined(__GLIBC__)
    int flags = FE_INVALID | FE_DIVBYZERO | FE_OVERFLOW;
    fedisableexcept(flags);
    flags = 0;
    if (any(excepts & FPExcept::invalid )) { flags |= FE_INVALID  ; }
    if (any(excepts & FPExcept::zero    )) { flags |= FE_DIVBYZERO; }
    if (any(excepts & FPExcept::overflow)) { flags |= FE_OVERFLOW ; }
    feenableexcept(flags);
#elif defined(__APPLE__) && (defined(__x86_64__) || defined(__aarch64__))
    apple_set_fpexcept(excepts, FPExcept::all);
#else
    amrex::ignore_unused(excepts);
#endif
    return prev;
}

FPExcept disableFPExcept (FPExcept excepts)
{
    auto prev = getFPExcept();
#if defined(__linux__) && defined(__GLIBC__)
    int flags = 0;
    if (any(excepts & FPExcept::invalid )) { flags |= FE_INVALID  ; }
    if (any(excepts & FPExcept::zero    )) { flags |= FE_DIVBYZERO; }
    if (any(excepts & FPExcept::overflow)) { flags |= FE_OVERFLOW ; }
    fedisableexcept(flags);
#elif defined(__APPLE__) && (defined(__x86_64__) || defined(__aarch64__))
    apple_set_fpexcept(FPExcept::none, excepts);
#else
    amrex::ignore_unused(excepts);
#endif
    return prev;
}

FPExcept enableFPExcept (FPExcept excepts)
{
    auto prev = getFPExcept();
#if defined(__linux__) && defined(__GLIBC__)
    int flags = 0;
    if (any(excepts & FPExcept::invalid )) { flags |= FE_INVALID  ; }
    if (any(excepts & FPExcept::zero    )) { flags |= FE_DIVBYZERO; }
    if (any(excepts & FPExcept::overflow)) { flags |= FE_OVERFLOW ; }
    feenableexcept(flags);
#elif defined(__APPLE__) && (defined(__x86_64__) || defined(__aarch64__))
    apple_set_fpexcept(excepts, FPExcept::none);
#else
    amrex::ignore_unused(excepts);
#endif
    return prev;
}

void Init_minimal (MPI_Comm mpi_comm)
{
    ++init_minimal_called;

    if (Initialized()) { return; }

    initialization_by_init_minimal = true;
    Initialize(mpi_comm);
}

void Finalize_minimal ()
{
    if (init_minimal_called > 0) {
        --init_minimal_called;
    }
    if (init_minimal_called == 0 && initialization_by_init_minimal) {
        Finalize();
        initialization_by_init_minimal = false;
    }
}

