    makePolymorphic (Array4<T> const& a)
    {
        return PolymorphicArray4<T>(a);
    }

void Initialize ()
{
    amrex::ignore_unused(s_comm,s_info);

    ParmParse pp("amrex");
    pp.queryAdd("async_out", s_asyncout);
    pp.queryAdd("async_out_nfiles", s_noutfiles);

    int nprocs = ParallelDescriptor::NProcs();
    s_noutfiles = std::max(1, std::min(s_noutfiles, nprocs));

#ifdef AMREX_USE_MPI
    if (s_asyncout && s_noutfiles < nprocs)
    {
        int provided = -1;
        MPI_Query_thread(&provided);
        if (provided < MPI_THREAD_MULTIPLE) {
            amrex::Abort("AsyncOut with " + std::to_string(s_noutfiles) + " and "
                         + std::to_string(nprocs) + " processes requires "
                         + "MPI_THREAD_MULTIPLE at runtime, but got "
                         + ParallelDescriptor::mpi_level_to_string(provided));
        }
        int myproc = ParallelDescriptor::MyProc();
        s_info = GetWriteInfo(myproc);
        MPI_Comm_split(ParallelDescriptor::Communicator(), s_info.ifile, myproc, &s_comm);
    }
#endif

    if (s_asyncout) {
        s_thread = std::make_unique<BackgroundThread>();
    }

    ExecOnFinalize(Finalize);
}

void Finalize ()
{
    if (s_thread) {
        s_thread.reset();
    }

#ifdef AMREX_USE_MPI
    if (s_comm != MPI_COMM_NULL) { MPI_Comm_free(&s_comm); }
    s_comm = MPI_COMM_NULL;
#endif
}

WriteInfo GetWriteInfo (int rank)
{
    const int nfiles = s_noutfiles;
    const int nprocs = ParallelDescriptor::NProcs();
    const int nmaxspots = (nprocs + (nfiles-1)) / nfiles;  // max spots per file
    const int nfull = nfiles + nprocs - nmaxspots*nfiles;  // the first nfull files are full

    int ifile, ispot, nspots;
    if (rank < nfull*nmaxspots) {
        ifile = rank / nmaxspots;
        ispot = rank - ifile*nmaxspots;
        nspots = nmaxspots;
    } else {
        int tmpproc = rank-nfull*nmaxspots;
        ifile = tmpproc/(nmaxspots-1);
        ispot = tmpproc - ifile*(nmaxspots-1);
        ifile += nfull;
        nspots = nmaxspots - 1;
    }

    return WriteInfo{.ifile = ifile, .ispot = ispot, .nspots = nspots};
}

void Submit (std::function<void()>&& a_f)
{
    s_thread->Submit(std::move(a_f));
}

void Submit (std::function<void()> const& a_f)
{
    s_thread->Submit(a_f);
}

void Wait ()
{
#ifdef AMREX_USE_MPI
    const int N = s_info.ispot;
    if (N > 0) {
        Vector<MPI_Request> reqs(N);
        Vector<MPI_Status> stats(N);
        for (int i = 0; i < N; ++i) {
            reqs[i] = ParallelDescriptor::Abarrier(s_comm).req();
        }
        ParallelDescriptor::Waitall(reqs, stats);
    }
#endif
}

void Notify ()
{
#ifdef AMREX_USE_MPI
    const int N = s_info.nspots - 1 - s_info.ispot;
    if (N > 0) {
        Vector<MPI_Request> reqs(N);
        Vector<MPI_Status> stats(N);
        for (int i = 0; i < N; ++i) {
            reqs[i] = ParallelDescriptor::Abarrier(s_comm).req();
        }
        ParallelDescriptor::Waitall(reqs, stats);
    }
#endif
}

/**
 * \struct amrex::AsyncOut::WriteInfo
 * \brief Slot assignment metadata for ranks sharing an output file.
 * \ingroup amrex_io
 */
struct WriteInfo {
    int ifile;
    int ispot;
    int nspots;
}

BackgroundThread::BackgroundThread ()
{
    m_thread = std::make_unique<std::thread>(&BackgroundThread::do_job, this);
}

BackgroundThread::~BackgroundThread ()
{
    if (m_thread) {
        Submit([this] () { m_finalizing = true; });
        m_thread->join();
        m_thread.reset();
    }
}

void BackgroundThread::do_job ()
{
    while (true)
    {
        std::unique_lock<std::mutex> lck(m_mutx);
        m_job_cond.wait(lck, [this] () -> bool { return !m_func.empty(); });
        auto f = m_func.front();
        m_func.pop();
        lck.unlock();
        f();
        if (m_clearing) { // All jobs before this have finished.
            m_done_cond.notify_one();
        }
        if (m_finalizing) {
            break;
        }
    }
}

void BackgroundThread::Submit (std::function<void()>&& a_f)
{
    std::scoped_lock lck(m_mutx);
    m_func.emplace(std::move(a_f));
    m_job_cond.notify_one();
}

void BackgroundThread::Submit (std::function<void()> const& a_f)
{
    std::scoped_lock lck(m_mutx);
    m_func.emplace(a_f);
    m_job_cond.notify_one();
}

void BackgroundThread::Finish ()
{
    if (m_thread) {
        Submit([this] () { m_clearing = true; });
        std::unique_lock<std::mutex> lck(m_mutx);
        m_done_cond.wait(lck, [this] () -> bool { return m_func.empty(); });
        m_clearing = false;
        lck.unlock();
    }
}

/**
 * \class amrex::BackgroundThread
 * \brief Utility class running deferred work on a single background thread.
 * \ingroup amrex_utilities
 */
class BackgroundThread
{
public:
    /**
     * \brief Launch the worker thread and initialize synchronization primitives.
     */
    BackgroundThread ();
    /**
     * \brief Stop the worker thread and drain any queued work.
     */
    ~BackgroundThread ();
    BackgroundThread (BackgroundThread const&) = delete;
    BackgroundThread (BackgroundThread &&) = delete;
    BackgroundThread& operator= (BackgroundThread const&) = delete;
    BackgroundThread& operator= (BackgroundThread &&) = delete;

    /**
     * \brief Enqueue a job that will run asynchronously on the worker thread.
     * \param a_f Functor representing the work to execute.
     */
    void Submit (std::function<void()>&& a_f);
    /**
     * \overload
     */
    void Submit (std::function<void()> const& a_f);

    /**
     * \brief Block the caller until all queued jobs have completed.
     */
    void Finish ();

private:
    void do_job ();

    std::unique_ptr<std::thread> m_thread;
    std::mutex m_mutx;
    std::condition_variable m_job_cond;
    std::condition_variable m_done_cond;
    std::queue<std::function<void()> > m_func;
    bool m_clearing = false;
    bool m_finalizing = false;
}

void*
amrex::BArena::alloc (std::size_t sz_)
{
    sz_ = Arena::align(sz_);
    auto sys_alloc = [] (std::size_t sz) {
#ifndef _WIN32
        return std::aligned_alloc(align_size, sz);
#else
        return _aligned_malloc(sz, align_size);
#endif
    };
    void* pt = sys_alloc(sz_);
    if (pt == nullptr && sz_ > 0) {
        // the pooled host arenas may hold enough unused memory
        auto release = [] (Arena* a) -> std::size_t {
            return (a->isHostAccessible() && !a->isManaged()) ? a->freeUnused() : 0;
        };
        std::size_t nfreed = release(The_Comms_Arena());
        if (The_Pinned_Arena() != The_Comms_Arena()) {
            nfreed += release(The_Pinned_Arena());
        }
        if (nfreed > 0) { pt = sys_alloc(sz_); }
    }
    if (pt == nullptr && sz_ > 0) {
        amrex::ErrorStream() << "Out of CPU memory: got nullptr from std::aligned_alloc\n";
        throw_out_of_memory("CPU memory", sz_, "std::aligned_alloc returned nullptr");
    }
    m_profiler.profile_alloc(pt, sz_);
    return pt;
}

void
amrex::BArena::free (void* pt)
{
    m_profiler.profile_free(pt);
#ifndef _WIN32
    std::free(pt);
#else
    _aligned_free(pt);
#endif
}

/**
 * \class amrex::BArena
 * \brief Basic Arena that allocates aligned memory on the host heap.
 * \ingroup amrex_memory
 */
class BArena
    :
    public Arena
{
public:
    /**
     * \brief Allocate host memory.
     * \param sz Number of bytes to allocate.
     * \return Aligned host pointer to the allocated memory.
     */
    [[nodiscard]] void* alloc (std::size_t sz) final;
    /**
     * \brief Free memory previously returned by alloc().
     * \param pt Pointer to the allocation to release.
     */
    void free (void* pt) final;

    /** \brief Return false; BArena allocations are not device accessible. */
    [[nodiscard]] bool isDeviceAccessible () const final;
    /** \brief Return true; BArena allocations reside on the host. */
    [[nodiscard]] bool isHostAccessible () const final;

    /** \brief Return false; BArena memory is not managed/unified. */
    [[nodiscard]] bool isManaged () const final;
    /** \brief Return false; BArena operates on the host. */
    [[nodiscard]] bool isDevice () const final;
    /** \brief Return false; BArena does not allocate pinned memory. */
    [[nodiscard]] bool isPinned () const final;
}

void
BaseFab_Initialize ()
{
    if (!basefab_initialized)
    {
        basefab_initialized = true;

#ifdef AMREX_USE_OMP
#pragma omp parallel
        {
            amrex::private_total_bytes_allocated_in_fabs     = 0;
            amrex::private_total_bytes_allocated_in_fabs_hwm = 0;
            amrex::private_total_cells_allocated_in_fabs     = 0;
            amrex::private_total_cells_allocated_in_fabs_hwm = 0;
        }
#endif

#ifdef AMREX_MEM_PROFILING
        MemProfiler::add("Fab", std::function<MemProfiler::MemInfo()>
                         ([] () -> MemProfiler::MemInfo {
                             return {amrex::TotalBytesAllocatedInFabs(),
                                     amrex::TotalBytesAllocatedInFabsHWM()};
                         }));
#endif
    }

    amrex::ExecOnFinalize(amrex::BaseFab_Finalize);
}

