        if (Gpu::Device::devicePropMajor() >= 6) {
            std::size_t s = sizeof(T)*this->nvar*this->domain.numPts();
#if defined(CUDART_VERSION) && (CUDART_VERSION >= 13000)
            cudaMemLocation location = {};
