std::ostream&
box_write (std::ostream& os,
           const int * smallend,
           const int * bigend,
           const int * type,
           int dim)
{
    os << '(';
    T_vector_write(os, smallend, dim) << ' ';
    T_vector_write(os, bigend, dim) << ' ';
    T_vector_write(os, type, dim) << ')';

    if (os.fail()) {
        amrex::Error("operator<<(ostream&,Box&) failed");
    }

    return os;
}

std::istream&
box_read (std::istream& is,
          int * smallend,
          int * bigend,
          int * type,
          int dim)
{
    is >> std::ws;
    char c;
    is >> c;

    for (int i=0; i<dim; ++i) {
        type[i] = 0;
    }

    if (c == '(')
    {
        T_vector_read(is, smallend, dim);
        T_vector_read(is, bigend, dim);
        is >> c;
        // Read an optional IndexType
        is.putback(c);
        if ( c == '(' )
        {
            T_vector_read(is, type, dim);
        }
        is.ignore(BL_IGNORE_MAX,')');
    }
    else if (c == '<')
    {
        is.putback(c);
        T_vector_read(is, smallend, dim);
        T_vector_read(is, bigend, dim);
        is >> c;
        // Read an optional IndexType
        is.putback(c);
        if ( c == '<' )
        {
            T_vector_read(is, type, dim);
        }
        //is.ignore(BL_IGNORE_MAX,'>');
    }
    else
    {
        amrex::Error("operator>>(istream&,Box&): expected \'(\'");
    }

    if (is.fail()) {
        amrex::Error("operator>>(istream&,Box&) failed");
    }

    return is;
}

