        int maxlen = length(0);
        dir = 0;
        for (int i = 1; i < dim; i++)
        {
            if (length(i) > maxlen)
            {
                maxlen = length(i);
                dir = i;
            }
        }
        return maxlen;
    }

//! Return length of longest side.  Ignores type.
    [[nodiscard]] AMREX_GPU_HOST_DEVICE
