    */
    AMREX_GPU_HOST_DEVICE
    BoxND& growLo (int idir, int n_cell = 1) noexcept { smallend.shift(idir, -n_cell); return *this; }

/**
    * \brief Grow on the low end by \p n_cell cells in direction \p d (negative shrinks).
