/**
 * \ingroup amrex_index_space
 * \brief Return the BoxND of length \p len on the low boundary of \p b
 * along coordinate direction \p dir.
 *
 * The returned BoxND is NODE based in direction \p dir and identical to \p b
 * in the other directions.
 * \param b Input Box.
 * \param dir Coordinate direction.
 * \param len Length of the boundary box in direction \p dir.
 */
template<int dim>
[[nodiscard]]
AMREX_GPU_HOST_DEVICE
AMREX_FORCE_INLINE
BoxND<dim> bdryLo (const BoxND<dim>& b, int dir, int len=1) noexcept
{
    IntVectND<dim> low(b.smallEnd());
    IntVectND<dim> hi(b.bigEnd());
    int sm = low[dir];
    low.setVal(dir,sm-len+1);
    hi.setVal(dir,sm);
    //
    // set dir'th bit to 1 = IndexType::NODE.
    //
    IndexTypeND<dim> typ(b.ixType());
    typ.set(dir);
    return BoxND<dim>(low,hi,typ);
}

/**
 * \ingroup amrex_index_space
 * \brief Return the BoxND of length \p len on the high boundary of \p b
 * along coordinate direction \p dir.
 *
 * The returned BoxND is NODE based in direction \p dir and identical to \p b
 * in the other directions.
 * \param b Input Box.
 * \param dir Coordinate direction.
 * \param len Length of the boundary box in direction \p dir.
 */
template<int dim>
[[nodiscard]]
AMREX_GPU_HOST_DEVICE
AMREX_FORCE_INLINE
BoxND<dim> bdryHi (const BoxND<dim>& b, int dir, int len=1) noexcept
{
    IntVectND<dim> low(b.smallEnd());
    IntVectND<dim> hi(b.bigEnd());
    auto const bitval = b.type()[dir];
    int bg = hi[dir]  + 1 - bitval%2;
    low.setVal(dir,bg);
    hi.setVal(dir,bg+len-1);
    //
    // Set dir'th bit to 1 = IndexType::NODE.
    //
    IndexTypeND<dim> typ(b.ixType());
    typ.set(dir);
    return BoxND<dim>(low,hi,typ);
}

/**
 * \ingroup amrex_index_space
 * \brief Similar to bdryLo and bdryHi except that it operates on the
 * given face of BoxND \p b.
 *
 * The returned BoxND is NODE based in the face direction and identical to \p b
 * in the other directions.
 * \param b Input Box.
 * \param face The face of \p b to operate on.
 * \param len Length of the boundary box along the face direction.
 */
template<int dim>
[[nodiscard]]
AMREX_GPU_HOST_DEVICE
AMREX_FORCE_INLINE
BoxND<dim> bdryNode (const BoxND<dim>& b, Orientation face, int len=1) noexcept
{
    int dir = face.coordDir();
    IntVectND<dim> low(b.smallEnd());
    IntVectND<dim> hi(b.bigEnd());
    if (face.isLow())
    {
        int sm = low[dir];
        low.setVal(dir,sm-len+1);
        hi.setVal(dir,sm);
    }
    else
    {
        int bitval = b.type()[dir];
        int bg = hi[dir]  + 1 - bitval%2;
        low.setVal(dir,bg);
        hi.setVal(dir,bg+len-1);
    }
    //
    // Set dir'th bit to 1 = IndexType::NODE.
    //
    IndexTypeND<dim> typ(b.ixType());
    typ.set(dir);
    return BoxND<dim>(low,hi,typ);
}

/**
 * \ingroup amrex_index_space
 * \brief Return the BoxND of length \p len adjacent to \p b on the low end
 * along coordinate direction \p dir.
 *
 * The returned BoxND is CELL based in direction \p dir and identical to \p b
 * in the other directions.
 * \param b Input Box.
 * \param dir Coordinate direction.
 * \param len Length of the adjacent box in direction \p dir.
 */
template<int dim>
[[nodiscard]]
AMREX_GPU_HOST_DEVICE
AMREX_FORCE_INLINE
BoxND<dim> adjCellLo (const BoxND<dim>& b, int dir, int len=1) noexcept
{
    BL_ASSERT(len > 0);
    IntVectND<dim> low(b.smallEnd());
    IntVectND<dim> hi(b.bigEnd());
    int sm = low[dir];
    low.setVal(dir,sm - len);
    hi.setVal(dir,sm - 1);
    //
    // Set dir'th bit to 0 = IndexType::CELL.
    //
    IndexTypeND<dim> typ(b.ixType());
    typ.unset(dir);
    return BoxND<dim>(low,hi,typ);
}

