void
BARef::define (std::istream& is, int& ndims)
{
    //
    // TODO -- completely remove the fiction of a hash value.
    //
    BL_ASSERT(m_abox.empty());
    int   maxbox;
    ULong tmphash;
    is.ignore(bl_ignore_max, '(') >> maxbox >> tmphash;
    AMREX_ASSERT(maxbox >= 0 && maxbox < std::numeric_limits<int>::max());
    resize(maxbox);
    auto pos = is.tellg();
    ndims = AMREX_SPACEDIM;
    if (maxbox > 0) { // No box to probe otherwise, and we would hit EOF.
        char c1, c2;
        int itmp;
        is >> std::ws >> c1 >> std::ws >> c2;
        if (c1 == '(' && c2 == '(') {
            is >> itmp;
            ndims = 1;
#if (AMREX_SPACEDIM >= 2)
            is >> std::ws;
            int ic = is.peek();
            if (ic == static_cast<int>(',')) {
                is.ignore(BL_IGNORE_MAX, ',');
                is >> itmp;
                ++ndims;
#if (AMREX_SPACEDIM == 3)
                is >> std::ws;
                ic = is.peek();
                if (ic == static_cast<int>(',')) {
                    ++ndims;
                }
#endif
            }
#endif
        }
    }
    is.seekg(pos, std::ios_base::beg);
    for (auto& b : m_abox) {
        is >> b;
    }
    is.ignore(bl_ignore_max, ')');
    if (is.fail()) {
        amrex::Error("BoxArray::define(istream&) failed");
    }
}

