    AMREX_ASSERT(bl.ixType() == ixType());
    if ((! m_bat.is_simple()) || (crseRatio() != IntVect::TheUnitVector())) {
        m_simplified_list.reset();
    }
    std::shared_ptr<BoxList> bak;
    bak.swap(m_simplified_list);
    define(std::move(bl));
