bool
BoxArray::ok () const
{
    const int N = static_cast<int>(size());
    if (N > 0)
    {
        auto const& bxs = this->m_ref->m_abox;
        if (m_bat.is_null()) {
            for (int i = 0; i < N; ++i) {
                if (! bxs[i].ok()) { return false; }
            }
        } else if (m_bat.is_simple()) {
            IndexType t = ixType();
            IntVect cr = crseRatio();
            for (int i = 0; i < N; ++i) {
                if (! amrex::convert(amrex::coarsen(bxs[i],cr),t).ok()) { return false; }
            }
        } else {
            for (int i = 0; i < N; ++i) {
                if (! m_bat.m_op.m_bndryReg(bxs[i]).ok()) { return false; }
            }
        }
    }
    return true;
}

bool
BoxArray::isDisjoint () const
{
    std::vector< std::pair<int,Box> > isects;

    const int N = static_cast<int>(size());
    auto const& bxs = this->m_ref->m_abox;
    if (m_bat.is_null()) {
        for (int i = 0; i < N; ++i) {
            intersections(bxs[i],isects);
            if ( isects.size() > 1 ) { return false; }
        }
    } else if (m_bat.is_simple()) {
        IndexType t = ixType();
        IntVect cr = crseRatio();
        for (int i = 0; i < N; ++i) {
            intersections(amrex::convert(amrex::coarsen(bxs[i],cr),t), isects);
            if ( isects.size() > 1 ) { return false; }
        }
    } else {
        for (int i = 0; i < N; ++i) {
            intersections(m_bat.m_op.m_bndryReg(bxs[i]), isects);
            if ( isects.size() > 1 ) { return false; }
        }
    }

    return true;
}

BoxList
BoxArray::boxList () const
{
    const int N = static_cast<int>(size());
    BoxList newb;
    newb.data().reserve(N);
    if (N > 0) {
        newb.set(ixType());
        auto const& bxs = this->m_ref->m_abox;
        if (m_bat.is_null()) {
            for (int i = 0; i < N; ++i) {
                newb.push_back(bxs[i]);
            }
        } else if (m_bat.is_simple()) {
            IndexType t = ixType();
            IntVect cr = crseRatio();
            for (int i = 0; i < N; ++i) {
                newb.push_back(amrex::convert(amrex::coarsen(bxs[i],cr),t));
            }
        } else {
            for (int i = 0; i < N; ++i) {
                newb.push_back(m_bat.m_op.m_bndryReg(bxs[i]));
            }
        }
    }
    return newb;
}

bool
BoxArray::contains (const IntVect& iv) const
{
    if (size() > 0) {
        return intersects(Box(iv,iv,ixType()));
    } else {
        return false;
    }
}

bool
BoxArray::contains (const Box& b, bool assume_disjoint_ba, const IntVect& ng) const
{
    if (size() > 0)
    {
        BL_ASSERT(ixType() == b.ixType());

        std::vector< std::pair<int,Box> > isects;

        intersections(b,isects,false,ng);

        if (!isects.empty())
        {
            if (assume_disjoint_ba && ng == 0) {
                Long nbx = b.numPts(), nisects = 0L;
                for (auto const& is : isects) {
                    nisects += is.second.numPts();
                }
                return (nbx == nisects);
            } else {
                BoxList bl(ixType());
                bl.reserve(isects.size());
                for (auto const& is : isects) {
                    bl.push_back(is.second);
                }
                auto const& blin = amrex::complementIn(b, bl);
                return blin.isEmpty();
            }
        } else {
            return false;
        }
    } else {
        return false;
    }
}

bool
BoxArray::contains (const BoxArray& ba, bool assume_disjoint_ba, const IntVect& ng) const
{
    if (size() == 0) { return false; }

    if (!minimalBox().grow(ng).contains(ba.minimalBox())) { return false; }

    for (int i = 0, N = static_cast<int>(ba.size()); i < N; ++i) {
        if (!contains(ba[i],assume_disjoint_ba, ng)) {
            return false;
        }
    }

    return true;
}

bool
BoxArray::contains (const BoxArray& ba, Periodicity const& period) const
{
    if (size() == 0) { return false; }

    if (! period.isAnyPeriodic()) { return contains(ba); }

    auto const& pshifts = period.shiftIntVect();

    std::vector< std::pair<int,Box> > isects;
    BoxList bl(ba.ixType());

    for (int i = 0, N = static_cast<int>(ba.size()); i < N; ++i) {
        Box const& b = ba[i];
        bl.clear();
        for (auto const& pit: pshifts) {
            intersections(b+pit, isects);
            for (auto const& is : isects) {
                bl.push_back(is.second - pit);
            }
        }
        BoxList const& left = amrex::complementIn(b, bl);
        if (left.isNotEmpty()) { return false; }
    }

    return true;
}

Box
BoxArray::minimalBox () const
{
    BL_ASSERT(m_bat.is_simple());
    Box minbox;
    const int N = static_cast<int>(size());
    if (N > 0)
    {
#ifdef AMREX_USE_OMP
        bool use_single_thread = omp_in_parallel();
        const int nthreads = use_single_thread ? 1 : omp_get_max_threads();
#else
        bool use_single_thread = true;
        const int nthreads = 1;
#endif
        if (use_single_thread)
        {
            minbox = m_ref->m_abox[0];
            for (int i = 1; i < N; ++i) {
                minbox.minBox(m_ref->m_abox[i]);
            }
        }
        else
        {
            Vector<Box> bxs(nthreads, m_ref->m_abox[0]);
#ifdef AMREX_USE_OMP
#pragma omp parallel
#endif
            {
                int tid = OpenMP::get_thread_num();
#ifdef AMREX_USE_OMP
#pragma omp for
#endif
                for (int i = 0; i < N; ++i) {
                    bxs[tid].minBox(m_ref->m_abox[i]);
                }
            }
            minbox = bxs[0];
            for (int i = 1; i < nthreads; ++i) {
                minbox.minBox(bxs[i]);
            }
        }
    }
    minbox.coarsen(crseRatio()).convert(ixType());
    return minbox;
}

Box
BoxArray::minimalBox (Long& npts_avg_box) const
{
    BL_ASSERT(m_bat.is_simple());
    Box minbox;
    const int N = static_cast<int>(size());
    Long npts_tot = 0;
    if (N > 0)
    {
#ifdef AMREX_USE_OMP
        bool use_single_thread = omp_in_parallel();
        const int nthreads = use_single_thread ? 1 : omp_get_max_threads();
#else
        bool use_single_thread = true;
        const int nthreads = 1;
#endif
        if (use_single_thread)
        {
            minbox = m_ref->m_abox[0];
            npts_tot += m_ref->m_abox[0].numPts();
            for (int i = 1; i < N; ++i) {
                minbox.minBox(m_ref->m_abox[i]);
                npts_tot += m_ref->m_abox[i].numPts();
            }
        }
        else
        {
            Vector<Box> bxs(nthreads, m_ref->m_abox[0]);
#ifdef AMREX_USE_OMP
#pragma omp parallel reduction(+:npts_tot)
#endif
            {
                int tid = OpenMP::get_thread_num();
#ifdef AMREX_USE_OMP
#pragma omp for
#endif
                for (int i = 0; i < N; ++i) {
                    bxs[tid].minBox(m_ref->m_abox[i]);
                    Long npts = m_ref->m_abox[i].numPts();
                    npts_tot += npts;
                }
            }
            minbox = bxs[0];
            for (int i = 1; i < nthreads; ++i) {
                minbox.minBox(bxs[i]);
            }
        }
    }
    auto cr = crseRatio();
    minbox.coarsen(cr).convert(ixType());
    npts_tot /= AMREX_D_TERM(Long(cr[0]),*cr[1],*cr[2]);
    npts_avg_box = (N > 0) ? npts_tot / N : 0L;
    return minbox;
}

