        AMREX_PRAGMA_SIMD
        for (int i = 0; i < len; i++)
        {
            Real r = vc[i];
            vc[i] = 0.5_rt*r*r;
        }
    }
    else if (c_sys == SPHERICAL)
    {
        if (dir == 0)
        {
            int len = static_cast<int>(vc.size());
            AMREX_PRAGMA_SIMD
            for (int i = 0; i < len; i++)
            {
                Real r = vc[i];
                vc[i] = r*r*r/3.0_rt;
            }
        }
        else
        {
