        }
    }
    else if (c_sys == SPHERICAL) {
        int len = static_cast<int>(vc.size());
        AMREX_PRAGMA_SIMD
        for (int i = 0; i < len; i++) {
            Real r = vc[i];
            vc[i] = static_cast<Real>(FOURPI/3.)*r*r*r;
        }
    }
#endif
}

std::ostream&
operator<< (std::ostream&   os,
            const CoordSys& c)
{
    os << '(' << (int) c.Coord() << ' ';
    os << AMREX_D_TERM( '(' << c.Offset(0) , <<
                  ',' << c.Offset(1) , <<
                  ',' << c.Offset(2))  << ')';
    os << AMREX_D_TERM( '(' << c.CellSize(0) , <<
                  ',' << c.CellSize(1) , <<
                  ',' << c.CellSize(2))  << ')';
    os << ' ' << int(c.ok) << ")\n";
    return os;
}

std::istream&
operator>> (std::istream& is,
            CoordSys&     c)
{
    int coord;
    is.ignore(BL_IGNORE_MAX, '(') >> coord;
    c.c_sys = (CoordSys::CoordType) coord;
    AMREX_D_EXPR(is.ignore(BL_IGNORE_MAX, '(') >> c.offset[0],
                 is.ignore(BL_IGNORE_MAX, ',') >> c.offset[1],
                 is.ignore(BL_IGNORE_MAX, ',') >> c.offset[2]);
    is.ignore(BL_IGNORE_MAX, ')');
    Real cellsize[3];
    AMREX_D_EXPR(is.ignore(BL_IGNORE_MAX, '(') >> cellsize[0],
                 is.ignore(BL_IGNORE_MAX, ',') >> cellsize[1],
                 is.ignore(BL_IGNORE_MAX, ',') >> cellsize[2]);
    is.ignore(BL_IGNORE_MAX, ')');
    int tmp;
    is >> tmp;
    c.ok = tmp?true:false;
    is.ignore(BL_IGNORE_MAX, '\n');
    for (int k = 0; k < AMREX_SPACEDIM; k++)
    {
        c.dx[k] = cellsize[k];
        c.inv_dx[k] = 1.0_rt/cellsize[k];
    }
    return is;
}

Real
CoordSys::Volume (const IntVect& point) const
{
    Real xhi[AMREX_SPACEDIM];
    Real xlo[AMREX_SPACEDIM];
    HiNode(point,xhi);
    LoNode(point,xlo);
    return Volume(xlo,xhi);
}

Real
CoordSys::Volume (const Real xlo[AMREX_SPACEDIM],
                  const Real xhi[AMREX_SPACEDIM]) const
{
    switch (c_sys)
    {
    case cartesian:
        return AMREX_D_TERM((xhi[0]-xlo[0]),
                            *(xhi[1]-xlo[1]),
                            *(xhi[2]-xlo[2]));
#if (AMREX_SPACEDIM==1)
    case RZ:
        return static_cast<Real>(0.5*TWOPI)*(xhi[0]*xhi[0]-xlo[0]*xlo[0]);
    case SPHERICAL:
        return static_cast<Real>(FOURPI/3.)*(xhi[0]-xlo[0]) *
            (xhi[0]*xhi[0]+xhi[0]*xlo[0]+xlo[0]*xlo[0]);
#endif
#if (AMREX_SPACEDIM==2)
    case RZ:
        return static_cast<Real>(0.5*TWOPI)*(xhi[1]-xlo[1])*(xhi[0]*xhi[0]-xlo[0]*xlo[0]);
    case SPHERICAL:
        return static_cast<Real>(TWOPI/3.)*(std::cos(xlo[1])-std::cos(xhi[1])) *
            (xhi[0]-xlo[0])*(xhi[0]*xhi[0]+xhi[0]*xlo[0]+xlo[0]*xlo[0]);
#endif
    default:
        AMREX_ASSERT(0);
    }
    return 0;
}

Real
CoordSys::AreaLo (const IntVect& point, int dir) const noexcept // NOLINT(readability-convert-member-functions-to-static)
{
    amrex::ignore_unused(point,dir);
#if (AMREX_SPACEDIM==1)
    AMREX_ASSERT(dir == 0);
    Real xlo[AMREX_SPACEDIM];
    switch (c_sys)
    {
    case cartesian:
        return 1._rt;
    case RZ:
        LoNode(point,xlo);
        return Real(TWOPI)*xlo[0];
    case SPHERICAL:
        LoNode(point,xlo);
        return Real(FOURPI)*xlo[0]*xlo[0];
    default:
        AMREX_ASSERT(0);
    }
#endif
#if (AMREX_SPACEDIM==2)
    Real xlo[AMREX_SPACEDIM];
    switch (c_sys)
    {
    case cartesian:
        switch (dir)
        {
        case 0: return dx[1];
        case 1: return dx[0];
        default:
            AMREX_ASSERT(0);
        }
        return 0._rt; // to silent compiler warning
    case RZ:
        LoNode(point,xlo);
        switch (dir)
        {
        case 0: return Real(TWOPI)*dx[1]*xlo[0];
        case 1: return ((xlo[0]+dx[0])*(xlo[0]+dx[0])-xlo[0]*xlo[0])*static_cast<Real>(0.5*TWOPI);
        default:
            AMREX_ASSERT(0);
        }
        return 0._rt; // to silent compiler warning
    case SPHERICAL:
        LoNode(point,xlo);
        switch (dir)
        {
        case 0: return Real(TWOPI)*xlo[0]*xlo[0]*(std::cos(xlo[1]) - std::cos(xlo[1]+dx[1]));
        case 1: return (xlo[0]+xlo[0]+dx[0])*dx[0]*std::sin(xlo[1])*static_cast<Real>(0.5*TWOPI);
        default:
            AMREX_ASSERT(0);
        }
        return 0._rt; // to silent compiler warning
    default:
        AMREX_ASSERT(0);
    }
#endif
#if (AMREX_SPACEDIM==3)
    switch (dir)
    {
    case 0: return dx[1]*dx[2];
    case 1: return dx[0]*dx[2];
    case 2: return dx[1]*dx[0];
    default:
        AMREX_ASSERT(0);
    }
#endif
    return 0;
}

Real
CoordSys::AreaHi (const IntVect& point, int dir) const noexcept // NOLINT(readability-convert-member-functions-to-static)
{
    amrex::ignore_unused(point,dir);
#if (AMREX_SPACEDIM==1)
    AMREX_ASSERT(dir == 0);
    Real xhi[AMREX_SPACEDIM];
    switch (c_sys)
    {
    case cartesian:
        return 1._rt;
    case RZ:
        HiNode(point,xhi);
        return Real(TWOPI)*xhi[0];
    case SPHERICAL:
        HiNode(point,xhi);
        return Real(FOURPI)*xhi[0]*xhi[0];
    default:
        AMREX_ASSERT(0);
    }
#endif
#if (AMREX_SPACEDIM==2)
    Real xhi[AMREX_SPACEDIM];
    switch (c_sys)
    {
    case cartesian:
        switch (dir)
        {
        case 0: return dx[1];
        case 1: return dx[0];
        default:
            AMREX_ASSERT(0);
        }
        return 0._rt; // to silent compiler warning
    case RZ:
        HiNode(point,xhi);
        switch (dir)
        {
        case 0: return Real(TWOPI)*dx[1]*xhi[0];
        case 1: return (xhi[0]*xhi[0]-(xhi[0]-dx[0])*(xhi[0]-dx[0]))*static_cast<Real>(TWOPI*0.5);
        default:
            AMREX_ASSERT(0);
        }
        return 0._rt; // to silent compiler warning
    case SPHERICAL:
        HiNode(point,xhi);
        switch (dir)
        {
        case 0: return Real(TWOPI)*xhi[0]*xhi[0]*(std::cos(xhi[1]-dx[1]) - std::cos(xhi[1]));
        case 1: return (xhi[0]+xhi[0]-dx[0])*dx[0]*std::sin(xhi[1])*static_cast<Real>(0.5*TWOPI);
        default:
            AMREX_ASSERT(0);
        }
        return 0._rt; // to silent compiler warning
    default:
        AMREX_ASSERT(0);
    }
#endif
#if (AMREX_SPACEDIM==3)
    switch (dir)
    {
    case 0: return dx[1]*dx[2];
    case 1: return dx[0]*dx[2];
    case 2: return dx[1]*dx[0];
    default:
        AMREX_ASSERT(0);
    }
#endif
    return 0._rt;
}

/**
 * \class amrex::CoordSys
 * \ingroup amrex_real_space
 * \brief Coordinate system; provides mapping between physical space and index space.
 *
 * Supports Cartesian, cylindrical (RZ), and spherical coordinate systems.
 */
class CoordSys
{
public:

    //! Coordinate system type: undefined, Cartesian, cylindrical (RZ), or spherical.
    enum CoordType { undef = -1, cartesian = 0, RZ = 1, SPHERICAL = 2 };
    //! Nice ASCII output.
    friend std::ostream& operator<< (std::ostream&, const CoordSys& );

    //! Nice ASCII input.
    friend std::istream& operator>> (std::istream&, CoordSys& );

    //! Is ok?
    [[nodiscard]] bool Ok () const noexcept { return ok; }

    //! Set the CoordType.
    void SetCoord (CoordType coord) noexcept { c_sys = coord; }

    //! Returns the CoordType.
    [[nodiscard]] CoordType Coord () const noexcept { return c_sys; }

    //! Returns the CoordType as an int.
    [[nodiscard]] int CoordInt () const  noexcept { return static_cast<int>(c_sys); }

    //! Is CoordType == SPHERICAL?
    [[nodiscard]] bool IsSPHERICAL () const noexcept {
        BL_ASSERT(c_sys != undef); return (c_sys == SPHERICAL);
    }

    //! Is CoordType == RZ?
    [[nodiscard]] bool IsRZ () const noexcept {
        BL_ASSERT(c_sys != undef); return (c_sys == RZ);
    }

    //! Is CoordType == cartesian?
    [[nodiscard]] bool IsCartesian () const noexcept {
        BL_ASSERT(c_sys != undef); return (c_sys == cartesian);
    }

    //! Sets the offset for each coordinate direction.
    void SetOffset (const Real* x_lo) noexcept;

    //! Returns the offset.
    [[nodiscard]] const Real* Offset () const noexcept { return offset; }

    //! Returns the offset for the specified coordinate direction.
    [[nodiscard]] Real Offset (int dir) const noexcept { return offset[dir]; }

    //! Returns the cellsize for each coordinate direction.
    [[nodiscard]] const Real* CellSize () const noexcept { BL_ASSERT(ok); return dx; }

//! Returns the cellsize for each coordinate direction.
[[nodiscard]] const Real* CellSize () const noexcept { BL_ASSERT(ok); return dx; }

//! Returns the cellsize for the specified coordinate direction.
[[nodiscard]] Real CellSize (int dir) const noexcept { BL_ASSERT(ok); return dx[dir]; }

//! Returns the cell sizes as a GpuArray for use on host or device.
[[nodiscard]] GpuArray<Real,AMREX_SPACEDIM> CellSizeArray () const noexcept {
    BL_ASSERT(ok);
    return {{ AMREX_D_DECL(dx[0],dx[1],dx[2]) }};
}

//! Returns the inverse cellsize for each coordinate direction.
[[nodiscard]] const Real* InvCellSize () const noexcept { BL_ASSERT(ok); return inv_dx; }

//! Returns the inverse cellsize for the specified coordinate direction.
[[nodiscard]] Real InvCellSize (int dir) const noexcept { BL_ASSERT(ok); return inv_dx[dir]; }

