AMREX_GPU_HOST_DEVICE
inline
void
amrex_setvol (Box const& bx, Array4<Real> const& vol,
              GpuArray<Real,1> const& offset,
              GpuArray<Real,1> const& dx, const int coord) noexcept
{
    const auto lo = amrex::lbound(bx);
    const auto hi = amrex::ubound(bx);

    if (coord == 0) // Cartesian
    {
        Real dv = dx[0];
        AMREX_PRAGMA_SIMD
        for (int i = lo.x; i <= hi.x; ++i) {
            vol(i,0,0) = dv;
        }
    }
    else if (coord == 1)
    {
        const Real pi = std::numbers::pi_v<Real>;
        AMREX_PRAGMA_SIMD
        for (int i = lo.x; i <= hi.x; ++i) {
            Real ri = offset[0] + dx[0]*i;
            Real ro = ri + dx[0];
            Real v = pi*(ro-ri)*(ro + ri);
            vol(i,0,0) = std::abs(v);
        }
    }
    else
    {
        const Real pi = std::numbers::pi_v<Real>;
        AMREX_PRAGMA_SIMD
        for (int i = lo.x; i <= hi.x; ++i) {
            Real ri = offset[0] + dx[0]*i;
            Real ro = ri + dx[0];
            Real v = (Real(4./3.)*pi)*(ro-ri)*(ro*ro+ro*ri+ri*ri);
            vol(i,0,0) = std::abs(v);
        }
    }
}

AMREX_GPU_HOST_DEVICE
inline
void
amrex_setarea (Box const& bx, Array4<Real> const& area,
               GpuArray<Real,1> const& offset,
               GpuArray<Real,1> const& dx, const int /*dir*/, const int coord) noexcept
{
    const auto lo = amrex::lbound(bx);
    const auto hi = amrex::ubound(bx);

    if (coord == 0)
    {
        AMREX_PRAGMA_SIMD
        for (int i = lo.x; i <= hi.x; ++i) {
            area(i,0,0) = 1.0;
        }
    }
    else if (coord == 1)
    {
        const Real pi = std::numbers::pi_v<Real>;
        AMREX_PRAGMA_SIMD
        for (int i = lo.x; i <= hi.x; ++i) {
            Real ri = offset[0] + dx[0]*i;
            Real a = (Real(2.)*pi)*ri;
            area(i,0,0) = std::abs(a);
        }
    }
    else
    {
        const Real pi = std::numbers::pi_v<Real>;
        AMREX_PRAGMA_SIMD
        for (int i = lo.x; i <= hi.x; ++i) {
            Real ri = offset[0] + dx[0]*i;
            Real a = (Real(4.0)*pi)*ri*ri;
            area(i,0,0) = std::abs(a);
        }
    }
}

AMREX_GPU_HOST_DEVICE
inline
void
amrex_setdloga (Box const& bx, Array4<Real> const& dloga,
                GpuArray<Real,1> const& offset,
                GpuArray<Real,1> const& dx, const int /*dir*/, const int coord) noexcept
{
    const auto lo = amrex::lbound(bx);
    const auto hi = amrex::ubound(bx);

    if (coord == 0)
    {
        AMREX_PRAGMA_SIMD
        for (int i = lo.x; i <= hi.x; ++i) {
            dloga(i,0,0) = 0.0;
        }
    }
    else if (coord == 1)
    {
        AMREX_PRAGMA_SIMD
        for (int i = lo.x; i <= hi.x; ++i) {
            Real rc = offset[0] + dx[0]*(i+Real(0.5));
            dloga(i,0,0) = Real(1.0)/rc;
        }
    }
    else
    {
        AMREX_PRAGMA_SIMD
        for (int i = lo.x; i <= hi.x; ++i) {
            Real ri = offset[0] + dx[0]*(i+Real(0.5));
            dloga(i,0,0) = Real(2.0)/ri;
        }
    }
}

AMREX_GPU_HOST_DEVICE
inline
void
amrex_setvol (Box const& bx, Array4<Real> const& vol,
              GpuArray<Real,2> const& offset,
              GpuArray<Real,2> const& dx, const int coord) noexcept
{
    const auto lo = amrex::lbound(bx);
    const auto hi = amrex::ubound(bx);

    if (coord == 0) // Cartesian
    {
        Real dv = dx[0]*dx[1];
        for     (int j = lo.y; j <= hi.y; ++j) {
            AMREX_PRAGMA_SIMD
            for (int i = lo.x; i <= hi.x; ++i) {
                vol(i,j,0) = dv;
            }
        }
    }
    else if (coord == 1) // r-z
    {
        const Real pi = std::numbers::pi_v<Real>;
        for     (int j = lo.y; j <= hi.y; ++j) {
            AMREX_PRAGMA_SIMD
            for (int i = lo.x; i <= hi.x; ++i) {
                Real ri = offset[0] + dx[0]*Real(i);
                Real ro = ri + dx[0];
                Real v = pi*dx[1]*dx[0]*(ro + ri);
                vol(i,j,0) = std::abs(v);
            }
        }
    }
    else // r-theta
    {
        const Real pi = std::numbers::pi_v<Real>;
        for     (int j = lo.y; j <= hi.y; ++j) {
            Real ti = offset[1] + dx[1]*Real(j);
            Real to = ti + dx[1];
            Real tmp = (Real(2.)*pi)*(std::cos(ti)-std::cos(to))/Real(3.0);
            AMREX_PRAGMA_SIMD
            for (int i = lo.x; i <= hi.x; ++i) {
                Real ri = offset[0] + dx[0]*Real(i);
                Real ro = ri + dx[0];
                Real v = tmp*(ro-ri)*(ro*ro+ro*ri+ri*ri);
                vol(i,j,0) = std::abs(v);
            }
        }
    }
}

