            }
        }
    }
    else if (coord == 1)
    {
        if (dir == 0)
        {
            for     (int j = lo.y; j <= hi.y; ++j) {
                AMREX_PRAGMA_SIMD
                for (int i = lo.x; i <= hi.x; ++i) {
                    Real rc = offset[0] + dx[0]*(Real(i)+Real(0.5));
                    dloga(i,j,0) = Real(1.0)/rc;
                }
            }
        }
        else
        {
            for     (int j = lo.y; j <= hi.y; ++j) {
                AMREX_PRAGMA_SIMD
                for (int i = lo.x; i <= hi.x; ++i) {
                    dloga(i,j,0) = Real(0.0);
                }
            }
        }
    }
    else
    {
        if (dir == 0)
        {
            for     (int j = lo.y; j <= hi.y; ++j) {
                AMREX_PRAGMA_SIMD
                for (int i = lo.x; i <= hi.x; ++i) {
                    Real rc = offset[0] + dx[0]*(Real(i)+Real(0.5));
                    dloga(i,j,0) = Real(2.0)/rc;
