/**
 * \struct amrex::DataAllocator
 * \ingroup amrex_memory
 * \brief Lightweight allocator/deallocator backed by an Arena.
 *
 * Falls back to The_Arena() when no arena is supplied.
 */
struct DataAllocator {
    Arena* m_arena = nullptr; ///< Stored arena pointer (may be null).

    //! Default-construct; alloc/free will use The_Arena().
    DataAllocator ()  noexcept  = default;

    //! Construct with an explicit arena \p ar.
    DataAllocator (Arena* ar) noexcept : m_arena(ar) {}

    //! Allocate \p sz bytes from the arena. Throws OutOfMemoryError on failure.
    [[nodiscard]] void* alloc (std::size_t sz) const {
        return arena()->alloc(sz);
    }

    //! Return the allocation at \p pt to the arena.
    void free (void* pt) const noexcept {
        arena()->free(pt);
    }

    //! Return the stored arena, or The_Arena() if none was set.
    [[nodiscard]] Arena* arena () const noexcept {
        return (m_arena) ? m_arena : The_Arena();
    }
}

/**
 * \struct amrex::DataDeleter
 * \ingroup amrex_memory
 * \brief Custom deleter that returns memory to an Arena.
 *
 * Falls back to The_Arena() when no arena is supplied.
 */
struct DataDeleter {
    Arena* m_arena = nullptr; ///< Stored arena pointer (may be null).
    //! Default-construct; operator() will use The_Arena().
    DataDeleter () noexcept  = default;
    //! Construct with an explicit arena \p ar.
    DataDeleter (Arena* ar) noexcept : m_arena(ar) {}
    //! Return the stored arena, or The_Arena() if none was set.
    [[nodiscard]] Arena* arena () const noexcept { return (m_arena) ? m_arena : The_Arena(); }
    //! Return the allocation at \p pt to the arena.
    void operator() (void* pt) const noexcept { arena()->free(pt); }
}

/**
 * \brief Demangle C++ name
 *
 * Demange C++ name if possible. For example
 * \code{.cpp}
 *     amrex::Box box;
 *     std::cout << amrex::demangle(typeid(box).name());
 * \endcode
 * Demangling turns "N5amrex3BoxE" into "amrex::Box".
 * \param name Mangled identifier returned by \c typeid or similar APIs.
 */
inline std::string demangle (const char* name)
{
#ifdef AMREX_USE_CXXABI
    int status;
    char* p = abi::__cxa_demangle(name, nullptr, nullptr, &status);
    if (p) {
        std::string s(p);
        std::free(p);
        return s;
    } else
#endif
    {
        return name;
    }
}

/**
 * \brief Return the dot product of two XDim3 structs.
 * \param a First operand.
 * \param b Second operand.
 */
AMREX_GPU_HOST_DEVICE AMREX_FORCE_INLINE
Real dot_product (XDim3 const& a, XDim3 const& b)
{
    return a.x*b.x + a.y*b.y + a.z*b.z;
}

/**
 * \brief Return the cross product of two XDim3 structs.
 * \param a First operand.
 * \param b Second operand.
 */
AMREX_GPU_HOST_DEVICE AMREX_FORCE_INLINE
XDim3 cross_product (XDim3 const& a, XDim3 const& b)
{
    return XDim3{.x = a.y*b.z-a.z*b.y, .y = a.z*b.x-a.x*b.z, .z = a.x*b.y-a.y*b.x};
}

/**
 * \brief Component-wise addition of two XDim3 structs.
 * \param a First operand.
 * \param b Second operand.
 */
AMREX_GPU_HOST_DEVICE AMREX_FORCE_INLINE
XDim3 operator+ (XDim3 const& a, XDim3 const& b)
{
    return XDim3{.x = a.x + b.x, .y = a.y + b.y, .z = a.z + b.z};
}

/**
 * \brief Component-wise subtraction of two XDim3 structs.
 * \param a Minuend vector.
 * \param b Subtrahend vector.
 */
AMREX_GPU_HOST_DEVICE AMREX_FORCE_INLINE
XDim3 operator- (XDim3 const& a, XDim3 const& b)
{
    return XDim3{.x = a.x - b.x, .y = a.y - b.y, .z = a.z - b.z};
}

/**
 * \brief Write a Dim3 or XDim3 to an output stream in \c (x,y,z) format.
 * \param os Stream receiving formatted output.
 * \param d  Coordinate tuple to print.
 */
template <typename T>
requires (std::same_as<T, Dim3> || std::same_as<T, XDim3>)
std::ostream& operator<< (std::ostream& os, const T& d)
{
    os << '(' << d.x << ',' << d.y << ',' << d.z << ')';
    return os;
}

