}

void
DistributionMapping::RRSFCDoIt (const BoxArray&          boxes,
                                int                   /* nprocs */)
{
    BL_PROFILE("DistributionMapping::RRSFCDoIt()");

    int nprocs = ParallelContext::NProcsSub();

#if defined (BL_USE_TEAM)
    amrex::Abort("Team support is not implemented yet in RRSFC");
#endif

    const int nboxes = static_cast<int>(boxes.size());
    std::vector<SFCToken> tokens;
    tokens.reserve(nboxes);
    for (int i = 0; i < nboxes; ++i)
    {
        const Box& bx = boxes[i];
        tokens.push_back(makeSFCToken(i, bx.smallEnd()));
    }
    //
    // Put'm in Morton space filling curve order.
    //
    std::ranges::sort(tokens, SFCToken::Compare());

    Vector<int> ord;

    LeastUsedCPUs(nprocs,ord);

    // Distribute boxes using round-robin
    for (int i = 0; i < nboxes; ++i) {
        m_ref->m_pmap[tokens[i].m_box] =
            ParallelContext::local_to_global_rank(ord[i%nprocs]);
    }
}

void
DistributionMapping::RRSFCProcessorMap (const BoxArray&          boxes,
                                        int                      nprocs)
{
    BL_ASSERT( ! boxes.empty());
    BL_ASSERT(m_ref.use_count() == 1); // fill in place, nobody else sees it
    m_ref->m_pmap.resize(boxes.size());

    RRSFCDoIt(boxes,nprocs);
}

Vector<Long>
DistributionMapping::ConvertCostRealToLong (const Vector<Real>& rcost)
{
    Vector<Long> cost(rcost.size());

    if (rcost.empty()) { return cost; }

    Real wmax = *std::ranges::max_element(rcost);
    Real scale = (wmax == 0) ? 1.e9_rt : 1.e9_rt/wmax;

    for (Long i = 0; i < rcost.size(); ++i) {
        cost[i] = Long(rcost[i]*scale) + 1L;
    }

    return cost;
}

