DistributionMapping MakeSimilarDM (const BoxArray& ba, const MultiFab& mf, const IntVect& ng)
{
    const DistributionMapping& mf_dm = mf.DistributionMap();
    const BoxArray& mf_ba = convert(mf.boxArray(),ba.ixType());
    return MakeSimilarDM(ba, mf_ba, mf_dm, ng);
}

DistributionMapping MakeSimilarDM (const BoxArray& ba, const BoxArray& src_ba,
                                   const DistributionMapping& src_dm, const IntVect& ng)
{
    AMREX_ASSERT_WITH_MESSAGE(ba.ixType() == src_ba.ixType(),
                              "input BoxArrays must have the same centering.");

    Vector<int> pmap(ba.size());
    for (int i = 0; i < std::ssize(ba); ++i) {
        Box box = ba[i];
        box.grow(ng);
        bool first_only = false;
        auto isects = src_ba.intersections(box, first_only, ng);
        if (isects.empty()) {
            // no intersection found, revert to round-robin
            int nprocs = ParallelContext::NProcsSub();
            pmap[i] = ParallelContext::local_to_global_rank(i % nprocs);
        } else {
            Long max_overlap = 0;
            int max_overlap_index = -1;
            for (const auto& isect : isects) {
                int gid = isect.first;
                const Box& isect_box = isect.second;
                if (isect_box.numPts() > max_overlap) {
                    max_overlap = isect_box.numPts();
                    max_overlap_index = gid;
                }
            }
            AMREX_ASSERT(max_overlap > 0 && max_overlap_index >= 0);
            pmap[i] = src_dm[max_overlap_index];
        }
    }
    return DistributionMapping(std::move(pmap));
}

/**
 * \class amrex::DistributionMapping
 * \ingroup amrex_domain_decomposition
 * \brief Calculates the distribution of FABs to MPI processes.
 *
 *  This class calculates the distribution of FABs to MPI processes in a
 *  FabArray in a multi-processor environment.  By distribution is meant what
 *  MPI process in the multi-processor environment owns what FAB.  Only the BoxArray
 *  on which the FabArray is built is used in determining the distribution.
 *  The four distribution strategies are round-robin, knapsack, SFC, and RRSFC.
 *  In the round-robin distribution, boxes are ordered from largest to smallest
 *  and assigned cyclically to ranks or teams, starting with those using the least
 *  FAB memory.  In the knapsack distribution the FABs are partitioned
 *  across CPUs such that the total volume of the Boxes in the underlying
 *  BoxArray are as equal across CPUs as is possible.  The SFC distribution is
 *  based on a space filling curve.  The RRSFC distribution orders boxes using
 *  an SFC and then assigns them in round-robin order to CPUs ordered from least
 *  to most FAB memory use.
 *
 *  Copies of a DistributionMapping share the mapping.  Like BoxArray::define,
 *  the define overloads and the ProcessorMap builders give the object a new
 *  mapping; copies made earlier keep the old one.
 */
class DistributionMapping
{
  public:

    template <typename T> friend class FabArray;
    friend class FabArrayBase;

    //! The distribution strategies
    enum Strategy { UNDEFINED = -1, ROUNDROBIN, KNAPSACK, SFC, RRSFC };

    struct Ref
    {
        //! Constructors to match those in DistributionMapping ....
        Ref () = default;

        explicit Ref (const Vector<int>& pmap) : m_pmap(pmap) {}

        explicit Ref (Vector<int>&& pmap) noexcept : m_pmap(std::move(pmap)) {}

        //! dtor, copy-ctor, copy-op=, move-ctor, and move-op= are compiler generated.

        Vector<int> m_pmap; //!< index array for all boxes

    //! dtor, copy-ctor, copy-op=, move-ctor, and move-op= are compiler generated.

    Vector<int> m_pmap; //!< index array for all boxes
    Vector<int> m_index_array;  //!< index array for local boxes owned by the team
    std::vector<bool> m_ownership; //!< true ownership
};

//! The default constructor.
DistributionMapping ();

