template <class FAB>
template <class F>
requires (BaseFabType<F>)
void
FabArray<FAB>::build_arrays () const
{
    using A = Array4<value_type>;
    using AC = Array4<value_type const>;
    static_assert(sizeof(A) == sizeof(AC), "sizeof(Array4<T>) != sizeof(Array4<T const>)");
    if (!m_hp_arrays && local_size() > 0) {
        const int n = local_size();
#ifdef AMREX_USE_GPU
        m_hp_arrays = (void*)The_Pinned_Arena()->alloc(n*2*sizeof(A));
        m_dp_arrays = (void*)The_Arena()->alloc(n*2*sizeof(A));
#else
        m_hp_arrays = std::malloc(n*2*sizeof(A));
#endif
        for (int li = 0; li < n; ++li) {
            if (m_fabs_v[li]) {
                new ((A*)m_hp_arrays+li) A(m_fabs_v[li]->array());
                new ((AC*)m_hp_arrays+li+n) AC(m_fabs_v[li]->const_array());
            } else {
                new ((A*)m_hp_arrays+li) A{};
                new ((AC*)m_hp_arrays+li+n) AC{};
            }
        }
        m_arrays.hp = (A*)m_hp_arrays;
        m_const_arrays.hp = (AC*)m_hp_arrays + n;
#ifdef AMREX_USE_GPU
        m_arrays.dp = (A*)m_dp_arrays;
        m_const_arrays.dp = (AC*)m_dp_arrays + n;
        Gpu::htod_memcpy_async(m_dp_arrays, m_hp_arrays, n*2*sizeof(A));
        // The pinned buffer is not modified after this point and is freed
        // in stream order by clear_arrays(), so kernels launched on the
        // current stream are correctly ordered after the copy without a
        // host sync. MFIter and StreamIter synchronize the current stream
        // before switching to other streams, so we only need to sync here
        // if we are already inside a multi-stream MFIter loop, where later
        // iterations may use the arrays on a different stream.
        if (!Gpu::inNoSyncRegion() && Gpu::numGpuStreams() > 1 &&
            MFIter::currentDepth() > 0)
        {
            Gpu::streamSynchronize();
        }
#endif
    }
}

template <class FAB>
void
FabArray<FAB>::clear_arrays ()
{
#ifdef AMREX_USE_GPU
    // The host-to-device copy of the Array4s issued in build_arrays() is
    // asynchronous and is not synchronized when we are in a NoSync region.
    // Use stream-ordered frees so that the pinned and device buffers are not
    // reused before the copy and any kernels using them have completed.
    if (m_hp_arrays) {
        Gpu::freeAsync(The_Pinned_Arena(), m_hp_arrays);
        Gpu::freeAsync(The_Arena(), m_dp_arrays);
    }
    m_dp_arrays = nullptr;
#else
    std::free(m_hp_arrays);
#endif
    m_hp_arrays = nullptr;
    m_arrays.hp = nullptr;
    m_const_arrays.hp = nullptr;
}

template <class FAB>
void
FabArray<FAB>::clear_fab_caches ()
{
    clear_arrays();
#ifdef AMREX_USE_GPU
    m_fb_local_copy_handler.clear();
    m_recv_copy_handler.clear();
    m_send_copy_handler.clear();
#endif
#ifdef AMREX_FB_UNPACK_ON_ARRIVAL
    m_fb_on_arrival_meta.clear();
#endif
}

template <class FAB>
[[nodiscard]]
FAB*
FabArray<FAB>::release (int K)
{
    const int li = localindex(K);
    if (li >= 0 && li < std::ssize(m_fabs_v) && m_fabs_v[li] != nullptr) {
        AMREX_ASSERT(m_single_chunk_arena == nullptr);
        Long nbytes = amrex::nBytesOwned(*m_fabs_v[li]);
        if (nbytes > 0) {
            for (auto const& t : m_tags) {
                updateMemUsage(t, -nbytes, nullptr);
            }
        }
        clear_fab_caches();
        return std::exchange(m_fabs_v[li], nullptr);
    } else {
        return nullptr;
    }
}

template <class FAB>
[[nodiscard]]
FAB*
FabArray<FAB>::release (const MFIter& mfi)
{
    const int li = mfi.LocalIndex();
    if (li >= 0 && li < std::ssize(m_fabs_v) && m_fabs_v[li] != nullptr) {
        AMREX_ASSERT(m_single_chunk_arena == nullptr);
        Long nbytes = amrex::nBytesOwned(*m_fabs_v[li]);
        if (nbytes > 0) {
            for (auto const& t : m_tags) {
