    // The lo-x/lo-y corner is filled by a 180 degree rotation.
    Array<Box,3> const domain_dst{loxbox, loybox, loxy_corner};
    auto const src_to_dst = amrex::makeTuple(NonLocalBC::Rotate90CounterClockWise{},
