template <class FAB>
template <typename BUF, class F>
requires (BaseFabType<F>)
void
FabArray<FAB>::FillBoundary_finish ()
{
#ifdef AMREX_USE_MPI

    BL_PROFILE("FillBoundary_finish()");
    BL_PROFILE_SYNC_STOP();

    if (!fbd) { return; }

#ifdef AMREX_FB_UNPACK_ON_ARRIVAL
    if (fbd->oa_meta) {
        FB_on_arrival_finish<BUF>();
        return;
    }
#endif

    const FB* TheFB = fbd->fb;
    bool sumboundary = TheFB->m_sb_snghost.allGE(0);
    const auto N_rcvs = static_cast<int>(TheFB->m_RcvTags->size());
    if (N_rcvs > 0)
    {
        Vector<const CopyComTagsContainer*> recv_cctc(N_rcvs,nullptr);
        for (int k = 0; k < N_rcvs; k++)
        {
            if (fbd->recv_size[k] > 0)
            {
                auto const& cctc = TheFB->m_RcvTags->at(fbd->recv_from[k]);
                recv_cctc[k] = &cctc;
            }
        }

        int actual_n_rcvs = N_rcvs - std::ranges::count(fbd->recv_data, nullptr);

        if (actual_n_rcvs > 0) {
            ParallelDescriptor::Waitall(fbd->recv_reqs, fbd->recv_stat);
#ifdef AMREX_DEBUG
            if (!CheckRcvStats(fbd->recv_stat, fbd->recv_size, fbd->tag))
            {
                amrex::Abort("FillBoundary_finish failed with wrong message size");
            }
#endif
        }

        bool is_thread_safe = TheFB->m_threadsafe_rcv;
        auto op = sumboundary ? FabArrayBase::ADD : FabArrayBase::COPY;

#ifdef AMREX_USE_GPU
        if (Gpu::inLaunchRegion())
        {
#if defined(__CUDACC__) && defined(AMREX_USE_CUDA)
            if (std::is_same_v<BUF,value_type> && Gpu::inGraphRegion() && !sumboundary)
            {
                FB_unpack_recv_buffer_cuda_graph(*TheFB, fbd->scomp, fbd->ncomp,
                                                 fbd->recv_data, fbd->recv_size,
                                                 recv_cctc, is_thread_safe);
            }
            else
#endif
            {
                bool deterministic = fbd->deterministic;

#endif
            {
                bool deterministic = fbd->deterministic;
                unpack_recv_buffer_gpu<BUF>(*this, fbd->scomp, fbd->ncomp, fbd->recv_data, fbd->recv_size,
                                            recv_cctc, op, is_thread_safe, TheFB->m_id, deterministic);
            }
        }
        else
#endif
        {
            unpack_recv_buffer_cpu<BUF>(*this, fbd->scomp, fbd->ncomp, fbd->recv_data, fbd->recv_size,
                                        recv_cctc, op, is_thread_safe);
        }

        if (fbd->the_recv_data)
        {
            if (Gpu::inNoSyncRegion()) {
                Gpu::freeAsync(amrex::The_Comms_Arena(), fbd->the_recv_data);
            } else {
                amrex::The_Comms_Arena()->free(fbd->the_recv_data);
            }
            fbd->the_recv_data = nullptr;
        }
    }

    const auto N_snds = static_cast<int>(TheFB->m_SndTags->size());
    if (N_snds > 0) {
        Vector<MPI_Status> stats(fbd->send_reqs.size());
        ParallelDescriptor::Waitall(fbd->send_reqs, stats);
        amrex::The_Comms_Arena()->free(fbd->the_send_data);
        fbd->the_send_data = nullptr;
    }

    fbd.reset();

#endif
}

template <class FAB>
void
FabArray<FAB>::ParallelCopy (const FabArray<FAB>& src,
                             int                  scomp,
                             int                  dcomp,
                             int                  ncomp,
                             const IntVect&       snghost,
                             const IntVect&       dnghost,
                             const Periodicity&   period,
                             CpOp                 op,
                             const FabArrayBase::CPC * a_cpc,
                             bool                 deterministic)
{
    BL_PROFILE("FabArray::ParallelCopy()");

    ParallelCopy_nowait(src, scomp, dcomp, ncomp, snghost, dnghost, period, op, a_cpc,
                        false, deterministic);
    ParallelCopy_finish();
}

template <class FAB>
void
FabArray<FAB>::ParallelCopy (const FabArray<FAB>& src, int src_comp, int dest_comp,
                             int num_comp, const IntVect& snghost, const IntVect& dnghost,
                             const IntVect& offset, const Periodicity& period)
{
    BL_PROFILE("FabArray::ParallelCopy()");

    ParallelCopy_nowait(src,src_comp,dest_comp,num_comp,snghost,dnghost,offset,period);
    ParallelCopy_finish();
}

template <class FAB>
void
FabArray<FAB>::ParallelAdd (const FabArray<FAB>& src, int src_comp, int dest_comp,
                             int num_comp, const IntVect& snghost, const IntVect& dnghost,
                             const IntVect& offset, const Periodicity& period)
{
    BL_PROFILE("FabArray::ParallelAdd()");

