bool
Geometry::outsideRoundoffDomain (AMREX_D_DECL(ParticleReal x, ParticleReal y, ParticleReal z)) const
{
    bool outside = AMREX_D_TERM(x < roundoff_lo[0]
                             || x > roundoff_hi[0],
