/**
 * \warning Gpu::Buffer assumes the GPU launch-region state stays fixed for its
 * lifetime. Flipping the launch-region flag between construction and
 * destruction may break Gpu::Buffer's member functions.
 */
template <typename T>
requires (std::is_trivially_copyable_v<T>)
class Buffer
{
public:

    Buffer (std::initializer_list<T> init) {
        resize(init.size());

        if (init.size() > 0) {
            std::memcpy(h_vect.data(), init.begin(), init.size()*sizeof(T));
            copyToDeviceAsync();
        }
    }

    Buffer (T const* h_p, const std::size_t n) {
        resize(n);

        if (n > 0 && h_p != nullptr) {
            std::memcpy(h_vect.data(), h_p, n*sizeof(T));
            copyToDeviceAsync();
        }
    }

    Buffer (const std::size_t n) {
        resize(n);
    }

    Buffer () = default;

    [[nodiscard]] T const* data () const noexcept {
        return (useDVect() && !d_vect.empty()) ? d_vect.data() : h_vect.data();
    }
    [[nodiscard]] T* data () noexcept {
        return (useDVect() && !d_vect.empty()) ? d_vect.data() : h_vect.data();
    }

    [[nodiscard]] T const* hostData () const noexcept { return h_vect.data(); }
    [[nodiscard]] T* hostData () noexcept { return h_vect.data(); }

    /**
    * \brief Changes the value of an element of the host (CPU) vector.
    * Does not update the device (GPU) vector, so copyToDeviceAsync()
    * needs to be called before accessing the data on the GPU.
    * \code{.cpp}
    *   amrex::Gpu::Buffer<int> buf;
    *   buf.resize(n);
    *   for (int i=0; i<n; ++i) {
    *       buf[i] = i*i;
    *   }
    *   buf.copyToDeviceAsync();
    *   int * ptr = buf.data();
    *   // Use ptr inside ParallelFor
    *   // optional:
    *   // Change values of ptr inside ParallelFor
    *   buf.copyToHost();
    *   // Use buf.hostData() or buf[] on the CPU
    * \endcode
    */
    [[nodiscard]] T& operator[] (const std::size_t i) noexcept {
        return h_vect[i];
    }

        return h_vect[i];
    }

    [[nodiscard]] const T& operator[] (const std::size_t i) const noexcept {
        return h_vect[i];
    }

    [[nodiscard]] std::size_t size () const noexcept { return h_vect.size(); }

    [[nodiscard]] bool empty () const noexcept { return h_vect.size() == 0; }

    void resize (const std::size_t n) {
        h_vect.resize(n);
        if (useDVect()) {
            d_vect.resize(n);
        }
    }

    void clear () noexcept {
        h_vect.clear();
        d_vect.clear();
    }

    void shrink_to_fit () {
        h_vect.shrink_to_fit();
        d_vect.shrink_to_fit();
    }

    void reserve (const std::size_t n) {
        h_vect.reserve(n);
        if (useDVect()) {
            d_vect.reserve(n);
        }
    }

    /**
    * \brief Adds an element to the back of the host (CPU) vector.
    * Does not update the device (GPU) vector, so copyToDeviceAsync()
    * needs to be called before accessing the data on the GPU.
    * \code{.cpp}
    *   amrex::Gpu::Buffer<int> buf;
    *   buf.reserve(n);
    *   for (int i=0; i<n; ++i) {
    *       buf.push_back(i*i);
    *   }
    *   buf.copyToDeviceAsync();
    *   int * ptr = buf.data();
    *   // Use ptr inside ParallelFor
    *   // optional:
    *   // Change values of ptr inside ParallelFor
    *   buf.copyToHost();
    *   // Use buf.hostData() or buf[] on the CPU
    * \endcode
    */
    void push_back (const T& value) {
        h_vect.push_back(value);
    }

    T* copyToDeviceAsync () {
#ifdef AMREX_USE_GPU
        if (useDVect() && !h_vect.empty())
        {
            d_vect.resize(h_vect.size());
            Gpu::htod_memcpy_async(d_vect.data(), h_vect.data(), h_vect.size()*sizeof(T));
            return d_vect.data();
        }
#endif
        return h_vect.data();
    }

    T* copyToHost () {
#ifdef AMREX_USE_GPU
        if (useDVect() && !d_vect.empty())
        {
            h_vect.resize(d_vect.size());

        if (useDVect() && !d_vect.empty())
        {
            h_vect.resize(d_vect.size());
            Gpu::dtoh_memcpy_async(h_vect.data(), d_vect.data(), d_vect.size()*sizeof(T));
            Gpu::streamSynchronize();
        }
#endif
        return h_vect.data();
    }

private:

    [[nodiscard]] bool useDVect () const noexcept {
        return Gpu::inLaunchRegion() /* && !use_unified_gpu_memory */;
    }

    DeviceVector<T> d_vect;
    PinnedVector<T> h_vect;
};

/**
 * \ingroup amrex_arithmetic_types
 * \brief A host / device complex number type, because std::complex doesn't
 *  work in device code with Cuda yet.
 *
 *  Should be bit-wise compatible with std::complex.
 *
 *  GpuComplex is aligned to its size (stricter than std::complex) to allow for
 *  coalesced memory accesses with nvidia GPUs.
 */
template <typename T>
struct alignas(2*sizeof(T)) GpuComplex
{
    using value_type = T;

    T m_real, m_imag;

    /**
     * \brief Construct a complex number given the real and imaginary part.
     */
    AMREX_GPU_HOST_DEVICE AMREX_FORCE_INLINE
    constexpr GpuComplex (const T& a_r = T(), const T& a_i = T()) noexcept
        : m_real(a_r), m_imag(a_i) {}

    /**
     * \brief Return the real part.
     */
    [[nodiscard]] AMREX_GPU_HOST_DEVICE AMREX_FORCE_INLINE
    constexpr T real () const noexcept { return m_real; }

    /**
     * \brief Return the imaginary part.
     */
    [[nodiscard]] AMREX_GPU_HOST_DEVICE AMREX_FORCE_INLINE
    constexpr T imag () const noexcept { return m_imag; }

    /**
     * \brief Add a real number to this complex number.
     */
    template <typename U>
    AMREX_GPU_HOST_DEVICE AMREX_FORCE_INLINE
    GpuComplex<T>& operator+= (const U& a_t) noexcept
    {
        m_real += a_t;
        return *this;
    }

   /**
     * \brief Subtract a real number from this complex number.
     */
    template <typename U>
    AMREX_GPU_HOST_DEVICE AMREX_FORCE_INLINE
    GpuComplex<T>& operator-= (const U& a_t) noexcept
    {
        m_real -= a_t;
        return *this;
    }

    /**
     * \brief Multiply this complex number by a real.
     */
    template <typename U>
    AMREX_GPU_HOST_DEVICE AMREX_FORCE_INLINE
    GpuComplex<T>& operator*= (const U& a_t) noexcept
    {
        m_real *= a_t;
        m_imag *= a_t;
        return *this;
    }

    /**
     * \brief Divide this complex number by a real.
     */
    template <typename U>
    AMREX_GPU_HOST_DEVICE AMREX_FORCE_INLINE

     */
    template <typename U>
    AMREX_GPU_HOST_DEVICE AMREX_FORCE_INLINE
    GpuComplex<T>& operator/= (const U& a_t) noexcept
    {
        m_real /= a_t;
        m_imag /= a_t;
        return *this;
    }

    /**
     * \brief Add another complex number to this one.
     */
    template <typename U>
    AMREX_GPU_HOST_DEVICE AMREX_FORCE_INLINE
    GpuComplex<T>& operator+= (const GpuComplex<U>& a_z) noexcept
    {
        m_real += a_z.real();
        m_imag += a_z.imag();
        return *this;
    }

    /**
     * \brief Subtract another complex number from this one.
     */
    template <typename U>
    AMREX_GPU_HOST_DEVICE AMREX_FORCE_INLINE
    GpuComplex<T>& operator-= (const GpuComplex<U>& a_z) noexcept
    {
        m_real -= a_z.real();
        m_imag -= a_z.imag();
        return *this;
    }

    /**
     * \brief Multiply this complex number by another one.
     */
    template <typename U>
    AMREX_GPU_HOST_DEVICE AMREX_FORCE_INLINE
    GpuComplex<T>& operator*= (const GpuComplex<U>& a_z) noexcept
    {
        const T a_r = m_real * a_z.real() - m_imag * a_z.imag();
        m_imag = m_real * a_z.imag() + m_imag * a_z.real();
        m_real = a_r;
        return *this;
    }

    /**
     * \brief Divide this complex number by another one.
     */
    template <typename U>
    AMREX_GPU_HOST_DEVICE AMREX_FORCE_INLINE
    GpuComplex<T>& operator/= (const GpuComplex<U>& a_z) noexcept
    {
        const T r =  m_real * a_z.real() + m_imag * a_z.imag();
        const T n = amrex::norm(a_z);
        m_imag = (m_imag * a_z.real() - m_real * a_z.imag()) / n;
        m_real = r / n;
        return *this;
    }

    /**
     * \brief Print this complex number to an ostream.
     */
    template <typename U>
    friend std::ostream & operator<< (std::ostream &out, const GpuComplex<U>& c);
};

template <typename U>
std::ostream& operator<< (std::ostream& out, const GpuComplex<U>& c)
{
    out << c.m_real;
    out << " + " << c.m_imag << "i";
    return out;
}

