template<typename T, typename L>
void launch (T const& n, L const& f) noexcept
{
    // Like the GPU backends: f(i) for each i in [0,n) when n is integral,
    // f(box) once when n is a BoxND.
    for (auto const i : Gpu::Range(n)) {
        f(i);
    }
}

