                          box2,ncomp2,std::forward<L2>(f2),
                          box3,ncomp3,std::forward<L3>(f3));
}

template <int MT, std::integral T1, std::integral T2, std::integral T3, typename L1, typename L2, typename L3, int dim>
void HostDeviceParallelFor (BoxND<dim> const& box1, T1 ncomp1, L1&& f1,
                            BoxND<dim> const& box2, T2 ncomp2, L2&& f2,
                            BoxND<dim> const& box3, T3 ncomp3, L3&& f3) noexcept
{
    HostDeviceParallelFor<MT>(Gpu::KernelInfo{},
                          box1,ncomp1,std::forward<L1>(f1),
                          box2,ncomp2,std::forward<L2>(f2),
                          box3,ncomp3,std::forward<L3>(f3));
}

/** Helper type to store/access the SIMD width in ParallelForSIMD lambdas
 *
 * Use instead of int as the running index i. Used to pass the
 * SIMD WIDTH as compile-time meta-data into a called function/method.
 *
 * @tparam WIDTH SIMD width in elements
 * @tparam N index type (integer)
 */
template<int WIDTH, class N=int>
struct SIMDindex
{
    /** SIMD width in elements */
    static constexpr int width = WIDTH;

    /** The linear loop index of ParallelFor(SIMD) */
    N index = 0;
};

/** ParallelFor with a SIMD Width (in elements)
 *
 * SIMD load/Write-back operations need to be performed before/after calling this.
 *
 * @tparam WIDTH SIMD width in elements
 * @tparam N index type (integer)
 * @tparam L function/functor to call per SIMD set of elements
 */
template <int WIDTH, std::integral N, typename L >
AMREX_ATTRIBUTE_FLATTEN_FOR
void ParallelForSIMD (N n, L const& f) noexcept
{
    N i = 0;
    // vectorize full lanes
    for (; i + WIDTH <= n; i+=WIDTH) {
        f(SIMDindex<WIDTH, N>{i});
    }
    // scalar handling of the remainder
    // note: we could make the remainder calls faster, by repeatedly
    //       decreasing the SIMD width by 2 until we reach 1
    for (; i < n; ++i) {
        f(SIMDindex<1, N>{i});
    }
}

/** ParallelFor with a SIMD Width (derived from a type w/ fallback to non-SIMD)
 *
 * SIMD load/Write-back operations need to be performed before/after calling this.
 *
 * @tparam T a type that implements amrex::simd::Vectorized (or not)
 * @tparam N index type (integer)
 * @tparam L function/functor to call per SIMD set of elements
 */
template <typename T, std::integral N, typename L >
AMREX_ATTRIBUTE_FLATTEN_FOR
void ParallelForSIMD (N n, L && f) noexcept
{
#ifdef AMREX_USE_SIMD
    if constexpr (amrex::simd::is_vectorized<T>) {
        amrex::ParallelForSIMD<T::simd_width>(n, std::forward<L>(f));
    } else
#endif
    {
        amrex::ParallelFor(n, std::forward<L>(f));
    }
}

// We cannot take rvalue lambdas.
    template<class L>
    AMREX_GPU_GLOBAL void launch_global (L f0) { f0(); }

// Min blocks of mt threads for AMREX_GPU_MIN_BLOCKS blocks of
        // AMREX_GPU_MAX_THREADS threads. Rounded down, so for mt up to
        // AMREX_GPU_MIN_BLOCKS*AMREX_GPU_MAX_THREADS the kernel's register cap is
        // not below -maxrregcount, which non-inlined callees are compiled with.
        // At most 16, the lowest per-SM block limit of supported GPUs.
        constexpr int launch_min_blocks (int mt) {
            int n = AMREX_GPU_MIN_BLOCKS * AMREX_GPU_MAX_THREADS / mt;
            return (n < 1) ? 1 : ((n > 16) ? 16 : n);
        }

template<int amrex_launch_bounds_max_threads, int min_blocks, class L>
    __launch_bounds__(amrex_launch_bounds_max_threads, min_blocks)
    AMREX_GPU_GLOBAL void launch_global (L f0) { f0(); }

