std::ostream&
index_type_write (std::ostream& os, const unsigned int& iv, int dim)
{
    os << '(' << (((iv & 1U) != 0) ? 'N' : 'C');
    for (int i=1; i<dim; ++i) {
        os << ',' << (((iv & (1U<<i)) != 0) ? 'N' : 'C');
    }
    os << ')' << std::flush;

    if (os.fail()) {
        amrex::Error("operator<<(ostream&,IndexType&) failed");
    }

    return os;
}

std::istream&
index_type_read (std::istream& is, unsigned int& iv, int dim)
{
    char t = '0';
    is.ignore(BL_IGNORE_MAX, '(') >> t;
    BL_ASSERT(t == 'C' || t == 'N');
    t == 'N' ? (iv |= 1U) : (iv &= ~1U);
    for (int i=1; i<dim; ++i) {
        is.ignore(BL_IGNORE_MAX, ',') >> t;
        BL_ASSERT(t == 'C' || t == 'N');
        t == 'N' ? (iv |= (1U << i)) : (iv &= ~(1U << i));
    }
    is.ignore(BL_IGNORE_MAX, ')');

    if (is.fail()) {
        amrex::Error("operator>>(ostream&,IndexType&) failed");
    }

    return is;
}

