/*
 * \brief I/O stream format saver
 *
 * This class can be used to save and restore I/O stream format in a RAII
 * way. It handles fill, fmtflag, precision, and width.
 */
template <class CharT, class Traits>
class IOFormatSaver
{
public:
    using BasicIos = std::basic_ios<CharT, Traits>;

    explicit IOFormatSaver (BasicIos& ios)
        : m_ios(&ios),
          m_fill(ios.fill()),
          m_flags(ios.flags()),
          m_precision(ios.precision()),
          m_width(ios.width())
    {}

    ~IOFormatSaver ()
    {
        m_ios->fill(m_fill);
        m_ios->flags(m_flags);
        m_ios->precision(m_precision);
        m_ios->width(m_width);
    }

    IOFormatSaver (IOFormatSaver const&) = delete;
    IOFormatSaver (IOFormatSaver &&) noexcept = delete;
    IOFormatSaver& operator= (IOFormatSaver const&) = delete;
    IOFormatSaver& operator= (IOFormatSaver &&) noexcept = delete;

private:
    BasicIos*                   m_ios;
    CharT                       m_fill;
    typename BasicIos::fmtflags m_flags;
    std::streamsize             m_precision;
    std::streamsize             m_width;
};

//! a one-thingy-per-box distributed object
template <class T>
class LayoutData: public FabArrayBase
{
public:

    LayoutData() = default;

    LayoutData(const BoxArray            & a_grids,
               const DistributionMapping & a_dm)
    {
        define(a_grids, a_dm);
    }

    void define(const BoxArray           & a_grids,
                const DistributionMapping & a_dm)
    {
        clear();
        FabArrayBase::define(a_grids, a_dm, 1, 0);
        m_need_to_clear_bd = true;
        addThisBD();
        m_data.resize(local_size());
    }

    void clear ()
    {
        m_data.clear();
        if (m_need_to_clear_bd) { clearThisBD(); }
        m_need_to_clear_bd = false;
        FabArrayBase::clear();
    }

    ~LayoutData () { if (m_need_to_clear_bd) { clearThisBD(); } }

    LayoutData (const LayoutData& rhs) noexcept
        : FabArrayBase(rhs),
          m_data(rhs.m_data),
          m_need_to_clear_bd(rhs.m_need_to_clear_bd)
    {
        if (m_need_to_clear_bd) { addThisBD(); }
    }

    LayoutData (LayoutData&& rhs) noexcept
        : FabArrayBase(static_cast<FabArrayBase&&>(rhs)),
          m_data(std::move(rhs.m_data)),
          m_need_to_clear_bd(rhs.m_need_to_clear_bd)
    {
        rhs.m_need_to_clear_bd = false;
    }

    LayoutData& operator= (const LayoutData& rhs) noexcept
    {
        if (&rhs != this)
        {
            m_data.clear();
            if (m_need_to_clear_bd) { clearThisBD(); }

            FabArrayBase::operator=(rhs);
            m_data = rhs.m_data;
            m_need_to_clear_bd = rhs.m_need_to_clear_bd;

            if (m_need_to_clear_bd) { addThisBD(); }
        }
        return *this;
    }

    LayoutData& operator= (LayoutData&& rhs) noexcept
    {
        if (&rhs != this)
        {
            m_data.clear();
            if (m_need_to_clear_bd) { clearThisBD(); }

            FabArrayBase::operator=(static_cast<FabArrayBase&&>(rhs));
            m_data = std::move(rhs.m_data);

            FabArrayBase::operator=(static_cast<FabArrayBase&&>(rhs));
            m_data = std::move(rhs.m_data);
            m_need_to_clear_bd = rhs.m_need_to_clear_bd;

            rhs.m_need_to_clear_bd = false;
        }
        return *this;
    }

    T& operator[](const MFIter& a_mfi) noexcept
    {
        int local_index = a_mfi.LocalIndex();
        BL_ASSERT(local_index >= 0 && local_index < m_data.size() &&
                  DistributionMap() == a_mfi.DistributionMap());
        return m_data[local_index];
    }


    const T& operator[](const MFIter& a_mfi) const noexcept
    {
        int local_index = a_mfi.LocalIndex();
        BL_ASSERT(local_index >= 0 && local_index < m_data.size() &&
                  DistributionMap() == a_mfi.DistributionMap());
        return m_data[local_index];
    }

    T& operator[](int a_box_index) noexcept
    {
        int local_index = this->localindex(a_box_index);
        BL_ASSERT(local_index >= 0 && local_index < m_data.size());
        return m_data[local_index];
    }

    const T& operator[](int a_box_index) const noexcept
    {
        int local_index = this->localindex(a_box_index);
        BL_ASSERT(local_index >= 0 && local_index < m_data.size());
        return m_data[local_index];
    }

    const T* data () const noexcept { return m_data.data(); }
    T*       data ()       noexcept { return m_data.data(); }

private:
    Vector<T> m_data;
    bool m_need_to_clear_bd = false;
};

void QueueReduction (Func f) // NOLINT
    {
#ifdef BL_USE_MPI
        reduction_queue.push_back(f);
        const int max_queue_size = 64;
        if (reduction_queue.size() >= max_queue_size) {
            EvalReduction();
        }
#else
        f();
#endif
    }

void EvalReduction ()
    {
#ifdef BL_USE_MPI
        static int count = 0;
        ++count;
        if (count == 1) {
            for (auto&& f : reduction_queue) {
                f();
            }
            reduction_queue.clear();
            count = 0;
        }
#endif
    }

