/**
 * \brief
 *  Convert a Real to a uint32, keeping only 10 significant bits.
 *  This puts the first 10 bits of x into retval with the 22 highest bits set to 0.
 *  It is assumed that xmin <= x < xmax. The result is clamped so that
 *  round-off at xmax cannot wrap it to zero.
 *
 *  This is useful in 3D, because you can interleave the bits of 3 10-bit
 *  numbers and store the result in one 32-bit integer.
 *
 * \param x the coordinate to convert.
 * \param xmin the low end of the domain.
 * \param xmax the high end of the domain.
 */
AMREX_GPU_HOST_DEVICE AMREX_FORCE_INLINE
std::uint32_t toUInt10 (amrex::Real x, amrex::Real xmin, amrex::Real xmax) noexcept {
    AMREX_ASSERT(x >= xmin && x < xmax);
    constexpr std::uint32_t code_offset = (1U << 10);
    constexpr Real rmax = Real(1.0) - std::numeric_limits<Real>::epsilon();
    Real r = amrex::Clamp((x - xmin)/(xmax - xmin), Real(0.0), rmax);
    return (std::uint32_t)(r * code_offset);
}

/**
 * \brief
 *  Convert a Real to a uint32, keeping only 16 significant bits.
 *  This puts the first 16 bits of x into retval with the 16 highest bits set to 0.
 *  It is assumed that xmin <= x < xmax. The result is clamped so that
 *  round-off at xmax cannot wrap it to zero.
 *
 *  This is useful in 2D, because you can interleave the bits of two 16-bit
 *  numbers and store the result in one 32-bit integer.
 *
 * \param x the coordinate to convert.
 * \param xmin the low end of the domain.
 * \param xmax the high end of the domain.
 */
AMREX_GPU_HOST_DEVICE AMREX_FORCE_INLINE
std::uint32_t toUInt16 (amrex::Real x, amrex::Real xmin, amrex::Real xmax) noexcept {
    AMREX_ASSERT(x >= xmin && x < xmax);
    constexpr std::uint32_t code_offset = (1U << 16);
    constexpr Real rmax = Real(1.0) - std::numeric_limits<Real>::epsilon();
    Real r = amrex::Clamp((x - xmin)/(xmax - xmin), Real(0.0), rmax);
    return (std::uint32_t)(r * code_offset);
}

/**
 * \brief
 *  Convert a Real to a uint32, keeping all significant bits.
 *  It is assumed that xmin <= x < xmax. The result is clamped so that
 *  round-off at xmax cannot wrap it to zero.
 *
 *  This is useful in 1D, because no interleaving is needed.
 *
 * \param x the coordinate to convert.
 * \param xmin the low end of the domain.
 * \param xmax the high end of the domain.
 */
AMREX_GPU_HOST_DEVICE AMREX_FORCE_INLINE
std::uint32_t toUInt32 (amrex::Real x, amrex::Real xmin, amrex::Real xmax) noexcept {
    AMREX_ASSERT(x >= xmin && x < xmax);
    constexpr unsigned long long code_offset = (1ULL << 32);
    constexpr Real rmax = Real(1.0) - std::numeric_limits<Real>::epsilon();
    Real r = amrex::Clamp((x - xmin)/(xmax - xmin), Real(0.0), rmax);
    return (std::uint32_t)(r * Real(code_offset));
}

/**
 * \brief
 * Given a 3D real-space coordinate, returns a Morton code stored in an
 * unsigned 32 bit integer.
 *
 * In 3D, this works by converting the coordinate to a 10-bit nonnegative
 * integer in each direction and then interleaving the bits.
 *
 * In 2D, it is same except the lowest 16 bits of of the coordinates are kept.
 *
 * It is assumed that plo <= p < phi has already been enforced.
 *
 * \param x the coordinates to convert.
 * \param y the coordinates to convert.
 * \param z the coordinates to convert.
 * \param plo the low end of the domain.
 * \param phi the high end of the domain.
 */
AMREX_GPU_HOST_DEVICE AMREX_FORCE_INLINE
std::uint32_t get32BitCode (AMREX_D_DECL(Real x, Real y, Real z),
                            const GpuArray<amrex::Real,AMREX_SPACEDIM>& plo,
                            const GpuArray<amrex::Real,AMREX_SPACEDIM>& phi) noexcept {
#if (AMREX_SPACEDIM == 3)
    std::uint32_t a = toUInt10(x, plo[0], phi[0]);
    std::uint32_t b = toUInt10(y, plo[1], phi[1]);
    std::uint32_t c = toUInt10(z, plo[2], phi[2]);
#elif (AMREX_SPACEDIM == 2)
    std::uint32_t a = toUInt16(x, plo[0], phi[0]);
    std::uint32_t b = toUInt16(y, plo[1], phi[1]);
#elif (AMREX_SPACEDIM == 1)
    std::uint32_t a = toUInt32(x, plo[0], phi[0]);
#endif
    return AMREX_D_TERM(makeSpace(a), | (makeSpace(b) << 1), | (makeSpace(c) << 2));
}

AMREX_GPU_HOST_DEVICE AMREX_FORCE_INLINE
std::uint32_t get32BitCode (const XDim3& p,
                            const GpuArray<amrex::Real,AMREX_SPACEDIM>& plo,
                            const GpuArray<amrex::Real,AMREX_SPACEDIM>& phi) noexcept {
    return get32BitCode(p.x, p.y, p.z, plo, phi);
}

template <typename T>
int num_unique_elements (std::vector<T>& v)
{
    std::ranges::sort(v);
    auto last = std::unique(v.begin(), v.end());
    return last - v.begin();
}

/*
Initialize_without_split function assigns and checks the required
AMReX_MPMD variables. This function is internally leveraged by
Initialize function.

This function needs to be used EXPLICITLY ONLY with pyAMReX (python)
so that the communication split can be performed using a python
library, for example, mpi4py.
*/
void Initialize_without_split (int argc, char* argv[])
{
    initialized = true;
    int flag;
    MPI_Initialized(&flag);
    if (!flag) {
        Gpu::SelectDeviceBeforeMPIInit();
        MPI_Init(&argc, &argv);
        mpi_initialized_by_us = true;
    }

    MPI_Comm_rank(MPI_COMM_WORLD, &myproc);
    MPI_Comm_size(MPI_COMM_WORLD, &nprocs);

    int* p = nullptr;
    MPI_Comm_get_attr(MPI_COMM_WORLD, MPI_APPNUM, &p, &flag);
    appnum = (flag && p) ? *p : -1;

    std::vector<int> all_appnum(nprocs);
    MPI_Allgather(&appnum, 1, MPI_INT, all_appnum.data(), 1, MPI_INT, MPI_COMM_WORLD);
    int napps = num_unique_elements(all_appnum);

    // MPI_APPNUM does not appear to work with slurm on some systems.
    if (napps != 2) {
        std::vector<int> all_argc(nprocs);
        MPI_Allgather(&argc, 1, MPI_INT, all_argc.data(), 1, MPI_INT, MPI_COMM_WORLD);
        napps = num_unique_elements(all_argc);
        if (napps == 2) {
            appnum = static_cast<int>(argc != all_argc[0]);
        }
    }

    if (napps != 2) {
        std::string exename;
        if (argc > 0) {
            exename = std::string(argv[0]);
        }
        unsigned long long hexe = std::hash<std::string>{}(exename);
        std::vector<unsigned long long> all_hexe(nprocs);
        MPI_Allgather(&hexe, 1, MPI_UNSIGNED_LONG_LONG,
                      all_hexe.data(), 1, MPI_UNSIGNED_LONG_LONG, MPI_COMM_WORLD);
        napps = num_unique_elements(all_hexe);
        if (napps == 2) {
            appnum = static_cast<int>(hexe != all_hexe[0]);
        }
    }

    if (napps != 2) {
        std::cout << "amrex::MPMD only supports two programs." << '\n';

    if (napps != 2) {
        std::cout << "amrex::MPMD only supports two programs." << '\n';
        MPI_Abort(MPI_COMM_WORLD, 1);
    }

}

MPI_Comm Initialize (int argc, char* argv[])
{
    Initialize_without_split(argc,argv);
    MPI_Comm_split(MPI_COMM_WORLD, appnum, myproc, &app_comm);

    return app_comm;
}

void Finalize ()
{
    // app_comm is MPI_COMM_NULL after Initialize_without_split.
    if (app_comm != MPI_COMM_NULL) {
        MPI_Comm_free(&app_comm);
        app_comm = MPI_COMM_NULL;
    }
    if (mpi_initialized_by_us) {
        MPI_Finalize();
        mpi_initialized_by_us = false;
    }
    initialized = false;
}

