        break;
    }
    case 1:
    {
        const Real facInv = Real(1.0) / static_cast<Real>(facy);
        Real c = 0.;
        for (int jref = 0; jref < facy; ++jref) {
            c += fine(ii,jj+jref,kk,n+fcomp);
        }
