template <typename DTOS>
Box get_dst_subbox (DTOS const& dtos, std::pair<Box,Box> const& sdboxes,
                    Box const& srcsubbox)
{
    Box const& srcbox = sdboxes.first;
    Box const& dstbox = sdboxes.second;
    if (srcbox == srcsubbox) {
        return dstbox;
    } else {
        auto sign = dtos.sign(amrex::lbound(dstbox));
        auto perm = dtos.permutation(amrex::lbound(dstbox));
        Box dstsubbox = dstbox;
        for (int ddim = 0; ddim < AMREX_SPACEDIM; ++ddim) {
            int sdim = perm[ddim];
            if (sign[ddim] > 0) {
                dstsubbox.growLo(ddim, srcbox.smallEnd(sdim)-srcsubbox.smallEnd(sdim));
                dstsubbox.growHi(ddim, srcsubbox.bigEnd(sdim)-srcbox.bigEnd(sdim));
            } else {
                dstsubbox.growLo(ddim, srcsubbox.bigEnd(sdim)-srcbox.bigEnd(sdim));
                dstsubbox.growHi(ddim, srcbox.smallEnd(sdim)-srcsubbox.smallEnd(sdim));
            }
        }
        return dstsubbox;
    }
}

template <BaseFabType FAB, typename DTOS>
requires (IsCallableR<Dim3,DTOS,Dim3>::value)
FabArrayBase::CommMetaData
makeFillBoundaryMetaData (FabArray<FAB>& mf, IntVect const& nghost,
                          Geometry const& geom, DTOS const& dtos)
{
    FabArrayBase::CommMetaData cmd;
    cmd.m_LocTags = std::make_unique<FabArrayBase::CopyComTagsContainer>();
    cmd.m_SndTags = std::make_unique<FabArrayBase::MapOfCopyComTagContainers>();
    cmd.m_RcvTags = std::make_unique<FabArrayBase::MapOfCopyComTagContainers>();

    // Normal FillBoundary part
    mf.define_fb_metadata(cmd, nghost, false, geom.periodicity(), false);

    BoxArray const& ba = mf.boxArray();
    DistributionMapping const& dm = mf.DistributionMap();
    Box dombox = amrex::convert(geom.Domain(), ba.ixType());
    Box pdombox = amrex::convert(geom.growPeriodicDomain(nghost), ba.ixType());

    const int myproc = ParallelDescriptor::MyProc();
    const auto nboxes = static_cast<int>(ba.size());
    std::vector<std::pair<int,Box> > isects;

    for (int i = 0; i < nboxes; ++i) {
        Box const& gbx = amrex::grow(ba[i], nghost);
        BoxList bl = amrex::boxDiff(gbx, pdombox);
        if (bl.isEmpty()) { continue; }

        detail::split_boxes(bl, dombox);

        const int dst_owner = dm[i];
        for (auto const& dst_box : bl) {
            auto const& src_dst_boxes = get_src_dst_boxes(dtos, dst_box, dombox);
            for (auto const& sd_box_pair : src_dst_boxes) {
                ba.intersections(sd_box_pair.first, isects);
                for (auto const& is : isects) {
                    int const     k = is.first;
                    Box const src_b = is.second;
                    int const src_owner = dm[k];
                    if (dst_owner == myproc || src_owner == myproc) {
                        Box const& dst_b = get_dst_subbox(dtos, sd_box_pair, src_b);
                        if (src_owner == dst_owner) {

                    if (dst_owner == myproc || src_owner == myproc) {
                        Box const& dst_b = get_dst_subbox(dtos, sd_box_pair, src_b);
                        if (src_owner == dst_owner) {
                            cmd.m_LocTags->emplace_back(dst_b, src_b, i, k);
                        } else {
                            auto& tags = (dst_owner == myproc) ?
                                (*cmd.m_RcvTags)[src_owner] :
                                (*cmd.m_SndTags)[dst_owner];
                            tags.emplace_back(dst_b, src_b, i, k);
                        }
                    }
                }
            }
        }
    }

    return cmd;
}

struct SphThetaPhiRIndexMapping
{
    SphThetaPhiRIndexMapping (Box const& a_domain)
        : nx(a_domain.length(0)),
          ny(a_domain.length(1)),
          nz(a_domain.length(2))
    {
        AMREX_ASSERT(a_domain.smallEnd() == 0);
    }

    [[nodiscard]] AMREX_GPU_HOST_DEVICE
    Dim3 operator() (Dim3 const& ijk) const noexcept
    {
        const int i = ijk.x;
        const int j = ijk.y;
        const int k = ijk.z;
        bool ilo = i < 0;
        bool ihi = i >= nx;
        bool imd = i >= 0 && i < nx;
        bool jlo = j < 0;
        bool jhi = j >= ny;
        bool jmd = j >= 0 && j < ny;
        bool klo = k < 0;
        bool kmd = k >= 0 && k < nz;
        // We do not need to do anything at the theta-lo/r-lo edge,
        // theta-hi/r-lo edge, and r > r-hi.
        if (ilo && jmd && kmd)
        {
            return Dim3{.x = -1-i, .y = (j+ny/2)%ny, .z = k};
        }
        else if (ihi && jmd && kmd)
        {
            return Dim3{.x = 2*nx-1-i, .y = (j+ny/2)%ny, .z = k};
        }
        else if (imd && jlo && kmd)
        {
            return Dim3{.x = i, .y = j+ny, .z = k};
        }
        else if (imd && jhi && kmd)
        {
            return Dim3{.x = i, .y = j-ny, .z = k};
        }
        else if (imd && jmd && klo)
        {
            return Dim3{.x = nx-1-i, .y = (j+ny/2)%ny, .z = -1-k};
        }
        else if (ilo && jlo && kmd)
        {
            return Dim3{.x = -1-i, .y = (j+ny/2)%ny, .z = k};
        }
        else if (ihi && jlo && kmd)
        {
            return Dim3{.x = 2*nx-1-i, .y = (j+ny/2)%ny, .z = k};
        }
        else if (ilo && jhi && kmd)
        {
            return Dim3{.x = -1-i, .y = (j+ny/2)%ny, .z = k};
        }
        else if (ihi && jhi && kmd)
        {
            return Dim3{.x = 2*nx-1-i, .y = (j+ny/2)%ny, .z = k};
        }
        else if (imd && jlo && klo)
        {
            return Dim3{.x = nx-1-i, .y = (j+ny/2)%ny, .z = -1-k};
        }

        {
            return Dim3{.x = nx-1-i, .y = (j+ny/2)%ny, .z = -1-k};
        }
        else if (imd && jhi && klo)
        {
            return Dim3{.x = nx-1-i, .y = (j+ny/2)%ny, .z = -1-k};
        }
        else
        {
            return ijk;
        }
    }

    [[nodiscard]] IntVect sign (Dim3 const& ijk) const noexcept
    {
        if (ijk.z < 0) {
            return IntVect{AMREX_D_DECL(-1, 1,-1)};
        } else if (ijk.z >=0 && ijk.z < nz &&
                   (ijk.x < 0 || ijk.x >= nx)) {
            return IntVect{AMREX_D_DECL(-1, 1, 1)};
        } else {
            return IntVect{AMREX_D_DECL( 1, 1, 1)};
        }
    }

    [[nodiscard]] IntVect permutation (Dim3 const& /*ijk*/) const noexcept // NOLINT(readability-convert-member-functions-to-static)
    {
        return IntVect(AMREX_D_DECL(0,1,2));
    }

private:
    int nx, ny, nz;
}

struct SphThetaPhiRComponentMapping
{
    SphThetaPhiRComponentMapping (Box const& a_domain, int a_start_index)
        : nx(a_domain.length(0)),
          ny(a_domain.length(1)),
          nz(a_domain.length(2)),
          scomp(a_start_index) {}

    template <typename T>
    [[nodiscard]] AMREX_GPU_HOST_DEVICE
    T operator()(Array4<const T> const& a, Dim3 const& ijk, int n) const noexcept
    {
        const int i = ijk.x;
        const int j = ijk.y;
        const int k = ijk.z;
        auto r = a(i,j,k,n);
        if (n == scomp) {
            if ((i >= 0 && i <  nx) &&
                (j <  0 || j >= ny) &&
                (k >= 0 && k <  nz)) {
                return r;
            } else {
                // We do not need to worry about the theta-lo/r-lo edge,
                // theta-hi/r-lo edge, and r > r-hi.
                return -r;
            }
        } else if (n == scomp+2) {
            if (k < 0) {
                return -r;
            } else {
                return r;
            }
        } else {
            return r;
        }
    }
private:
    int nx, ny, nz;
    int scomp;
}

int
    numUniquePhysicalCores ()
    {
        int ncores;

#if defined(__APPLE__)
        size_t len = sizeof(ncores);
        // See hw.physicalcpu and hw.physicalcpu_max
        //   https://developer.apple.com/documentation/kernel/1387446-sysctlbyname/determining_system_capabilities/
        //   https://developer.apple.com/documentation/kernel/1387446-sysctlbyname
        if (sysctlbyname("hw.physicalcpu", &ncores, &len, NULL, 0) == -1) {
            if (system::verbose > 0) {
                amrex::Print() << "numUniquePhysicalCores(): Error receiving hw.physicalcpu! "
                               << "Defaulting to visible cores.\n";
            }
            ncores = int(std::thread::hardware_concurrency());
        }
#elif defined(__linux__)
        std::set<std::vector<int>> uniqueThreadSets;
        int cpuIndex = 0;

        while (true) {
            // for each logical CPU in cpuIndex from 0...N-1
            std::string path = "/sys/devices/system/cpu/cpu" + std::to_string(cpuIndex) + "/topology/thread_siblings_list";
            std::ifstream file(path);
            if (!file.is_open()) {
                break; // no further CPUs to check
            }

            // find its siblings
            std::vector<int> siblings;
            std::string line;
            if (std::getline(file, line)) {
                std::stringstream ss(line);
                std::string token;

                // Possible syntax: 0-3, 8-11, 14,17
                // https://github.com/torvalds/linux/blob/v6.5/Documentation/ABI/stable/sysfs-devices-system-cpu#L68-L72
                while (std::getline(ss, token, ',')) {
                    size_t dashPos = token.find('-');
                    if (dashPos != std::string::npos) {
                        // Range detected
                        int start = std::stoi(token.substr(0, dashPos));
                        int end = std::stoi(token.substr(dashPos + 1));

                        // Range detected
                        int start = std::stoi(token.substr(0, dashPos));
                        int end = std::stoi(token.substr(dashPos + 1));
                        for (int i = start; i <= end; ++i) {
                            siblings.push_back(i);
                        }
                    } else {
                        siblings.push_back(std::stoi(token));
                    }
                }
            }

            // and record the siblings group
            // (assumes: ascending and unique sets per cpuIndex)
            uniqueThreadSets.insert(std::move(siblings));
            cpuIndex++;
        }

        if (cpuIndex == 0) {
            if (system::verbose > 0) {
                amrex::Print() << "numUniquePhysicalCores(): Error reading CPU info.\n";
            }
            ncores = int(std::thread::hardware_concurrency());
        } else {
            ncores = int(uniqueThreadSets.size());
        }
#elif defined(_WIN32)
        DWORD length = 0;
        bool result = GetLogicalProcessorInformation(NULL, &length);

        if (!result) {
            if (system::verbose > 0) {
                amrex::Print() << "numUniquePhysicalCores(): Failed to get logical processor information! "
                               << "Defaulting to visible cores.\n";
            }
            ncores = int(std::thread::hardware_concurrency());
        }
        else {
            std::vector<SYSTEM_LOGICAL_PROCESSOR_INFORMATION> buffer(length / sizeof(SYSTEM_LOGICAL_PROCESSOR_INFORMATION));
            if (!GetLogicalProcessorInformation(&buffer[0], &length)) {
                if (system::verbose > 0) {
                    amrex::Print() << "numUniquePhysicalCores(): Failed to get logical processor information! "
                                   << "Defaulting to visible cores.\n";
                }
                ncores = int(std::thread::hardware_concurrency());
            } else {

                }
                ncores = int(std::thread::hardware_concurrency());
            } else {
                ncores = 0;
                for (const auto& info : buffer) {
                    if (info.Relationship == RelationProcessorCore) {
                        ncores++;
                    }
                }
            }
        }
#else
        // TODO:
        //   BSD
        if (system::verbose > 0) {
            amrex::Print() << "numUniquePhysicalCores(): Unknown system. Defaulting to visible cores.\n";
        }
        ncores = int(std::thread::hardware_concurrency());
#endif
        return ncores;
    }

void Initialize ()
    {
        if (initialized) {
            ++initialized;
            return;
        }

        amrex::ParmParse pp("amrex");
        std::string omp_threads = "system";
        pp.queryAdd("omp_threads", omp_threads);

        auto to_int = [](std::string const & str_omp_threads) -> std::optional<int> {
            int num = 0;
            std::istringstream iss(str_omp_threads);
            if (iss >> num) {
                // Require a complete integer token; otherwise "4xxxx" would parse as 4.
                char c;
                if (!(iss >> c)) {
                    return num;
                }
            }
            return std::nullopt;
        };

        if (omp_threads == "system") {
            // default or OMP_NUM_THREADS environment variable
        } else if (omp_threads == "nosmt") {
            char const *env_omp_num_threads = std::getenv("OMP_NUM_THREADS");
            if (env_omp_num_threads == nullptr) {
                omp_set_num_threads(numUniquePhysicalCores());
            }
            else if (amrex::system::verbose > 1) {
                amrex::Print() << "amrex.omp_threads was set to nosmt,"
                               << "but OMP_NUM_THREADS was set. Will keep "
                               << "OMP_NUM_THREADS=" << env_omp_num_threads << ".\n";
            }
        } else {
            std::optional<int> num_omp_threads = to_int(omp_threads);
            if (num_omp_threads.has_value() && num_omp_threads.value() > 0) {
                omp_set_num_threads(num_omp_threads.value());
            }
            else {
                if (amrex::system::verbose > 0) {
                    amrex::Print() << "amrex.omp_threads has an unknown value: "
                                   << omp_threads
                                   << " (try system, nosmt, or a positive integer)\n";
                }
            }
        }

#if defined(_WIN32)
        for (auto& vp : omp_locks) {

#if defined(_WIN32)
        for (auto& vp : omp_locks) {
            auto* p = new omp_lock_t;
            omp_init_lock(p);
            vp = (void*) p;
        }
#else
        for (auto& lck : omp_locks) {
            omp_init_lock(&lck);
        }
#endif

        ++initialized;
    }

void Finalize ()
    {
        if (initialized) {
            --initialized;
            if (initialized == 0) {
#if defined(_WIN32)
                for (auto vp : omp_locks) {
                    auto* p = (omp_lock_t*)vp;
                    omp_destroy_lock(p);
                    delete p;
                }
#else
                for (auto& lck : omp_locks) {
                    omp_destroy_lock(&lck);
                }
#endif
            }
        }
    }

inline omp_lock_t* get_lock (int ilock) {
        return (omp_lock_t*)(*(get_lock_impl(ilock)));
    }

