/**
 * \brief Parallel reduce for MultiFab/FabArray. The reduce result is local
 * and it's the user's responsibility if MPI communication is needed.
 *
 * This performs reduction over a MultiFab's valid region. For
 * example, the code below computes the sum of the processed data in a MultiFab.
 * \code{.cpp}
 *     auto const& ma = mf.const_arrays();
 *     Real ektot = ParReduce(TypeList<ReduceOpSum>{}, TypeList<Real>{}, mf,
 *     [=] AMREX_GPU_DEVICE (int box_no, int i, int j, int k) noexcept
 *         -> GpuTuple<Real>
 *     {
 *         auto rho = ma[box_no](i,j,k,0);
 *         auto mx = ma[box_no](i,j,k,1);
 *         auto my = ma[box_no](i,j,k,2);
 *         auto mz = ma[box_no](i,j,k,3);
 *         auto ek = (mx*mx+my*my+mz*mz)/(2.*rho);
 *         return { ek };
 *     });
 * \endcode
 *
 * \tparam Op  Reduce operator (e.g., ReduceOpSum, ReduceOpMin, ReduceOpMax,
 *             ReduceOpLogicalAnd, and ReduceOpLogicalOr)
 * \tparam T   data type (e.g., Real, int, etc.)
 * \tparam FAB MultiFab/FabArray type
 * \tparam F   callable type like a lambda function
 *
 * \param operation_list a reduce operator stored in TypeList
 * \param type_list      a data type stored in TypeList
 * \param fa     a MultiFab/FabArray object used to specify the iteration space
 * \param f      a callable object returning GpuTuple<T>.  It takes four ints,
 *               where the first int is the local box index and the others are
 *               spatial indices for x, y, and z-directions.
 *
 * \return reduction result (T)
 */
template <typename Op, typename T, BaseFabType FAB, typename F>
T
ParReduce (TypeList<Op> operation_list, TypeList<T> type_list,
           FabArray<FAB> const& fa, F&& f)
{
    return ParReduce(operation_list, type_list, fa, IntVect(0), std::forward<F>(f));
}

// in parallel, compute the filename give the basename
//[NOTE: dont call this before MPI is initialized.]
  void setFileName()
  {
    int outInterv = 1;
    ParmParse pp("amrex");
    pp.queryAdd("pout_int", outInterv);
    if (outInterv == 0) { outInterv=ParallelDescriptor::NProcs(); }

    int thisProc = ParallelDescriptor::MyProc();
    if ((thisProc % outInterv) != 0)
    {
      s_pout_filename = std::string("/dev/null");
    }
    else
    {
      static const size_t ProcnumSize = 1 + 10 + 1 ;  //'.' + 10digits + '\0'
      char procnum[ProcnumSize] ;
      snprintf( procnum ,ProcnumSize ,".%d" ,ParallelDescriptor::MyProc() );
      s_pout_filename = s_pout_basename + procnum ;
    }
  }

// in parallel, close the file if nec., open it and check for success
  void openFile()
  {
    if ( s_pout_open )
    {
      s_pout.close();
    }
    s_pout.open( s_pout_filename.c_str() );
    // if open() fails, we have problems, but it's better
    // to try again later than to make believe it succeeded
    s_pout_open = (bool)s_pout ;
  }

// in serial, filename is always cout
  void setFileName()
  {
    s_pout_filename = "cout" ;
  }

// in serial, this does absolutely nothing
  void openFile()
  {
    amrex::ignore_unused(s_pout);
  }

std::ostream& pout()
  {
#ifdef BL_USE_MPI
    // the common case is _open == true, which just returns s_pout
    if ( ! s_pout_open )
    {
      // the uncommon cae: the file isn't opened, MPI may not be
      // initialized, and the basename may not have been set
      int flag_i, flag_f;
      MPI_Initialized(&flag_i);
      MPI_Finalized(&flag_f);
      // app hasn't set a basename yet, so set the default
      if ( ! s_pout_init )
      {
        s_pout_basename = "amrex_pout" ;
        s_pout_init = true ;
      }
      // if MPI not initialized, we can't open the file so return cout
      if ( ! flag_i || flag_f)
      {
        return std::cout; // MPI hasn't been started yet, or has ended....
      }
      // MPI is initialized, so file must not be, so open it
      setFileName() ;
      openFile() ;
      // finally, in case the open failed, return cout
      if ( ! s_pout_open )
      {
        return std::cout ;
      }
    }
    return s_pout ;
#else
    return std::cout;
#endif
  }

void setPoutBaseName( const std::string & a_Name )
  {
    bool is_new_name = a_Name != s_pout_basename ;
    s_pout_basename = a_Name ;
    if ( s_pout_init && s_pout_open && is_new_name )
    {
      // open a new file
      //[NOTE: this is safe to do now because it's already been done once.]
      setFileName() ;
      openFile() ;
    }
    s_pout_init = true ;
  }

const std::string & poutFileName()
  {
#ifdef BL_USE_MPI
    int flag;
    MPI_Initialized(&flag);
    if (flag)
    {
      if ( ! s_pout_open )
      {
        if ( ! s_pout_init )
        {
          s_pout_basename = "amrex_pout" ;
          s_pout_init = true ;
        }
        setFileName() ;
        //[NOTE: could open the file here, but we would still need
        //       code in pout() to handle the case where the file isn't
        //       open, so there's no point duplicating the code here. <dbs>]
      }
    }
    else
    {
      // There's really nothing reasonable to do in this case, since the
      // filename cannot be computed until after MPI is initialized and the
      // proc number is known.  So treat it as a programming bug.  Since MPI
      // isn't initialized, all procs must be running this code, so all procs
      // will fail.
      std::cerr << "error: poutFileName() cannot be called before MPI_Initialize()." << '\n' ;
      exit( 111 );
    }
#else
    // in serial, set the filename to "cout" and return it
    //[NOTE: yes, this resets the filename redundantly ever time. <dbs>]
    setFileName();
#endif
    return s_pout_filename ;
  }

template <typename T, typename F>
    int amrex_partition_helper (T const* AMREX_RESTRICT pv, T* AMREX_RESTRICT pv2, int n, F && f)
    {
        return Scan::PrefixSum<int> (n,
         [=] AMREX_GPU_DEVICE (int i) -> int
         {
             return f(pv[i]);
         },
         [=] AMREX_GPU_DEVICE (int i, int const& s)
         {
             // We store true elements from the beginning and false
             // elements reversely from the end.  If all elements
             // before pv[i] are true, the exclusive sum so far would
             // be i.  But the actual value is s.
             if (f(pv[i])) {
                 // For true element, s spots from the beginning have
                 // been taken.
                 pv2[s] = pv[i];
             } else {
                 // There are i-s elements before this element that
                 // are false.  From the end, i-s spots have been
                 // taken.
                 pv2[n-1-(i-s)] = pv[i];
             }
         },
         Scan::Type::exclusive);
    }

template <typename T>
    void amrex_stable_partition_helper (T* p, int n2)
    {
        if (n2 > 1) {
            int npairs = n2/2;
            amrex::ParallelFor(npairs, [=] AMREX_GPU_DEVICE (int i) noexcept
            {
                amrex::Swap(p[i], p[n2-1-i]);
            });
            if (!Gpu::inNoSyncRegion()) {
                Gpu::streamSynchronize();
            }
        }
    }

template <class FAB>
void
FabArray<FAB>::PC_local_cpu (const CPC& thecpc, FabArray<FAB> const& src,
                             int scomp, int dcomp, int ncomp, CpOp op)
{
    auto const N_locs = static_cast<int>(thecpc.m_LocTags->size());
    if (N_locs == 0) { return; }
    bool is_thread_safe = thecpc.m_threadsafe_loc;

    if (is_thread_safe)
    {
#ifdef AMREX_USE_OMP
#pragma omp parallel for
#endif
        for (int i = 0; i < N_locs; ++i)
        {
            const CopyComTag& tag = (*thecpc.m_LocTags)[i];
#ifdef BL_USE_TEAM
            // With MPI teams, the tags include teammates' FABs. Only write our own.
            if (distributionMap[tag.dstIndex] != ParallelDescriptor::MyProc()) { continue; }
#endif
            if (this != &src || tag.dstIndex != tag.srcIndex || tag.sbox != tag.dbox) {
                // avoid self copy or plus
                const FAB* sfab = &(src[tag.srcIndex]);
                      FAB* dfab = &(get(tag.dstIndex));
                if (op == FabArrayBase::COPY)
                {
                    dfab->template copy<RunOn::Host>(*sfab, tag.sbox, scomp, tag.dbox, dcomp, ncomp);
                }
                else
                {
                    dfab->template plus<RunOn::Host>(*sfab, tag.sbox, tag.dbox, scomp, dcomp, ncomp);
                }
            }
        }
#ifdef BL_USE_TEAM
        // Teammates may read our FABs next.
        if (ParallelDescriptor::TeamSize() > 1) { ParallelDescriptor::MyTeam().MemoryBarrier(); }
#endif
    }
    else
    {
        LayoutData<Vector<FabCopyTag<FAB> > > loc_copy_tags(boxArray(),DistributionMap());
        for (int i = 0; i < N_locs; ++i)
        {
            const CopyComTag& tag = (*thecpc.m_LocTags)[i];
            if (this != &src || tag.dstIndex != tag.srcIndex || tag.sbox != tag.dbox) {
                loc_copy_tags[tag.dstIndex].push_back
                    ({src.fabPtr(tag.srcIndex), tag.dbox, tag.sbox.smallEnd()-tag.dbox.smallEnd()});
            }
        }

            }
        }

#ifdef AMREX_USE_OMP
#pragma omp parallel
#endif
        for (MFIter mfi(*this); mfi.isValid(); ++mfi)
        {
            const auto& tags = loc_copy_tags[mfi];
            auto dfab = this->array(mfi);
            if (op == FabArrayBase::COPY)
            {
                for (auto const & tag : tags)
                {
                    auto const sfab = tag.sfab->array();
                    Dim3 offset = tag.offset.dim3();
                    amrex::LoopConcurrentOnCpu (tag.dbox, ncomp,
                    [=] (int i, int j, int k, int n) noexcept
                    {
                        dfab(i,j,k,dcomp+n) = sfab(i+offset.x,j+offset.y,k+offset.z,scomp+n);
                    });
                }
            }
            else
            {
                for (auto const & tag : tags)
                {
                    auto const sfab = tag.sfab->array();
                    Dim3 offset = tag.offset.dim3();
                    amrex::LoopConcurrentOnCpu (tag.dbox, ncomp,
                    [=] (int i, int j, int k, int n) noexcept
                    {
                        dfab(i,j,k,dcomp+n) += sfab(i+offset.x,j+offset.y,k+offset.z,scomp+n);
                    });
                }
            }
        }
    }
}

template <class FAB>
void
FabArray<FAB>::PC_local_gpu (const CPC& thecpc, FabArray<FAB> const& src,
                             int scomp, int dcomp, int ncomp, CpOp op,
                             bool deterministic)
{
    auto const N_locs = static_cast<int>(thecpc.m_LocTags->size());
    if (N_locs == 0) { return; }
    bool is_thread_safe = thecpc.m_threadsafe_loc;

    // Deterministic handling is only implemented for ADD.
    if (deterministic) { AMREX_ALWAYS_ASSERT(op == FabArrayBase::ADD); }

    using TagType = Array4CopyTag<value_type>;
    Vector<TagType> loc_copy_tags;
    loc_copy_tags.reserve(N_locs);

    Vector<BaseFab<int> > maskfabs;
    Vector<Array4Tag<int> > masks_unique;
    Vector<Array4Tag<int> > masks;
    if (!is_thread_safe)
    {
        if ((op == FabArrayBase::COPY && !amrex::IsStoreAtomic<value_type>::value) ||
            (op == FabArrayBase::ADD  && !amrex::HasAtomicAdd <value_type>::value &&
             !deterministic))
        {
            maskfabs.resize(this->local_size());
            masks_unique.reserve(this->local_size());
            masks.reserve(N_locs);
        }
    }

    for (int i = 0; i < N_locs; ++i)
    {
        const CopyComTag& tag = (*thecpc.m_LocTags)[i];
        if (this != &src || tag.dstIndex != tag.srcIndex || tag.sbox != tag.dbox) {
            int li = this->localindex(tag.dstIndex);
            loc_copy_tags.push_back(
                TagType{.dfab   = this->atLocalIdx(li).array(),
                        .dindex = tag.dstIndex,
                        .sfab   = src.fabPtr(tag.srcIndex)->const_array(),
                        .dbox   = tag.dbox,
                        .offset = (tag.sbox.smallEnd()-tag.dbox.smallEnd()).dim3()});

            if (maskfabs.size() > 0) {
                if (!maskfabs[li].isAllocated()) {
                    maskfabs[li].resize(this->atLocalIdx(li).box());
                    masks_unique.emplace_back(Array4Tag<int>{.dfab = maskfabs[li].array()});
                }

                    maskfabs[li].resize(this->atLocalIdx(li).box());
                    masks_unique.emplace_back(Array4Tag<int>{.dfab = maskfabs[li].array()});
                }
                masks.emplace_back(Array4Tag<int>{.dfab = maskfabs[li].array()});
            }
        }
    }

    if (maskfabs.size() > 0) {
        amrex::ParallelFor(masks_unique,
        [=] AMREX_GPU_DEVICE (int i, int j, int k, Array4Tag<int> const& msk) noexcept
        {
            msk.dfab(i,j,k) = 0;
        });
    }

    if (op == FabArrayBase::COPY)
    {
        if (is_thread_safe) {
            detail::fab_to_fab<value_type, value_type>(loc_copy_tags, scomp,
                dcomp, ncomp, detail::CellStore<value_type, value_type>());
        } else {
            detail::fab_to_fab_atomic_cpy<value_type, value_type>(
                loc_copy_tags, scomp, dcomp, ncomp, masks);
        }
    }
    else
    {
        if (is_thread_safe) {
            // Non-overlapping destinations: a plain add is already bitwise
            // reproducible, so no need for the heavier deterministic kernel.
            detail::fab_to_fab<value_type, value_type>(loc_copy_tags, scomp,
                dcomp, ncomp, detail::CellAdd<value_type, value_type>());
        } else if (deterministic) {
            // Use deterministic_fab_to_fab for ADD operations to ensure bitwise
            // reproducibility. The atomic add operations (fab_to_fab_atomic_add) are
            // non-deterministic because the order of atomic additions is not guaranteed.
            detail::deterministic_fab_to_fab<value_type, value_type>(
                loc_copy_tags, scomp, dcomp, ncomp, detail::CellAdd<value_type, value_type>());
        } else {
            detail::fab_to_fab_atomic_add<value_type, value_type>(
                loc_copy_tags, scomp, dcomp, ncomp, masks);
        }
    }
}

std::vector<IntVect>
Periodicity::shiftIntVect (IntVect const& nghost) const
{
    std::vector<IntVect> r;

    int per[3] = {0,0,0};
    int jmp[3] = {1,1,1};

    for (int i = 0; i < AMREX_SPACEDIM; ++i) {
        if (isPeriodic(i)) {
            per[i] = jmp[i] = period[i];
            while (per[i] < nghost[i]) {
                per[i] += period[i];
            }
        }
    }

    for (int i = -per[0]; i <= per[0]; i += jmp[0]) {
    for (int j = -per[1]; j <= per[1]; j += jmp[1]) {
    for (int k = -per[2]; k <= per[2]; k += jmp[2]) {
        r.emplace_back(AMREX_D_DECL(i,j,k));
    }
    }
    }

    return r;
}

Box
Periodicity::Domain () const noexcept
{
    Box pdomain;
    for (int i = 0; i < AMREX_SPACEDIM; ++i) {
        if (isPeriodic(i)) {
            pdomain.setSmall(i,0);
            pdomain.setBig  (i,period[i]-1);
        } else {
            pdomain.setSmall(i, std::numeric_limits<int>::min());
            pdomain.setBig(i, std::numeric_limits<int>::max()-1); // so that it can be nodalized.
        }
    }
    return pdomain;
}

const Periodicity&
Periodicity::NonPeriodic () noexcept
{
    static const Periodicity np(IntVect(AMREX_D_DECL(0,0,0)));
    return np;
}

/**
* \brief This provides length of period for periodic domains.  0 means it is
* not periodic in that direction.
* It is also assumed that the periodic domain starts with index 0.
*/
class Periodicity
{
public:
    Periodicity () noexcept : period(AMREX_D_DECL(0,0,0)) {}
    explicit Periodicity (const IntVect& v) noexcept : period(v) {}

    [[nodiscard]] bool isAnyPeriodic () const noexcept
        { return AMREX_D_TERM(period[0]>0, || period[1]>0, || period[2]>0); }
    [[nodiscard]] bool isAllPeriodic () const noexcept
        { return AMREX_D_TERM(period[0]>0, && period[1]>0, && period[2]>0); }
    [[nodiscard]] bool isPeriodic (int dir) const noexcept
        { return period[dir]>0; }

    bool operator==(const Periodicity& rhs) const noexcept
        { return period == rhs.period; }

    //! Cell-centered domain Box "infinitely" long in non-periodic directions.
    [[nodiscard]] Box Domain () const noexcept;

    [[nodiscard]] IntVect const& intVect () const { return period; }

    [[nodiscard]] std::vector<IntVect> shiftIntVect (IntVect const& nghost = IntVect(0)) const;

    static const Periodicity& NonPeriodic () noexcept;

private:
    IntVect period;
}

void
BndryFuncArray::operator () (Box const& /*bx*/, FArrayBox& dest,
                             int dcomp, int numcomp,
                             Geometry const& geom, Real time,
                             const Vector<BCRec>& bcr, int bcomp, // BCRec for this box
                             int /*orig_comp*/)
{
    BL_ASSERT(m_func != nullptr || m_func3D != nullptr);

    const int*  lo = dest.loVect();
    const int*  hi = dest.hiVect();
    const Box& domain = geom.Domain();
    const int* dom_lo = domain.loVect();
    const int* dom_hi = domain.hiVect();
    const Real* dx = geom.CellSize();

    Real grd_lo[AMREX_SPACEDIM];
    const Real* problo = geom.ProbLo();
    for (int i = 0; i < AMREX_SPACEDIM; i++)
    {
        grd_lo[i] = problo[i] + dx[i]*static_cast<Real>(lo[i]-dom_lo[i]);
    }

    static_assert(sizeof(BCRec) == 2*AMREX_SPACEDIM*sizeof(int),
                  "Let us know if this assertion fails");

    for (int icomp = 0; icomp < numcomp; ++icomp)
    {
        Real* data = dest.dataPtr(dcomp+icomp);
        if (m_func != nullptr) {
            m_func(data,AMREX_ARLIM(lo),AMREX_ARLIM(hi),
                   dom_lo,dom_hi,
                   dx,grd_lo,&time,bcr[bcomp+icomp].vect());
        } else {
            m_func3D(data,AMREX_ARLIM_3D(lo),AMREX_ARLIM_3D(hi),
                     AMREX_ARLIM_3D(dom_lo),AMREX_ARLIM_3D(dom_hi),
                     AMREX_ZFILL(dx),AMREX_ZFILL(grd_lo),&time,bcr[bcomp+icomp].vect());
        }
    }
}

void
CpuBndryFuncFab::operator() (Box const& bx, FArrayBox& dest,
                             int dcomp, int numcomp,
                             Geometry const& geom, Real time,
                             const Vector<BCRec>& bcr, int bcomp,
                             int orig_comp)
{
    const int* lo = dest.loVect();
    const Box& domain = amrex::convert(geom.Domain(),bx.ixType());
    const int* dom_lo = domain.loVect();
    const Real* dx = geom.CellSize();
    const Real* problo = geom.ProbLo();
    Real xlo[AMREX_SPACEDIM];
    for (int i = 0; i < AMREX_SPACEDIM; i++)
    {
        xlo[i] = problo[i] + dx[i]*static_cast<Real>(lo[i]-dom_lo[i]);
    }
    if (bx.ixType().cellCentered()) {
        fab_filcc(bx, dest.array(dcomp), numcomp, domain, dx, xlo, &(bcr[bcomp]));
    } else if (bx.ixType().nodeCentered()) {
        fab_filnd(bx, dest.array(dcomp), numcomp, domain, dx, xlo, &(bcr[bcomp]));
    } else {
        fab_filfc(bx, dest.array(dcomp), numcomp, domain, dx, xlo, &(bcr[bcomp]));
    }

    if (f_user != nullptr)
    {
        f_user(bx, dest.array(), dcomp, numcomp, geom.data(), time,
               &(bcr[bcomp]), 0, orig_comp);
    }
}

