PlotFileDataImpl::PlotFileDataImpl (std::string const& plotfile_name)
    : m_plotfile_name(plotfile_name)
{
    // Header
    std::string File(plotfile_name+"/Header");
    Vector<char> fileCharPtr;
    ParallelDescriptor::ReadAndBcastFile(File, fileCharPtr);
    std::istringstream is(std::string(fileCharPtr.dataPtr()), std::istringstream::in);

    is >> m_file_version;

    is >> m_ncomp;
    AMREX_ASSERT(m_ncomp >= 0 && m_ncomp < std::numeric_limits<int>::max());
    m_var_names.resize(m_ncomp);
    GotoNextLine(is); // This is needed, otherwise the next getline will get an empty string.
    for (int i = 0; i < m_ncomp; ++i) {
        std::string tmp;
        std::getline(is, tmp);
        m_var_names[i] = amrex::trim(std::move(tmp));
    }

    is >> m_spacedim >> m_time >> m_finest_level;
    m_nlevels = m_finest_level+1;
    AMREX_ASSERT(m_finest_level >= 0 && m_finest_level < 1000);
    AMREX_ALWAYS_ASSERT_WITH_MESSAGE(m_spacedim >= 1 && m_spacedim <= AMREX_SPACEDIM,
                                     "PlotFileData: plotfile dimension exceeds AMREX_SPACEDIM");

    for (int i = 0; i < m_spacedim; ++i) {
        is >> m_prob_lo[i];
    }
    for (int i = 0; i < m_spacedim; ++i) {
        is >> m_prob_hi[i];
        m_prob_size[i] = m_prob_hi[i] - m_prob_lo[i];
    }

    AMREX_ASSERT(m_nlevels > 0 && m_nlevels <= 1000);
    m_ref_ratio.resize(m_nlevels, 0);
    for (int i = 0; i < m_finest_level; ++i) {
        is >> m_ref_ratio[i];
    }
    GotoNextLine(is);

    m_prob_domain.resize(m_nlevels);
    for (int i = 0; i < m_nlevels; ++i) {
        is >> m_prob_domain[i];
    }

    m_level_steps.resize(m_nlevels);
    for (int i = 0; i < m_nlevels; ++i) {
        is >> m_level_steps[i];
    }

    m_cell_size.resize(m_nlevels, Array<Real,AMREX_SPACEDIM>{{AMREX_D_DECL(1.,1.,1.)}});
    for (int ilev = 0; ilev < m_nlevels; ++ilev) {
        for (int idim = 0; idim < m_spacedim; ++idim) {
            is >> m_cell_size[ilev][idim];
        }
    }

        }
    }

    is >> m_coordsys;
    int bwidth;
    is >> bwidth;

    m_mf_name.resize(m_nlevels);
    m_vismf.resize(m_nlevels);
    m_ba.resize(m_nlevels);
    m_dmap.resize(m_nlevels);
    m_ngrow.resize(m_nlevels);
    for (int ilev = 0; ilev < m_nlevels; ++ilev) {
        int levtmp, ngrids, levsteptmp;
        Real gtime;
        is >> levtmp >> ngrids >> gtime;
        is >> levsteptmp;
        Real glo[3], ghi[3];
        AMREX_ASSERT(ngrids >= 0 && ngrids < std::numeric_limits<int>::max());
        for (int igrid = 0; igrid < ngrids; ++igrid) {
            for (int idim = 0; idim < m_spacedim; ++idim) {
                is >> glo[idim] >> ghi[idim];
            }
        }
        std::string relname;
        is >> relname;
        m_mf_name[ilev] = m_plotfile_name + "/" + relname;
        if (m_ncomp > 0) {
            m_vismf[ilev] = std::make_unique<VisMF>(m_mf_name[ilev]);
            m_ba[ilev] = m_vismf[ilev]->boxArray();
            m_dmap[ilev].define(m_ba[ilev]);
            m_ngrow[ilev] = m_vismf[ilev]->nGrowVect();
        }
    }
}

void
PlotFileDataImpl::syncDistributionMap (PlotFileDataImpl const& src)
{
    int nlevs_min = std::min(m_nlevels, src.m_nlevels);
    for (int ilev = 0; ilev < nlevs_min; ++ilev) {
        syncDistributionMap(ilev, src);
    }
}

void
PlotFileDataImpl::syncDistributionMap (int level, PlotFileDataImpl const& src)
{
    if (level <= src.finestLevel() && m_dmap[level].size() == src.DistributionMap(level).size()) {
        m_dmap[level] = src.DistributionMap(level);
    }
}

MultiFab
PlotFileDataImpl::get (int level)
{
    MultiFab mf(m_ba[level], m_dmap[level], m_ncomp, m_ngrow[level]);
    VisMF::Read(mf, m_mf_name[level]);
    return mf;
}

MultiFab
PlotFileDataImpl::get (int level, std::string const& varname)
{
    MultiFab mf(m_ba[level], m_dmap[level], 1, m_ngrow[level]);
    auto r = std::ranges::find(m_var_names, varname);
    if (r == std::end(m_var_names)) {
        amrex::Abort("PlotFileDataImpl::get: varname not found "+varname);
    } else {
        int icomp = static_cast<int>(std::distance(std::begin(m_var_names), r));
        for (MFIter mfi(mf); mfi.isValid(); ++mfi) {
            int gid = mfi.index();
            FArrayBox& dstfab = mf[mfi];
            std::unique_ptr<FArrayBox> srcfab(m_vismf[level]->readFAB(gid, icomp));
            dstfab.copy<RunOn::Device>(*srcfab);
            Gpu::streamSynchronize(); // srcfab is freed at the end of this iteration
        }
    }
    return mf;
}

class PlotFileDataImpl
{
public:
    PlotFileDataImpl (std::string const& plotfile_name);

    [[nodiscard]] int spaceDim () const noexcept { return m_spacedim; }

    [[nodiscard]] Real time () const noexcept { return m_time; }

    [[nodiscard]] int finestLevel () const noexcept { return m_finest_level; }

    [[nodiscard]] int refRatio (int level) const { return m_ref_ratio[level]; }

    [[nodiscard]] IntVect refRatioVect (int level) const {
        if (level >= 0 && level < m_finest_level) {
            auto flen = probDomain(level+1).length();
            auto clen = probDomain(level  ).length();
            auto ratio = flen / clen;
            AMREX_ASSERT(ratio*clen == flen);
            return ratio;
        } else {
            return IntVect(0);
        }
    }

    [[nodiscard]] int levelStep (int level) const { return m_level_steps[level]; }

    [[nodiscard]] const BoxArray& boxArray (int level) const { return m_ba[level]; }

    [[nodiscard]] const DistributionMapping& DistributionMap (int level) const { return m_dmap[level]; }

    void syncDistributionMap (PlotFileDataImpl const& src);

    void syncDistributionMap (int level, PlotFileDataImpl const& src);

    [[nodiscard]] int coordSys () const noexcept { return m_coordsys; }

    [[nodiscard]] Box probDomain (int level) const { return m_prob_domain[level]; }

    [[nodiscard]] Array<Real,AMREX_SPACEDIM> probSize () const noexcept { return m_prob_size; }
    [[nodiscard]] Array<Real,AMREX_SPACEDIM> probLo () const noexcept { return m_prob_lo; }
    [[nodiscard]] Array<Real,AMREX_SPACEDIM> probHi () const noexcept { return m_prob_hi; }
    [[nodiscard]] Array<Real,AMREX_SPACEDIM> cellSize (int level) const { return m_cell_size[level]; }

    [[nodiscard]] const Vector<std::string>& varNames () const noexcept { return m_var_names; }

    [[nodiscard]] int nComp () const noexcept { return m_ncomp; }
    [[nodiscard]] IntVect nGrowVect (int level) const { return m_ngrow[level]; }

    [[nodiscard]] int nComp () const noexcept { return m_ncomp; }
    [[nodiscard]] IntVect nGrowVect (int level) const { return m_ngrow[level]; }

    MultiFab get (int level);
    MultiFab get (int level, std::string const& varname);

private:
    std::string m_plotfile_name;
    std::string m_file_version;
    int m_ncomp;
    Vector<std::string> m_var_names;
    int m_spacedim;
    Real m_time;
    int m_finest_level, m_nlevels;
    Array<Real,AMREX_SPACEDIM> m_prob_lo {{AMREX_D_DECL(0.,0.,0.)}};
    Array<Real,AMREX_SPACEDIM> m_prob_hi {{AMREX_D_DECL(1.,1.,1.)}};
