                            [=] AMREX_GPU_DEVICE (int i, T const& x) { out[i] = x; },
                            Type::inclusive, a_ret_sum);
    } else {
        return PrefixSum<T>(n,
                            [=] AMREX_GPU_DEVICE (N i) -> T { return in[i]; },
                            [=] AMREX_GPU_DEVICE (N i, T const& x) { out[i] = x; },
                            Type::inclusive, a_ret_sum);
    }
#endif
}

/**
 * \ingroup amrex_collectives
 *
 * \brief Exclusive sum
 *
 * \param n number of elements
 * \param in input
 * \param out output
 * \param a_ret_sum control the return value
 * \return return the total sum if `a_ret_sum` is true
 */
template <std::integral N, typename T >
T ExclusiveSum (N n, T const* in, T * out, RetSum a_ret_sum = retSum)
{
    if (n <= 0) { return 0; }
#if defined(AMREX_USE_CUDA)
    T in_last = 0;
    if (a_ret_sum) {
        Gpu::dtoh_memcpy_async(&in_last, in+(n-1), sizeof(T));
    }
    void* d_temp = nullptr;
    std::size_t temp_bytes = 0;
    AMREX_GPU_SAFE_CALL(cub::DeviceScan::ExclusiveSum(d_temp, temp_bytes, in, out, n,
                                                      Gpu::gpuStream()));
    d_temp = The_Arena()->alloc(temp_bytes);
    AMREX_GPU_SAFE_CALL(cub::DeviceScan::ExclusiveSum(d_temp, temp_bytes, in, out, n,
                                                      Gpu::gpuStream()));
    T out_last = 0;
    if (a_ret_sum) {
        Gpu::dtoh_memcpy_async(&out_last, out+(n-1), sizeof(T));
    }
    Gpu::streamSynchronize();
    The_Arena()->free(d_temp);
    AMREX_GPU_ERROR_CHECK();
    return in_last+out_last;
#elif defined(AMREX_USE_HIP)
    T in_last = 0;
    if (a_ret_sum) {
        Gpu::dtoh_memcpy_async(&in_last, in+(n-1), sizeof(T));
    }
    void* d_temp = nullptr;
    std::size_t temp_bytes = 0;
    AMREX_GPU_SAFE_CALL(rocprim::exclusive_scan(d_temp, temp_bytes, in, out, T{0}, n,
                                                rocprim::plus<T>(), Gpu::gpuStream()));
    d_temp = The_Arena()->alloc(temp_bytes);
    AMREX_GPU_SAFE_CALL(rocprim::exclusive_scan(d_temp, temp_bytes, in, out, T{0}, n,
                                                rocprim::plus<T>(), Gpu::gpuStream()));
    T out_last = 0;
    if (a_ret_sum) {
        Gpu::dtoh_memcpy_async(&out_last, out+(n-1), sizeof(T));
    }
    Gpu::streamSynchronize();
    The_Arena()->free(d_temp);
    AMREX_GPU_ERROR_CHECK();
    return in_last+out_last;

    The_Arena()->free(d_temp);
    AMREX_GPU_ERROR_CHECK();
    return in_last+out_last;
#elif defined(AMREX_USE_SYCL) && defined(AMREX_USE_ONEDPL)
    T in_last = 0;
    if (a_ret_sum) {
        Gpu::dtoh_memcpy_async(&in_last, in+(n-1), sizeof(T));
    }
    auto policy = oneapi::dpl::execution::make_device_policy(Gpu::Device::streamQueue());
    std::exclusive_scan(policy, in, in+n, out, T(0), std::plus<T>());
    T out_last = 0;
    if (a_ret_sum) {
        Gpu::dtoh_memcpy_async(&out_last, out+(n-1), sizeof(T));
    }
    Gpu::streamSynchronize();
    AMREX_GPU_ERROR_CHECK();
    return in_last+out_last;
#else
    if (static_cast<Long>(n) <= static_cast<Long>(std::numeric_limits<int>::max())) {
        return PrefixSum<T>(static_cast<int>(n),
                            [=] AMREX_GPU_DEVICE (int i) -> T { return in[i]; },
                            [=] AMREX_GPU_DEVICE (int i, T const& x) { out[i] = x; },
                            Type::exclusive, a_ret_sum);
    } else {
        return PrefixSum<T>(n,
                            [=] AMREX_GPU_DEVICE (N i) -> T { return in[i]; },
                            [=] AMREX_GPU_DEVICE (N i, T const& x) { out[i] = x; },
                            Type::exclusive, a_ret_sum);
    }
#endif
}

//  !defined(AMREX_USE_GPU)
template <typename T, std::integral N, typename FIN, typename FOUT, typename TYPE>
requires (std::same_as<std::decay_t<TYPE>,Type::Inclusive> ||
          std::same_as<std::decay_t<TYPE>,Type::Exclusive>)
T PrefixSum (N n, FIN const& fin, FOUT const& fout, TYPE, RetSum = retSum)
{
    if (n <= 0) { return 0; }
    T totalsum = 0;
    for (N i = 0; i < n; ++i) {
        T x = fin(i);
        T y = totalsum;
        totalsum += x;
        AMREX_IF_CONSTEXPR (std::is_same_v<std::decay_t<TYPE>,Type::Inclusive>) {
            y += x;
        }
        fout(i, y);
    }
    return totalsum;
}

// The return value is the total sum.
template <std::integral N, typename T >
T InclusiveSum (N n, T const* in, T * out, RetSum /*a_ret_sum*/ = retSum)
{
    std::inclusive_scan(in, in+n, out);
    return (n > 0) ? out[n-1] : T(0);
}

// The return value is the total sum.
template <std::integral N, typename T >
T ExclusiveSum (N n, T const* in, T * out, RetSum /*a_ret_sum*/ = retSum)
{
    if (n <= 0) { return 0; }

    auto in_last = in[n-1];
    std::exclusive_scan(in, in+n, out, T(0));
    return in_last + out[n-1];
}

/// \ingroup amrex_collectives
    template<class InIter, class OutIter>
    OutIter inclusive_scan (InIter begin, InIter end, OutIter result)
    {
#if defined(AMREX_USE_GPU)
        auto N = std::distance(begin, end);
        if (N <= 0) { return result; }
        Scan::InclusiveSum(N, &(*begin), &(*result), Scan::noRetSum);
        OutIter result_end = result;
        std::advance(result_end, N);
        return result_end;
#else
        return std::inclusive_scan(begin, end, result);
#endif
    }

/// \ingroup amrex_collectives
    template<class InIter, class OutIter>
    OutIter exclusive_scan (InIter begin, InIter end, OutIter result)
    {
#if defined(AMREX_USE_GPU)
        auto N = std::distance(begin, end);
        if (N <= 0) { return result; }
        Scan::ExclusiveSum(N, &(*begin), &(*result), Scan::noRetSum);
        OutIter result_end = result;
        std::advance(result_end, N);
        return result_end;
#else
        using T = typename std::iterator_traits<InIter>::value_type;
        return std::exclusive_scan(begin, end, result, T(0));
#endif
    }

/** True if the boolean value is true (scalar identity fallback for simd any_of)
         *
         * Example:
         * ```cpp
         * // Works for both simd_mask and scalar bool:
         * auto mask = a > b;
         * if (amrex::simd::stdx::any_of(mask)) { ... }
         * ```
         *
         * @see https://en.cppreference.com/w/cpp/experimental/simd/any_of
         */
        AMREX_GPU_HOST_DEVICE AMREX_FORCE_INLINE
        bool any_of (bool const v) { return v; }

template <typename T>
            struct where_expression {
                bool mask;
                T* value;

                AMREX_GPU_HOST_DEVICE AMREX_FORCE_INLINE
                where_expression& operator= (T const& new_val)
                {
                    if (mask) { *value = new_val; }
                    return *this;
                }
            };

/** Masked assignment expression (scalar fallback for simd where)
         *
         * Returns an expression object whose assignment operator conditionally
         * updates value only when mask is true.
         *
         * Example:
         * ```cpp
         * // Works for both simd<T> and scalar T:
         * auto mask = b > T(0);
         * T result = T(0);
         * amrex::simd::stdx::where(mask, result) = a / b;
         * ```
         *
         * @see https://en.cppreference.com/w/cpp/experimental/simd/where
         */
        template <typename T>
        AMREX_GPU_HOST_DEVICE AMREX_FORCE_INLINE
        detail::where_expression<T> where (bool const mask, T& value)
        {
            return {mask, &value};
        }

/** Vectorized ternary operator (scalar fallback for simd select)
         *
         * @see select in the AMREX_USE_SIMD path above
         * @see C++26 std::simd select
         */
        template <typename T>
        AMREX_GPU_HOST_DEVICE AMREX_FORCE_INLINE
        T select (bool const mask, T const& true_val, T const& false_val)
        {
            return mask ? true_val : false_val;
        }

/** Mixin Helper Class
     *
     * Use this class as a mixin (base) class to simplify writing functors that support/do not support
     * ParallelForSIMD.
     *
     * Example:
     * ```cpp
     * struct Compute : public Vectorized<>
     * {
     *     template<typename T_Real>
     *     AMREX_GPU_HOST_DEVICE AMREX_FORCE_INLINE
     *     void operator() (T_Real & AMREX_RESTRICT x) { ... }
     * };
     *
     * // ... call site below
     * {
     *     Compute c;
     *
     *     if constexpr (amrex::simd::is_vectorized<Compute>) {
     *         ParallelForSIMD<...>(np, c).
     *     } else {
     *         ParallelFor(np, c);
     *     }
     * }
     * ```
     */
    template<int SIMD_WIDTH = native_simd_size_real>
    struct
    Vectorized : detail::InternalVectorized
    {
        //! SIMD width in elements
        static constexpr int simd_width = SIMD_WIDTH;
    };

/** Check if a function argument is declared as non-const
     *
     * Use in conjunction with conditional write-back logic from vector registers, e.g.,
     *
     * ```cpp
     * template<typename T_Real>
     * void compute (T_Real & AMREX_RESTRICT x,
     *               T_Real const & AMREX_RESTRICT y) { ... }
     *
     * part_x.copy_from(&m_part_x[i], stdx::element_aligned);
     * part_y.copy_from(&m_part_y[i], stdx::element_aligned);
     *
     * compute(part_x, part_y);
     *
     * if constexpr (is_nth_arg_non_const(compute<double>, 0))
     *     part_x.copy_to(&m_part_x[i], stdx::element_aligned);
     * if constexpr (is_nth_arg_non_const(compute<double>, 1))
     *     part_y.copy_to(&m_part_y[i], stdx::element_aligned);
     * ```
     */
    template<typename R, typename... Args>
    constexpr bool is_nth_arg_non_const (R(*)(Args...), int n)
    {
        constexpr bool val_arr[sizeof...(Args)] {!std::is_const_v<std::remove_reference_t<Args>>...};
        return val_arr[n];
    }

/** Load 1D contiguous data from array pointers
     *
     * On GPU and CPU w/o SIMD, this dereferences a 1D array element at the
     * index position i.
     * On CPU with SIMD, this loads a SIMD register at the IndexType::width
     * SIMD-wide index position i.
     *
     * @tparam T data type (amrex::ParticleReal or int or uint64_t)
     * @tparam IndexType int or amrex::SIMDindex<SIMD_WIDTH, int>
     * @param ptr pointer to the array data
     * @param i index or SIMD index
     * @return a reference to the (scalar) data OR a new SIMD variable (register) loaded with data
     */
    template <typename T, typename IndexType>
    AMREX_GPU_HOST_DEVICE AMREX_FORCE_INLINE
    decltype(auto) load_1d (T* ptr, IndexType const i)
    {
        if constexpr (std::is_integral_v<IndexType>) {
            return ptr[i];
        } else if constexpr (IndexType::width == 1) {
            return ptr[i.index];
        } else {
#ifdef AMREX_USE_SIMD
            using DataType = stdx::fixed_size_simd<std::decay_t<T>, IndexType::width>;

            // initialize vector register
            // TODO stdx::vector_aligned needs alignment guarantees
            //      https://github.com/AMReX-Codes/amrex/issues/4592
            //      https://en.cppreference.com/w/cpp/experimental/simd/simd/copy_from
            DataType val;
            val.copy_from(&ptr[i.index], stdx::element_aligned);
            return val;

#else
            static_assert(IndexType::width == 1, "SIMD width must be 1 for non-SIMD builds");
            return ptr[i.index];
#endif
        }
    }

    )
    {
        // SIMD uses special vector register types in ValType that need to be copied back to RAM array type T
        if constexpr (!std::is_same_v<ValType, T>) {
            if constexpr (ForceWriteback || amrex::simd::is_nth_arg_non_const(P_Method, N)) {
#ifdef AMREX_USE_SIMD
                // write back to memory
                // TODO stdx::vector_aligned needs alignment guarantees
                //      https://github.com/AMReX-Codes/amrex/issues/4592
                //      https://en.cppreference.com/w/cpp/experimental/simd/simd/copy_from
                val.copy_to(&ptr[i.index], amrex::simd::stdx::element_aligned);
#else
                amrex::Abort("store_1d: ValType val must alias T ptr data (to make this a no-OP).");
#endif
            }
        }
        amrex::ignore_unused(val, ptr, i);
    }

AMREX_GPU_DEVICE AMREX_FORCE_INLINE
Real amrex_calc_xslope (int i, int j, int k, int n, int order,
                               amrex::Array4<Real const> const& q) noexcept
{
    if (order == 2)
    {
        Real dl = 2.0_rt*(q(i  ,j,k,n) - q(i-1,j,k,n));
        Real dr = 2.0_rt*(q(i+1,j,k,n) - q(i  ,j,k,n));
        Real dc = 0.5_rt*(q(i+1,j,k,n) - q(i-1,j,k,n));
        Real slope = amrex::min(std::abs(dl),std::abs(dc),std::abs(dr));
        slope = (dr*dl > 0.0_rt) ? slope : 0.0_rt;
        return (dc > 0.0_rt) ? slope : -slope;

    } else if (order == 4) {

        Real dlft, drgt, dcen, dfm, dfp, dlim, dsgn, dtemp;
        Real qm, qp, qi;
        qi = q(i,j,k,n);
        qm = q(i-1,j,k,n);
        qp = q(i+1,j,k,n);

        dlft = qm - q(i-2,j,k,n);
        drgt = qi - qm;
        dcen = 0.5_rt*(dlft+drgt);
        dsgn = std::copysign(1.e0_rt, dcen);
        dlim = (dlft*drgt >= 0.0_rt) ? 2.0_rt*amrex::min(std::abs(dlft), std::abs(drgt)) : 0.0_rt;
        dfm = dsgn*amrex::min(dlim, std::abs(dcen));

        dlft = qp - qi;
        drgt = q(i+2,j,k,n) - qp;
        dcen = 0.5_rt*(dlft+drgt);
        dsgn = std::copysign(1.e0_rt, dcen);
        dlim = (dlft*drgt >= 0.0_rt) ? 2.0_rt*amrex::min(std::abs(dlft), std::abs(drgt)) : 0.0_rt;
        dfp = dsgn*amrex::min(dlim, std::abs(dcen));

        dlft = qi - qm;
        drgt = qp - qi;
        dcen = 0.5_rt*(dlft+drgt);
        dsgn = std::copysign(1.e0_rt, dcen);
        dlim = (dlft*drgt >= 0.0_rt) ? 2.0_rt*amrex::min(std::abs(dlft), std::abs(drgt)) : 0.0_rt;

        dtemp  = 4.0_rt/3.0_rt*dcen - 1.0_rt/6.0_rt*(dfp + dfm);

        return dsgn*amrex::min(dlim, std::abs(dtemp));

    } else {
        return 0._rt;
    }
}

