            requires (NRows==1 || NCols==1)
        {
            static_assert(StartIndex == 0 || StartIndex == 1);
            if constexpr (StartIndex == 1) {
                --i;
            }
            AMREX_ASSERT(i >= 0);
            AMREX_ASSERT(i < NRows*NCols);
