                                    i, j, begin[0], end[0]-1, begin[1], end[1]-1);
                amrex::Abort();
            ))
            AMREX_IF_ON_HOST((
                std::stringstream ss;

            ))
            AMREX_IF_ON_HOST((
                std::stringstream ss;
