void
TinyProfiler::start ()
{
    if (!enabled) { return; }

    memory_start();

#ifdef AMREX_USE_OMP
#pragma omp master
#endif
    {
        AMREX_ALWAYS_ASSERT_WITH_MESSAGE(stats.empty() && selective_stats.empty(),
            "TinyProfiler cannot be started twice");
    }

#ifdef AMREX_USE_OMP
#pragma omp master
#endif
    if (!regionstack.empty()) {

#ifdef AMREX_USE_GPU
        if (gpu_sync || device_synchronize_around_region) {
            amrex::Gpu::streamSynchronize();
        }
        // With device_synchronize_around_region, every timer is synchronized,
        // so the complete report is kept. On CPU, key.gpu_sync stays false.
        key.gpu_sync = gpu_sync && !device_synchronize_around_region;
#endif

        const double t = amrex::second();

        if (key.gpu_sync) {
            selective_reporting = true;
        }

        ttstack.emplace_back(t, 0.0, &key.name, 0.0);
        global_depth = static_cast<int>(ttstack.size());
#ifdef AMREX_USE_OMP
        in_parallel_region = omp_in_parallel();
#else
        in_parallel_region = false;
#endif

#ifdef AMREX_USE_CUDA
        nvtxRangePush(key.name.c_str());
#elif defined(AMREX_USE_HIP) && defined(AMREX_USE_ROCTX)
        roctxRangePush(key.name.c_str());
#endif

        const char* name = nullptr;
        for (auto const& region : regionstack)
        {
            const auto it = statsmap[region].try_emplace(key).first;
            name = it->first.name.c_str();
            Stats& st = it->second;
            ++st.depth;
            stats.push_back(&st);
        }
        // Only the (OpenMP master) thread that runs the profilers writes current_name
        prev_name = current_name.load(std::memory_order_relaxed);
        current_name.store(name, std::memory_order_release);

#ifdef AMREX_USE_GPU
        // The focused report is only possible on GPU builds.
        if (global_depth == 1 || key.gpu_sync) {
            Stats& st = selective_statsmap[mainregion][key];
            ++st.depth;

        if (global_depth == 1 || key.gpu_sync) {
            Stats& st = selective_statsmap[mainregion][key];
            ++st.depth;
            selective_stats.push_back(&st);
        }
        if (key.gpu_sync) {
            for (auto const& region : selective_regionstack) {
                Stats& st = selective_statsmap[region][key];
                ++st.depth;
                selective_stats.push_back(&st);
            }
        }
#endif

        if (verbose) {
            ++n_print_tabs;
            std::string whitespace;
            for (int itab = 0; itab < n_print_tabs; ++itab) {
                whitespace += "  ";
            }
            // If we try to print to output_file here, it may not be thread
            // safe. Also note that this is controlled by verbose already.
            amrex::Print() << whitespace << "TP: Entering " << key.name << '\n';
        }
    }
}

void
TinyProfiler::stop ()
{
    if (!enabled) { return; }

    memory_stop();

#ifdef AMREX_USE_OMP
#pragma omp master
#endif
    if (!stats.empty()) {

#ifdef AMREX_USE_GPU
        if (gpu_sync || device_synchronize_around_region) {
            amrex::Gpu::streamSynchronize();
        }
#endif

        const double t = amrex::second();

        AMREX_ALWAYS_ASSERT_WITH_MESSAGE(std::ssize(ttstack) == global_depth,
            "TinyProfiler sections must be nested with respect to each other");
#ifdef AMREX_USE_OMP
        AMREX_ALWAYS_ASSERT_WITH_MESSAGE(in_parallel_region == omp_in_parallel(),
            "TinyProfiler sections must be nested with respect to parallel regions");
#endif

        {
            auto const& tt = ttstack.back();

            // first: wall time when the pair is pushed into the stack
            // second: accumulated dt of children
            // fourth: accumulated dt of children shown in the focused report
            double dtin = t - std::get<0>(tt); // elapsed time since start() is called.
            double dtex = dtin - std::get<1>(tt);
            double const shown_child_time = std::get<3>(tt);

            for (Stats* st : stats)
            {
                --(st->depth);
                ++(st->n);
                if (st->depth == 0) {
                    st->dtin += dtin;
                }
                st->dtex += dtex;
            }

            for (Stats* st : selective_stats)
            {
                --(st->depth);
                ++(st->n);
                if (st->depth == 0) {
                    st->dtin += dtin;
                }
                st->dtex += dtin - shown_child_time;
            }

            ttstack.pop_back();
            current_name.store(prev_name, std::memory_order_release);
            if (!ttstack.empty()) {
                auto& parent = ttstack.back();
                std::get<1>(parent) += dtin;
                // A hidden timer passes up only the time of its shown descendants,

                auto& parent = ttstack.back();
                std::get<1>(parent) += dtin;
                // A hidden timer passes up only the time of its shown descendants,
                // so its own time stays with the nearest shown ancestor.
                std::get<3>(parent) += selective_stats.empty() ? shown_child_time : dtin;
            }

#ifdef AMREX_USE_CUDA
            nvtxRangePop();
#elif defined(AMREX_USE_HIP) && defined(AMREX_USE_ROCTX)
            roctxRangePop();
#endif
        }

        stats.clear();
        selective_stats.clear();

        if (verbose) {
            std::string whitespace;
            for (int itab = 0; itab < n_print_tabs; ++itab) {
                whitespace += "  ";
            }
            --n_print_tabs;
            // If we try to print to output_file here, it may not be thread
            // safe. Also note that this is controlled by verbose already.
            amrex::Print() << whitespace << "TP: Leaving  " << key.name << '\n';
        }
    }
}

void
TinyProfiler::memory_start () const noexcept
{
    if (!memprof_enabled) { return; }

    // multiple omp threads may share the same TinyProfiler object so this function must be const
    // it is NOT allowed to double start a section
#ifdef AMREX_USE_OMP
    if (omp_in_parallel()) {
        mem_stack_thread_private[omp_get_thread_num()].deque.push_back(this);
    } else
#endif
    {
        mem_stack.push_back(this);
    }
}

void
TinyProfiler::memory_stop () const noexcept
{
    if (!memprof_enabled) { return; }

    // multiple omp threads may share the same TinyProfiler object so this function must be const
    // it IS allowed to double stop a section
#ifdef AMREX_USE_OMP
    if (omp_in_parallel()) {
        if (!mem_stack_thread_private[omp_get_thread_num()].deque.empty() &&
            mem_stack_thread_private[omp_get_thread_num()].deque.back() == this) {
            mem_stack_thread_private[omp_get_thread_num()].deque.pop_back();
        }
    } else
#endif
    {
        if (!mem_stack.empty() && mem_stack.back() == this) {
            mem_stack.pop_back();
        }
    }
}

MemStat*
TinyProfiler::memory_alloc (std::size_t nbytes, std::map<std::string, MemStat>& memstats) noexcept
{
    if (!memprof_enabled) { return nullptr; }

    // this function is not thread safe for the same memstats
    // the caller of this function (CArena::alloc) has a mutex
    MemStat* stat = nullptr;
#ifdef AMREX_USE_OMP
    if (omp_in_parallel() && !mem_stack_thread_private[omp_get_thread_num()].deque.empty()) {
        stat = &memstats[
            mem_stack_thread_private[omp_get_thread_num()].deque.back()->key.name
        ];
    } else
#endif
    if (!mem_stack.empty()) {
        stat = &memstats[mem_stack.back()->key.name];
    } else {
        stat = &memstats["Unprofiled"];
    }

    ++stat->nalloc;
    stat->currentmem += static_cast<Long>(nbytes);
    stat->avgmem -= static_cast<double>(nbytes) * amrex::second();
    stat->maxmem = std::max(stat->maxmem, stat->currentmem);

    return stat;
}

void
TinyProfiler::memory_free (std::size_t nbytes, MemStat* stat) noexcept
{
    if (!memprof_enabled) { return; }

    // this function is not thread safe for the same stat
    // the caller of this function (CArena::free) has a mutex
    if (stat) {
        ++stat->nfree;
        stat->avgmem += static_cast<double>(nbytes) * amrex::second();
        stat->currentmem -= static_cast<Long>(nbytes);
    }
}

void
TinyProfiler::Initialize ()
{
    selective_regionstack.clear();
    selective_statsmap.clear();
    selective_reporting = false;

    {
        amrex::ParmParse pp("tiny_profiler");
        pp.queryAdd("device_synchronize_around_region", device_synchronize_around_region);
        if (! pp.query("verbose", "v", verbose)) {
            pp.add("verbose", verbose);
        }
        // Specify the maximum percentage of inclusive time
        // that the "Other" section in the output can have (default 1%)
        pp.queryAdd("print_threshold", print_threshold);

        pp.queryAdd("enabled", enabled);
    }

    // Re-arm the output-file read for this cycle and reset the cached value, so
    // a new tiny_profiler.output_file is picked up across init/finalize cycles
    // and a cycle that sets nothing falls back to the default (stdout).
    output_file_read = false;
    output_file = "stdout";

    if (!enabled) { return; }

    regionstack.emplace_back(mainregion);
    t_init = amrex::second();

    finalized = false;
}

void
TinyProfiler::MemoryInitialize ()
{
    {
        amrex::ParmParse pp("tiny_profiler");
        pp.queryAdd("enabled", enabled);
        pp.queryAdd("memprof_enabled", memprof_enabled);
        memprof_enabled = memprof_enabled && enabled;
    }

    if (!memprof_enabled) { return; }

#ifdef AMREX_USE_OMP
    mem_stack_thread_private.resize(omp_get_max_threads());
#endif

    t_memory_init = amrex::second();

    memprof_finalized = false;
}

void
TinyProfiler::Finalize (bool bFlushing)
{
    if (!enabled) { return; }

    if (!bFlushing) {                // If flushing, don't make this the last time!
        if (finalized) {
            return;
        } else {
            finalized = true;
        }
    }

    double t_final = amrex::second();

    bool use_selective_stats = false;
#ifdef AMREX_USE_GPU
    use_selective_stats = selective_reporting;
    ParallelDescriptor::ReduceBoolOr(use_selective_stats);
#endif

    // Make a local copy so that timers completed during output are not included.
    auto lstatsmap = use_selective_stats ? selective_statsmap : statsmap;

    int nprocs = ParallelDescriptor::NProcs();
    int ioproc = ParallelDescriptor::IOProcessorNumber();

    double dt_max = t_final - t_init;
    ParallelReduce::Max(dt_max, ioproc, ParallelDescriptor::Communicator());
    double dt_min = t_final - t_init;
    ParallelReduce::Min(dt_min, ioproc, ParallelDescriptor::Communicator());
    double dt_avg = t_final - t_init;
    ParallelReduce::Sum(dt_avg, ioproc, ParallelDescriptor::Communicator());
    dt_avg /= double(nprocs);

    std::ofstream ofs;
    std::ostream* os = nullptr;
    if (ParallelDescriptor::IOProcessor()) {
        os = open_output_stream(get_output_file(), ofs);
    }

    IOFormatSaver iofmtsaver(amrex::OutStream());
    IOFormatSaver iofmtsaver_estream(amrex::ErrorStream());

    if (os)
    {
        os->precision(4);
        *os << "\n\nTinyProfiler total time across processes [min...avg...max]: "
            << dt_min << " ... " << dt_avg << " ... " << dt_max << "\n";
    }

    // make sure the set of regions is the same on all processes.
    {
        Vector<std::string> localRegions, syncedRegions;
        bool alreadySynced;

        for (auto const& kv : lstatsmap) {
            localRegions.push_back(kv.first);
        }

        amrex::SyncStrings(localRegions, syncedRegions, alreadySynced);

        if (!alreadySynced) {

        amrex::SyncStrings(localRegions, syncedRegions, alreadySynced);

        if (!alreadySynced) {
            for (auto const& s : syncedRegions) {
                if (!lstatsmap.contains(s)) {
                    lstatsmap.insert(std::make_pair(s,RegionStats()));
                }
            }
        }
    }

    PrintStats(lstatsmap[mainregion], dt_max, os);
    for (auto& kv : lstatsmap) {
        if (kv.first != mainregion) {
            if (os) {
                *os << "\n\nBEGIN REGION " << kv.first << "\n";
            }
            PrintStats(kv.second, dt_max, os);
            if (os) {
                *os << "END REGION " << kv.first << "\n";
            }
        }
    }

    if (!bFlushing) {
        current_name.store(nullptr, std::memory_order_release);
        regionstack.clear();
        selective_regionstack.clear();
        regionstartstack.clear();
        ttstack.clear();
        statsmap.clear();
        selective_statsmap.clear();
        selective_reporting = false;
    }
}

void
TinyProfiler::MemoryFinalize (bool bFlushing)
{
    if (!memprof_enabled) { return; }

    // This function must be called BEFORE the profiled arenas are deleted

    if (!bFlushing) {                // If flushing, don't make this the last time!
        if (memprof_finalized) {
            return;
        } else {
            memprof_finalized = true;
        }
    }

    std::ofstream ofs;
    std::ostream* os = nullptr;
    if (ParallelDescriptor::IOProcessor()) {
        os = open_output_stream(get_output_file(), ofs);
    }

    PrintMemoryUsage(os, false);

    if (!bFlushing) {
        all_memstats.clear();
        all_memnames.clear();
    }
}

bool
TinyProfiler::RegisterArena (const std::string& memory_name,
                             std::map<std::string, MemStat>& memstats) noexcept
{
    if (!memprof_enabled) { return false; }

    all_memstats.push_back(&memstats);
    all_memnames.push_back(memory_name);
    return true;
}

void
TinyProfiler::DeregisterArena (std::map<std::string, MemStat>& memstats) noexcept
{
    if (!memprof_enabled) { return; }

    for (std::size_t i = 0; i < all_memstats.size();) {
        if (all_memstats[i] == &memstats) {
            all_memstats.erase(all_memstats.begin() + i); // NOLINT
            all_memnames.erase(all_memnames.begin() + i); // NOLINT
        } else {
            ++i;
        }
    }
}

