            localStrings.push_back((kv.first.gpu_sync ? '1' : '0') + kv.first.name);
        }

        amrex::SyncStrings(localStrings, syncedStrings, alreadySynced);

        if (!alreadySynced) {
            for (auto const& s : syncedStrings) {
                TimerKey const key{.name = s.substr(1), .gpu_sync = (s[0] == '1')};
