}

TinyProfileRegion::TinyProfileRegion (const char* a_regname, bool gpu_sync) noexcept
    : regname(a_regname),
      tprof(std::string("REG::")+std::string(a_regname), false, gpu_sync)
{
    TinyProfiler::StartRegion(a_regname, gpu_sync);
    tprof.start();
}

TinyProfileRegion::~TinyProfileRegion ()
{
    tprof.stop();
    TinyProfiler::StopRegion(regname);
}

void
TinyProfiler::PrintCallStack (std::ostream& os)
{
    if (!enabled) { return; }

    os << "===== TinyProfilers ======\n";
    for (auto const& x : ttstack) {
        os << *(std::get<2>(x)) << "\n";
    }
}

const char*
TinyProfiler::CurrentName () noexcept
{
    // signal-safe only if lock-free
    static_assert(decltype(current_name)::is_always_lock_free);
    return current_name.load(std::memory_order_acquire);
}

void
TinyProfiler::PrintMemoryUsage (std::ostream* os, bool only_local) noexcept
{
    if (!memprof_enabled) { return; }

    double t_final = amrex::second();
    double dt_max = t_final - t_memory_init;
    if (!only_local) {
        int ioproc = ParallelDescriptor::IOProcessorNumber();
        ParallelReduce::Max(dt_max, ioproc, ParallelDescriptor::Communicator());
    }

    for (std::size_t i = 0; i < all_memstats.size(); ++i) {
        PrintMemStats(*(all_memstats[i]), all_memnames[i], dt_max, t_final, os, only_local);
    }
}

std::string const&
TinyProfiler::get_output_file ()
{
    // Read the parameter once per Initialize/Finalize cycle. The guard is
    // re-armed in Initialize(), so a value updated between cycles is honored.
    // The guard also ensures the pre-existing file is removed at most once, so
    // the timer and memory reports (both opened in append mode) coexist.
    if (!output_file_read) {
        output_file_read = true;

        amrex::ParmParse pp("tiny_profiler");
        pp.query("output_file", output_file);

        if (ParallelDescriptor::IOProcessor()) {
            if (!is_stream_name(output_file) && FileSystem::Exists(output_file)) {
                FileSystem::Remove(output_file);
            }
        }
    }

    return output_file;
}

