bool
amrex::UtilCreateDirectory (const std::string& path,
                            mode_t mode, bool verbose)
{
    double sleep = 0.1;
    while (sleep < 2.0) {
        if (FileSystem::CreateDirectories(path, mode, verbose)) { return true; }
        amrex::Sleep(sleep);
        sleep *= 2;
    }
    return false;
}

