template <typename TV, typename TI>
struct ValLocPair
{
    TV value;
    TI index;

    constexpr TV&       first  ()       { return value; }
    constexpr TV const& first  () const { return value; }
    constexpr TI&       second ()       { return index; }
    constexpr TI const& second () const { return index; }

    static constexpr ValLocPair<TV,TI> max () {
        return ValLocPair<TV,TI>{std::numeric_limits<TV>::max(), TI()};
    }

    static constexpr ValLocPair<TV,TI> lowest () {
        return ValLocPair<TV,TI>{std::numeric_limits<TV>::lowest(), TI()};
    }

    friend constexpr bool operator< (ValLocPair<TV,TI> const& a, ValLocPair<TV,TI> const& b)
    {
        return a.value < b.value;
    }

    friend constexpr bool operator> (ValLocPair<TV,TI> const& a, ValLocPair<TV,TI> const& b)
    {
        return a.value > b.value;
    }
};

/**
* \brief This class is a thin wrapper around std::vector.  Unlike vector,
* Vector::operator[] provides bound checking when compiled with
* DEBUG=TRUE.
*/
template <class T, class Allocator=std::allocator<T> >
class Vector
    :
        public std::vector<T, Allocator>
{
public:

    using std::vector<T, Allocator>::vector;
    using typename std::vector<T, Allocator>::size_type;

    [[nodiscard]] T& operator[] (size_type i)
    {
        AMREX_ASSERT_WITH_MESSAGE(i < (this->std::vector<T, Allocator>::size()),
                                  "Out of bound error, index: " + std::to_string(i) + " size: " + std::to_string(size()));
        return this->std::vector<T, Allocator>::operator[](i);
    }

    [[nodiscard]] const T& operator[] (size_type i) const
    {
        AMREX_ASSERT_WITH_MESSAGE(i < (this->std::vector<T, Allocator>::size()),
                                  "Out of bound error, index: " + std::to_string(i) + " size: " + std::to_string(size()));
        return this->std::vector<T, Allocator>::operator[](i);
    }

    //! get access to the underlying data pointer
    [[nodiscard]] T* dataPtr () noexcept { return this->data(); }
    //! get access to the underlying data pointer
    [[nodiscard]] const T* dataPtr () const noexcept { return this->data(); }

    [[nodiscard]] Long size () const noexcept {return static_cast<Long>(std::vector<T, Allocator>::size());}

};

