// Min and max over the valid box of every local FAB and component.  Result
    // nc*L+n is for component n of local FAB L.  This is not inlined because
    // nvcc does not allow extended lambdas in constructors.
    Vector<GpuTuple<Real,Real>> device_minmax (const FabArray<FArrayBox>& mf)
    {
        auto const& ma = mf.const_arrays();
        return ParReducePerBoxComp(TypeList<ReduceOpMin,ReduceOpMax>{}, TypeList<Real,Real>{},
                                   mf, IntVect(0), mf.nComp(),
        [=] AMREX_GPU_DEVICE (int b, int i, int j, int k, int n) noexcept -> GpuTuple<Real,Real>
        {
            Real const x = ma[b](i,j,k,n);
            return {x, x};
        });
    }

void NItemsPerBin (int totalItems, Vector<int> &binCounts)
    {
        if(binCounts.empty()) {
            return;
        }
        int countForAll = static_cast<int>(totalItems / binCounts.size());
        int remainder = static_cast<int>(totalItems % binCounts.size());
        for(int & binCount : binCounts) {
            binCount = countForAll;
        }
        for(int i(0); i < remainder; ++i) {
            ++binCounts[i];
        }
    }

DistributionMapping vismf_make_dm (BoxArray& ba)
    {
        auto& ba_ref = ba.getSharedRef();

        std::shared_ptr<DMRef> dm_ref;
        int ielem = -1;
        for (auto it = s_layout_cache.begin(); it != s_layout_cache.end(); ) {
            auto cached_ba = it->first.lock();
            if (cached_ba) {
                if (cached_ba->m_abox == ba_ref->m_abox) {
                    ba_ref = std::move(cached_ba);
                    dm_ref = it->second.lock();
                    ielem = int(std::distance(s_layout_cache.begin(), it));
                    break;
                }
                ++it;
            } else { // expired
                it = s_layout_cache.erase(it);
            }
        }

        auto have_dm_in_cache = bool(dm_ref);
        ParallelDescriptor::ReduceBoolAnd(have_dm_in_cache);
        if (have_dm_in_cache) {
            return DistributionMapping{std::move(dm_ref)};
        } else {
            DistributionMapping dm{ba};
            if (ielem >= 0) {
                s_layout_cache[ielem].first = ba.getWeakRef();
                s_layout_cache[ielem].second = dm.getWeakRef();
            } else {
                s_layout_cache.emplace_back(ba.getWeakRef(), dm.getWeakRef());
            }
            return dm;
        }
    }

void
VisMF::Initialize ()
{
    if(initialized) {
      return;
    }
    //
    // Use the same defaults as in Amr.cpp.
    //
    VisMF::SetNOutFiles(nOutFiles);

    VisMF::SetMFFileInStreams(nMFFileInStreams);

    amrex::ExecOnFinalize(VisMF::Finalize);

    ParmParse pp("vismf");
    pp.query("verbose", "v",verbose);

    int headerVersion(currentVersion);
    pp.query("headerversion", headerVersion);
    if(headerVersion != currentVersion) {
      currentVersion = static_cast<VisMF::Header::Version> (headerVersion);
    }

    pp.query("groupsets", groupSets);
    pp.query("setbuf", setBuf);
    pp.query("usesingleread", useSingleRead);
    pp.query("usesinglewrite", useSingleWrite);
    pp.query("checkfilepositions", checkFilePositions);
    pp.query("usepersistentifstreams", usePersistentIFStreams);
    pp.query("usesynchronousreads", useSynchronousReads);
    pp.query("usedynamicsetselection", useDynamicSetSelection);
    pp.query("iobuffersize", ioBufferSize);
    pp.query("allowsparsewrites", allowSparseWrites);
    pp.query("noflushafterwrite", noFlushAfterWrite);
    pp.query("barrierafterlevel", barrierAfterLevel);

    initialized = true;
}

void
VisMF::Finalize ()
{
    initialized = false;
    s_layout_cache.clear();
}

void
VisMF::SetNOutFiles (int noutfiles, MPI_Comm comm)
{
    nOutFiles = std::max(1, std::min(ParallelDescriptor::NProcs(comm), noutfiles));
}

void
VisMF::SetMFFileInStreams (int nstreams, MPI_Comm comm)
{
    nMFFileInStreams = std::max(1, std::min(ParallelDescriptor::NProcs(comm), nstreams));
}

