FArrayBox*
VisMF::readFAB (int                  idx,
                const std::string   &mf_name,
                const VisMF::Header &hdr,
                int                  whichComp)
{
//    BL_PROFILE("VisMF::readFAB_idx");
    Box fab_box(hdr.m_ba[idx]);
    if(hdr.m_ngrow.max() > 0) {
        fab_box.grow(hdr.m_ngrow);
    }

    auto* fab = new FArrayBox(fab_box, whichComp == -1 ? hdr.m_ncomp : 1);

    std::string FullName(VisMF::DirName(mf_name));
    FullName += hdr.m_fod[idx].m_name;

    std::ifstream *infs = VisMF::OpenStream(FullName);
    infs->seekg(hdr.m_fod[idx].m_head, std::ios::beg);

    if(hdr.m_vers == Header::Version_v1) {
      if(whichComp == -1) {    // ---- read all components
        fab->readFrom(*infs);
      } else {
        fab->readFrom(*infs, whichComp);
      }
    } else {
      Real* fabdata = fab->dataPtr();
#ifdef AMREX_USE_GPU
      std::unique_ptr<FArrayBox> hostfab;
      if (fab->arena()->isManaged() || fab->arena()->isDevice()) {
          hostfab = std::make_unique<FArrayBox>(fab->box(), fab->nComp(), The_Pinned_Arena());
          fabdata = hostfab->dataPtr();
      }
#endif
      if(whichComp == -1) {    // ---- read all components
        if(hdr.m_writtenRD == FPC::NativeRealDescriptor()) {
          infs->read((char *) fabdata, static_cast<std::streamsize>(fab->nBytes()));
        } else {
          Long readDataItems(fab->box().numPts() * fab->nComp());
          RealDescriptor::convertToNativeFormat(fabdata, readDataItems,
                                                *infs, hdr.m_writtenRD);
        }

      } else {
        Long bytesPerComp(fab->box().numPts() * hdr.m_writtenRD.numBytes());
        infs->seekg(bytesPerComp * whichComp, std::ios::cur);
        if(hdr.m_writtenRD == FPC::NativeRealDescriptor()) {
          infs->read((char *) fabdata, bytesPerComp);
        } else {
          Long readDataItems(fab->box().numPts());  // ---- one component only

          infs->read((char *) fabdata, bytesPerComp);
        } else {
          Long readDataItems(fab->box().numPts());  // ---- one component only
          RealDescriptor::convertToNativeFormat(fabdata, readDataItems,
                                                *infs, hdr.m_writtenRD);
        }
      }
#ifdef AMREX_USE_GPU
      if (hostfab) {
          Gpu::htod_memcpy_async(fab->dataPtr(), hostfab->dataPtr(), fab->size()*sizeof(Real));
          Gpu::streamSynchronize();
      }
#endif
    }

    if (!(infs->good())) { amrex::Error("VisMF::readFAB failed"); }

    VisMF::CloseStream(FullName);

    return fab;
}

void
VisMF::readFAB (FabArray<FArrayBox> &mf,
                int                  idx,
                const std::string&   mf_name,
                const VisMF::Header& hdr)
{
//    BL_PROFILE("VisMF::readFAB_mf");
    FArrayBox &fab = mf[idx];

    std::string FullName(VisMF::DirName(mf_name));
    FullName += hdr.m_fod[idx].m_name;

    std::ifstream *infs = VisMF::OpenStream(FullName);
    infs->seekg(hdr.m_fod[idx].m_head, std::ios::beg);

    Box box = fab.box();
    if (hdr.m_ngrow != mf.nGrowVect()) {
        box.grow(hdr.m_ngrow - mf.nGrowVect());
    }
    std::unique_ptr<FArrayBox> hostfab;

    if(NoFabHeader(hdr)) {
      Real* fabdata = fab.dataPtr();
#ifdef AMREX_USE_GPU
      if (fab.arena()->isManaged() || fab.arena()->isDevice() || box != fab.box()) {
          hostfab = std::make_unique<FArrayBox>(box, fab.nComp(), The_Pinned_Arena());
          fabdata = hostfab->dataPtr();
      }
#else
      if (box != fab.box()) {
          hostfab = std::make_unique<FArrayBox>(box, fab.nComp());
          fabdata = hostfab->dataPtr();
      }
#endif

      if(hdr.m_writtenRD == FPC::NativeRealDescriptor()) {
          auto nbytes = hostfab ? hostfab->nBytes() : fab.nBytes();
          infs->read((char *) fabdata, static_cast<std::streamsize>(nbytes));
      } else {
          auto readDataItems = hostfab ? hostfab->size() : fab.size();
          RealDescriptor::convertToNativeFormat(fabdata, readDataItems,
                                                *infs, hdr.m_writtenRD);
      }
#ifdef AMREX_USE_GPU
      if (hostfab) {
          if (fab.arena()->isManaged() || fab.arena()->isDevice()) {
              fab.template copy<RunOn::Device>(*hostfab);
              Gpu::streamSynchronize();
          } else {
              fab.template copy<RunOn::Host>(*hostfab);
          }
      }
#else
      if (hostfab) {
          fab.copy(*hostfab);
      }
#endif
    } else {
        if (box == fab.box()) {
            fab.readFrom(*infs);
        } else {

        if (box == fab.box()) {
            fab.readFrom(*infs);
        } else {
#ifdef AMREX_USE_GPU
            if (fab.arena()->isManaged() || fab.arena()->isDevice()) {
                hostfab = std::make_unique<FArrayBox>(box, fab.nComp(), The_Pinned_Arena());
                hostfab->readFrom(*infs);
                fab.template copy<RunOn::Device>(*hostfab);
                Gpu::streamSynchronize();
            } else
#endif
            {
                hostfab = std::make_unique<FArrayBox>(box, fab.nComp());
                hostfab->readFrom(*infs);
                fab.template copy<RunOn::Host>(*hostfab);
            }
        }
    }

    if (!(infs->good())) { amrex::Error("VisMF::readFAB failed"); }

    VisMF::CloseStream(FullName);
}

