class VisMFBuffer
{
public:
    //! We try to do I/O with buffers of this size.
    static constexpr int  IO_Buffer_Size = 262144 * 8;
    //! The type of a char buffer required by [p]setbuf().
#ifdef BL_SETBUF_SIGNED_CHAR
    using Setbuf_Char_Type = signed char;
#else
    using Setbuf_Char_Type = char;
#endif
    //! A simple character buffer for setbuf() usage.
    using IO_Buffer = Vector<Setbuf_Char_Type>;

    static Long GetIOBufferSize () { return ioBufferSize; }
    static void SetIOBufferSize (Long iobuffersize) {
        BL_ASSERT(iobuffersize > 0);
        ioBufferSize = iobuffersize;
    }

    static void ClearBuffer (IO_Buffer& buf) {
        IO_Buffer().swap(buf);
    }

protected:

    static AMREX_EXPORT Long ioBufferSize;   //!< ---- the settable buffer size
}

void
IParser::define (std::string const& func_body)
{
    m_data = std::make_shared<Data>();

    if (!func_body.empty()) {
        m_data->m_expression = func_body;
        std::erase_if(m_data->m_expression, [](char c) { return c == '\n' || c == '\r'; });
        std::string f = m_data->m_expression + "\n";

        std::scoped_lock iparser_lock(iparser_mutex);
        YY_BUFFER_STATE buffer = amrex_iparser_scan_string(f.c_str());
        try {
            amrex_iparserparse();
            m_data->m_iparser = amrex_iparser_new();
        } catch (const std::runtime_error& e) {
            amrex_iparser_delete_buffer(buffer); // delete buffer allocated by bison
            amrex_iparser_delete_ptrs();         // delete ptrs allocated by amrex
            throw std::runtime_error(std::string(e.what()) + " in IParser expression \""
                                     + m_data->m_expression + "\"");
        }
        amrex_iparser_delete_buffer(buffer);
    }
}

/// \cond DOXYGEN_IGNORE
IParser::Data::~Data ()
{
    m_expression.clear();
    if (m_iparser) { amrex_iparser_delete(m_iparser); }
    clear_host_executor();
#ifdef AMREX_USE_GPU
    if (m_device_executor) { The_Arena()->free(m_device_executor); }
#endif
}

void
IParser::Data::clear_host_executor ()
{
    if (m_host_executor) {
        if (m_use_arena) {
            The_Pinned_Arena()->free(m_host_executor);
        } else {
            std::free(m_host_executor);
        }
        m_host_executor = nullptr;
        m_use_arena = true;
    }
}

void
IParser::setConstant (std::string const& name, long long c)
{
    if (m_data && m_data->m_iparser) {
        if (m_data->m_host_executor != nullptr) {
            throw std::runtime_error("amrex::IParser::setConstant: cannot modify constants after compile()");
        }
        iparser_setconst(m_data->m_iparser, name.c_str(), c);
    }
}

void
IParser::registerVariables (Vector<std::string> const& vars)
{
    if (m_data && m_data->m_host_executor != nullptr) {
        throw std::runtime_error("amrex::IParser::registerVariables: cannot modify variables after compile()");
    }

    if (m_data && m_data->m_iparser) {
        // The syntax tree may be shared with copies of this object, so forget
        // every previous registration, not just this object's.  A variable
        // dropped here then fails at compile time instead of reading past the
        // argument array.
        iparser_clearvar(m_data->m_iparser);
        m_data->m_nvars = static_cast<int>(vars.size());
        for (int i = 0; i < m_data->m_nvars; ++i) {
            iparser_regvar(m_data->m_iparser, vars[i].c_str(), i);
        }
    }
}

