iparser_newf2 (enum iparser_f2_t ftype, struct iparser_node* l, struct iparser_node* r)
{
    iparser_workspace.ptrs.push_back(std::malloc(sizeof(struct iparser_f2)));
    auto *tmp = (struct iparser_f2*) iparser_workspace.ptrs.back();
    tmp->type = IPARSER_F2;
    tmp->l = l;
    tmp->r = r;
    tmp->ftype = ftype;
    return (struct iparser_node*) tmp;
}

struct iparser_node*
iparser_newf3 (enum iparser_f3_t ftype, struct iparser_node* n1, struct iparser_node* n2,
               struct iparser_node* n3)
{
    iparser_workspace.ptrs.push_back(std::malloc(sizeof(struct iparser_f3)));
    auto *tmp = (struct iparser_f3*) iparser_workspace.ptrs.back();
    tmp->type = IPARSER_F3;
    tmp->n1 = n1;
    tmp->n2 = n2;
    tmp->n3 = n3;
    tmp->ftype = ftype;
    return (struct iparser_node*) tmp;
}

struct iparser_node*
iparser_newassign (struct iparser_symbol* sym, struct iparser_node* v)
{
    iparser_workspace.ptrs.push_back(std::malloc(sizeof(struct iparser_assign)));
    auto *r = (struct iparser_assign*) iparser_workspace.ptrs.back();
    r->type = IPARSER_ASSIGN;
    r->s = sym;
    r->v = v;
    return (struct iparser_node*) r;
}

struct iparser_node*
iparser_newlist (struct iparser_node* nl, struct iparser_node* nr)
{
    if (nr == nullptr) {
        return nl;
    } else {
        iparser_workspace.ptrs.push_back(std::malloc(sizeof(struct iparser_node)));
        auto *r = (struct iparser_node*) iparser_workspace.ptrs.back();
        r->type = IPARSER_LIST;
        r->l = nl;
        r->r = nr;
        return r;
    }
}

struct iparser_node* iparser_get_rightmost_operand (struct iparser_node* node)
{
    if (node && node->type == IPARSER_F2) {
        auto ftype = ((struct iparser_f2*)node)->ftype;
        if (ftype == IPARSER_CMP_CHAIN) {
            return iparser_get_rightmost_operand(node->r);
        } else if (ftype == IPARSER_LT || ftype == IPARSER_GT ||
                   ftype == IPARSER_LEQ || ftype == IPARSER_GEQ ||
                   ftype == IPARSER_EQ || ftype == IPARSER_NEQ) {
            return node->r;
        }
    }
    return nullptr;
}

bool iparser_is_comparison (struct iparser_node* node)
{
    if (node && node->type == IPARSER_F2) {
        auto ftype = ((struct iparser_f2*)node)->ftype;
        return (ftype == IPARSER_LT || ftype == IPARSER_GT ||
                ftype == IPARSER_LEQ || ftype == IPARSER_GEQ ||
                ftype == IPARSER_EQ || ftype == IPARSER_NEQ ||
                (ftype == IPARSER_CMP_CHAIN && iparser_is_comparison(node->r)));
    } else {
        return false;
    }
}

struct iparser_node* iparser_newcmpchain (struct iparser_node* nl, enum iparser_f2_t cmp,
                                          struct iparser_node* nr)
{
    /* If left side is an unparenthesized comparison, this extends the chain */
    if (amrex::iparser_is_comparison(nl) && !iparser_workspace.parens.contains(nl)) {
       return amrex::iparser_newf2(amrex::IPARSER_CMP_CHAIN, nl,
                                   amrex::iparser_newf2(cmp,
                                                        amrex::iparser_get_rightmost_operand(nl),
                                                        nr));
    } else {
        return amrex::iparser_newf2(cmp, nl, nr); // Initial comparison
    }
}

struct iparser_node* iparser_newparen (struct iparser_node* n)
{
    /* A parenthesized comparison must not become part of a chain. */
    if (amrex::iparser_is_comparison(n)) {
        iparser_workspace.parens.insert(n);
    }
    return n;
}

struct amrex_iparser*
amrex_iparser_new ()
{
    auto *my_iparser = (struct amrex_iparser*) std::malloc(sizeof(struct amrex_iparser));
    my_iparser->p_root = nullptr;

    try {
        my_iparser->sz_mempool = iparser_ast_size(iparser_workspace.root);
        my_iparser->p_root = std::malloc(my_iparser->sz_mempool);
        my_iparser->p_free = my_iparser->p_root;

        my_iparser->ast = iparser_ast_dup(my_iparser, iparser_workspace.root);

        amrex_iparser_delete_ptrs();

        if ((char*)my_iparser->p_root + my_iparser->sz_mempool != (char*)my_iparser->p_free) {
            amrex::Abort("amrex_iparser_new: error in memory size");
        }

        iparser_ast_optimize(my_iparser->ast);
    } catch (...) { // amrex::Abort throws with amrex.throw_exception=1
        amrex_iparser_delete(my_iparser);
        throw;
    }

    return my_iparser;
}

void
amrex_iparser_delete (struct amrex_iparser* iparser)
{
    std::free(iparser->p_root);
    std::free(iparser);
}

void
amrex_iparser_delete_ptrs ()
{
    for (auto* p : iparser_workspace.ptrs) {
        std::free(p);
    }
    iparser_workspace.ptrs.clear();
    iparser_workspace.parens.clear();
    iparser_workspace.root = nullptr;
}

std::size_t
iparser_aligned_size (std::size_t N)
{
    const unsigned int align_size = 16;
    std::size_t x = N + (align_size-1);
    x -= x & (align_size-1);
    return x;
}

void*
iparser_allocate (struct amrex_iparser* my_iparser, std::size_t N)
{
    void* r = my_iparser->p_free;
    my_iparser->p_free = (char*)r + iparser_aligned_size(N);
    return r;
}

std::size_t
iparser_ast_size (struct iparser_node* node)
{
    std::size_t result = 0;

    switch (node->type)
    {
    case IPARSER_NUMBER:
        result = iparser_aligned_size(sizeof(struct iparser_number));
        break;
    case IPARSER_SYMBOL:
        result = iparser_aligned_size(    sizeof(struct iparser_symbol))
            + iparser_aligned_size(std::strlen(((struct iparser_symbol*)node)->name)+1);
        break;
    case IPARSER_ADD:
    case IPARSER_SUB:
    case IPARSER_MUL:
    case IPARSER_DIV:
    case IPARSER_ADD_PP:
    case IPARSER_SUB_PP:
    case IPARSER_MUL_PP:
    case IPARSER_DIV_PP:
    case IPARSER_LIST:
        result = iparser_aligned_size(sizeof(struct iparser_node))
            + iparser_ast_size(node->l) + iparser_ast_size(node->r);
        break;
    case IPARSER_NEG:
        result = iparser_aligned_size(sizeof(struct iparser_node))
            + iparser_ast_size(node->l);
        break;
    case IPARSER_F1:
        result = iparser_aligned_size(sizeof(struct iparser_f1))
            +             iparser_ast_size(((struct iparser_f1*)node)->l);
        break;
    case IPARSER_F2:
        result = iparser_aligned_size(sizeof(struct iparser_f2))
            +             iparser_ast_size(((struct iparser_f2*)node)->l)
            +             iparser_ast_size(((struct iparser_f2*)node)->r);
        break;
    case IPARSER_F3:
        result = iparser_aligned_size(sizeof(struct iparser_f3))
            +             iparser_ast_size(((struct iparser_f3*)node)->n1)
            +             iparser_ast_size(((struct iparser_f3*)node)->n2)
            +             iparser_ast_size(((struct iparser_f3*)node)->n3);
        break;
    case IPARSER_ASSIGN:
        result += iparser_aligned_size(sizeof(struct iparser_assign))
            + iparser_ast_size((struct iparser_node*)(((struct iparser_assign*)node)->s))
            + iparser_ast_size(((struct iparser_assign*)node)->v);
        break;
    case IPARSER_ADD_VP:

            + iparser_ast_size(((struct iparser_assign*)node)->v);
        break;
    case IPARSER_ADD_VP:
    case IPARSER_SUB_VP:
    case IPARSER_MUL_VP:
    case IPARSER_DIV_VP:
    case IPARSER_DIV_PV:
        result = iparser_aligned_size(sizeof(struct iparser_node))
            + iparser_ast_size(node->r);
        break;
    case IPARSER_NEG_P:
        result = iparser_aligned_size(sizeof(struct iparser_node))
            + iparser_ast_size(node->l);
        break;
    default:
        amrex::Abort("iparser_ast_size: unknown node type " + std::to_string(node->type));
    }

    return result;
}

