}

/* This is our struct for storing AST in a more packed way.  The whole
 * tree is stored in a contiguous chunk of memory starting from void*
 * p_root with a size of sz_mempool.
 */
struct amrex_iparser {
    void* p_root;
    void* p_free;
    struct iparser_node* ast;
    std::size_t sz_mempool;
}

AMREX_GPU_HOST_DEVICE AMREX_FORCE_INLINE long long
iparser_call_f1 (enum iparser_f1_t /*type*/, long long a)
{
    /// There is only one type for now
    return std::abs(a);
}

AMREX_GPU_HOST_DEVICE AMREX_FORCE_INLINE long long
iparser_call_f2 (enum iparser_f2_t type, long long a, long long b)
{
    switch (type) {
    case IPARSER_FLRDIV:
    {
        long long r = a/b;
        if (r*b == a || (a < 0 && b < 0) || (a > 0 && b > 0)) {
            return r;
        } else {
            return r-1;
        }
    }
    case IPARSER_POW:
    {
        if (b < 0) {
            return 0;
        } else {
            long long r = 1;
            while (b != 0) {
                if (b & 1) {
                    r *= a;
                }
                b >>= 1;
                if (b > 0) { a *= a; } // to avoid overflow
            }
            return r;
        }
    }
    case IPARSER_GT:
        return (a > b) ? 1 : 0;
    case IPARSER_LT:
        return (a < b) ? 1 : 0;
    case IPARSER_GEQ:
        return (a >= b) ? 1 : 0;
    case IPARSER_LEQ:
        return (a <= b) ? 1 : 0;
    case IPARSER_EQ:
        return (a == b) ? 1 : 0;
    case IPARSER_NEQ:
        return (a != b) ? 1 : 0;
    case IPARSER_CMP_CHAIN:
    case IPARSER_AND:
        return ((a != 0) && (b != 0)) ? 1 : 0;
    case IPARSER_OR:
        return ((a != 0) || (b != 0)) ? 1 : 0;
    case IPARSER_MIN:
        return (a < b) ? a : b;
    case IPARSER_MAX:
        return (a > b) ? a : b;
    default:
        amrex::Abort("iparser_call_f2: Unknown function");
        return 0;
    }
}

AMREX_GPU_HOST_DEVICE AMREX_FORCE_INLINE long long
iparser_call_f3 (enum iparser_f3_t /*type*/, long long a, long long b, long long c)
{
    // There is only one type currently
    return (a != 0) ? b : c;
}

void
Parser::define (std::string const& func_body)
{
    m_data = std::make_shared<Data>();

    if (!func_body.empty()) {
        m_data->m_expression = func_body;
        // Strip // comments before joining lines, so a comment ends at its own line.
        for (auto pos = m_data->m_expression.find("//"); pos != std::string::npos;
             pos = m_data->m_expression.find("//", pos)) {
            auto eol = m_data->m_expression.find('\n', pos);
            m_data->m_expression.erase(pos, (eol == std::string::npos)
                                       ? std::string::npos : eol - pos);
        }
        std::erase_if(m_data->m_expression, [](char c) { return c == '\n' || c == '\r'; });
        std::string f = m_data->m_expression + "\n";

        std::scoped_lock parser_lock(parser_mutex);
        YY_BUFFER_STATE buffer = amrex_parser_scan_string(f.c_str());
        try {
            amrex_parserparse();
            m_data->m_parser = amrex_parser_new();
        } catch (const std::runtime_error& e) {
            amrex_parser_delete_buffer(buffer); // delete buffer allocated by bison
            amrex_parser_delete_ptrs();         // delete ptrs allocated by amrex
            throw std::runtime_error(std::string(e.what()) + " in Parser expression \""
                                     + m_data->m_expression + "\"");
        }
        amrex_parser_delete_buffer(buffer);
        m_ufs = parser_get_user_functions(m_data->m_parser);
    }
}

/// \cond DOXYGEN_IGNORE
Parser::Data::~Data ()
{
    m_expression.clear();
    if (m_parser) { amrex_parser_delete(m_parser); }
    clear_host_executor();
#ifdef AMREX_USE_GPU
    if (m_device_executor) { The_Arena()->free(m_device_executor); }
#endif
}

void
Parser::Data::clear_host_executor ()
{
    if (m_host_executor) {
        if (m_use_arena) {
            The_Pinned_Arena()->free(m_host_executor);
        } else {
            std::free(m_host_executor);
        }
        m_host_executor = nullptr;
        m_use_arena = true;
    }
}

