template <typename T>
AMREX_FORCE_INLINE
T parser_math_jn_host (int a, T b)
{
#if defined(_WIN32) && defined(__MINGW32__)
    // the implementation below has been tested on linux
    int const n = a < 0 ? -a : a;
    T const x = b < T(0) ? -b : b;
    T r = std::cyl_bessel_j(T(n), x);
    if ((n % 2 != 0) && ((a < 0) != (b < T(0)))) {
        r = -r;
    }
    return r;
#elif defined(_WIN32)
    return ::_jn(a,b);
#else
    return ::jn(a,b);
#endif
}

template <typename T>
AMREX_GPU_DEVICE AMREX_FORCE_INLINE
T parser_math_jn_device (int a, T b)
{
#if defined(AMREX_USE_SYCL) && !defined(AMREX_SYCL_EXT_INTEL_MATH)
    // Unreachable: Parser::compile rejects jn for this build.
    amrex::ignore_unused(a,b);
    return 0;
#elif defined(AMREX_USE_SYCL)
    return sycl::ext::intel::math::jn(a, b);
#else
    return ::jn(a,b);
#endif
}

template <typename T>
AMREX_FORCE_INLINE
T parser_math_yn_host (int a, T b)
{
#if defined(_WIN32) && defined(__MINGW32__)
    // the implementation below has been tested on linux
    int const n = a < 0 ? -a : a;
    if (b < T(0)) {
        return std::numeric_limits<T>::quiet_NaN();
    }
    T r = std::cyl_neumann(T(n), b);
    if ((n % 2 != 0) && (a < 0)) {
        r = -r;
    }
    return r;
#elif defined(_WIN32)
    return ::_yn(a,b);
#else
    return ::yn(a,b);
#endif
}

