AMREX_GPU_HOST_DEVICE AMREX_FORCE_INLINE double
parser_call_f1 (enum parser_f1_t type, double a)
{
    switch (type) {
    case PARSER_SQRT:        return std::sqrt(a);
    case PARSER_EXP:         return parser_math_exp<double>(a);
    case PARSER_LOG:         return parser_math_log<double>(a);
    case PARSER_LOG10:       return parser_math_log10<double>(a);
    case PARSER_SIN:         return parser_math_sin<double>(a);
    case PARSER_COS:         return parser_math_cos<double>(a);
    case PARSER_TAN:         return parser_math_tan<double>(a);
    case PARSER_ASIN:        return parser_math_asin<double>(a);
    case PARSER_ACOS:        return parser_math_acos<double>(a);
    case PARSER_ATAN:        return parser_math_atan<double>(a);
    case PARSER_SINH:        return parser_math_sinh<double>(a);
    case PARSER_COSH:        return parser_math_cosh<double>(a);
    case PARSER_TANH:        return parser_math_tanh<double>(a);
    case PARSER_ASINH:       return parser_math_asinh<double>(a);
    case PARSER_ACOSH:       return parser_math_acosh<double>(a);
    case PARSER_ATANH:       return parser_math_atanh<double>(a);
    case PARSER_ABS:         return std::abs(a);
    case PARSER_FLOOR:       return std::floor(a);
    case PARSER_CEIL:        return std::ceil(a);
    case PARSER_COMP_ELLINT_1: return parser_math_comp_ellint_1<double>(a);
    case PARSER_COMP_ELLINT_2: return parser_math_comp_ellint_2<double>(a);
    case PARSER_ERF:         return parser_math_erf<double>(a);
    default:
        amrex::Abort("parser_call_f1: Unknown function ");
        return 0.0;
    }
}

AMREX_GPU_HOST_DEVICE AMREX_FORCE_INLINE double
parser_call_f2 (enum parser_f2_t type, double a, double b)
{
    switch (type) {
    case PARSER_POW:
        return parser_math_pow<double>(a,b);
    case PARSER_ATAN2:
        return parser_math_atan2<double>(a,b);
    case PARSER_GT:
        return (a > b) ? 1.0 : 0.0;
    case PARSER_LT:
        return (a < b) ? 1.0 : 0.0;
    case PARSER_GEQ:
        return (a >= b) ? 1.0 : 0.0;
    case PARSER_LEQ:
        return (a <= b) ? 1.0 : 0.0;
    case PARSER_EQ:
        return (a == b) ? 1.0 : 0.0;
    case PARSER_NEQ:
        return (a != b) ? 1.0 : 0.0;
    case PARSER_CMP_CHAIN:
    case PARSER_AND:
        return ((a != 0.0) && (b != 0.0)) ? 1.0 : 0.0;
    case PARSER_OR:
        return ((a != 0.0) || (b != 0.0)) ? 1.0 : 0.0;
    case PARSER_HEAVISIDE:
        if (a < 0.0) {
            return 0.0;
        } else if (a > 0.0) {
            return 1.0;
        } else {
            return b;
        }
    case PARSER_JN:
        return parser_math_jn<double>(int(a),b);
    case PARSER_YN:
        return parser_math_yn<double>(int(a),b);
    case PARSER_MIN:
        return (a < b) ? a : b;
    case PARSER_MAX:
        return (a > b) ? a : b;
    case PARSER_FMOD:
        return std::fmod(a,b);
    default:
        amrex::Abort("parser_call_f2: Unknown function");
        return 0.0;
    }
}

AMREX_GPU_HOST_DEVICE AMREX_FORCE_INLINE double
parser_call_f3 (enum parser_f3_t /*type*/, double a, double b, double c)
{
    // There is only one type currently
    return (a != 0.0) ? b : c;
}

// Fills ghost cells outside the domain on BCType::ext_dir faces with the
// given Dirichlet values. AMReX fills the other BC types (foextrap,
// reflect_even, ...) itself; periodic ghost cells are filled by FillBoundary.
struct DirichletFill
{
    amrex::GpuArray<Real,AMREX_SPACEDIM> phi_lo;
    amrex::GpuArray<Real,AMREX_SPACEDIM> phi_hi;

    AMREX_GPU_DEVICE
    void operator() (amrex::IntVect const& iv, amrex::Array4<Real> const& dest,
                     int dcomp, int numcomp, amrex::GeometryData const& geom,
                     Real /*time*/, amrex::BCRec const* bcr, int bcomp,
                     int /*orig_comp*/) const
    {
        amrex::Box const& domain = geom.Domain();
        for (int n = 0; n < numcomp; ++n) {
            amrex::BCRec const& bc = bcr[bcomp+n];
            for (int d = 0; d < AMREX_SPACEDIM; ++d) {
                if (bc.lo(d) == amrex::BCType::ext_dir && iv[d] < domain.smallEnd(d)) {
                    dest(iv, dcomp+n) = phi_lo[d];
                } else if (bc.hi(d) == amrex::BCType::ext_dir && iv[d] > domain.bigEnd(d)) {
                    dest(iv, dcomp+n) = phi_hi[d];
                }
            }
        }
    }
}

// Laplacian of phi at cell iv. For ext_dir, the ghost cell holds the value
// on the boundary face, which is only dx/2 away from the cell center.
AMREX_GPU_DEVICE AMREX_FORCE_INLINE
Real laplacian (amrex::IntVect const& iv, amrex::Array4<Real const> const& phi,
                amrex::BCRec const& bc, amrex::Box const& domain,
                amrex::GpuArray<Real,AMREX_SPACEDIM> const& dxinv)
{
    Real lap = 0.0_rt;
    for (int d = 0; d < AMREX_SPACEDIM; ++d) {
        auto const e = amrex::IntVect::TheDimensionVector(d);
        Real const flo = (bc.lo(d) == amrex::BCType::ext_dir && iv[d] == domain.smallEnd(d))
            ? 2.0_rt : 1.0_rt;
        Real const fhi = (bc.hi(d) == amrex::BCType::ext_dir && iv[d] == domain.bigEnd(d))
            ? 2.0_rt : 1.0_rt;
        lap += (fhi * (phi(iv+e) - phi(iv)) - flo * (phi(iv) - phi(iv-e))) * dxinv[d] * dxinv[d];
    }
    return lap;
}

// Exact solution: linear steady state plus a decaying sine mode in x.
AMREX_GPU_HOST_DEVICE AMREX_FORCE_INLINE
Real exact_solution (Real x, Real t, Real phi_lo, Real phi_hi, Real diffusion_coef)
{
    Real const pi = amrex::Math::pi<Real>();
    return phi_lo + (phi_hi - phi_lo) * x
        + std::exp(-pi * pi * diffusion_coef * t) * std::sin(pi * x);
}

int main (int argc, char* argv[])
{
    amrex::Initialize(argc, argv);
    int status = 0;
    {
        int n_cell = 32;
        int max_grid_size = 16;
        Real diffusion_coef = 1.0_rt;
        Real cfl = 0.9_rt;
        Real stop_time = 0.05_rt;
        Real phi_lo = 1.0_rt; // Dirichlet value at x = 0
        Real phi_hi = 0.0_rt; // Dirichlet value at x = 1
        int plot_int = -1;
        {
            amrex::ParmParse pp;
            pp.query("n_cell", n_cell);
            pp.query("max_grid_size", max_grid_size);
            pp.query("diffusion_coef", diffusion_coef);
            pp.query("cfl", cfl);
            pp.query("stop_time", stop_time);
            pp.query("phi_lo", phi_lo);
            pp.query("phi_hi", phi_hi);
            pp.query("plot_int", plot_int);
        }

        // Boundary conditions, one BCRec per component:
        //   x: Dirichlet (ext_dir) on both sides
        //   y: zero gradient, as even reflection (lo) and extrapolation (hi)
        //   z: periodic (int_dir), which must match the Geometry
        amrex::Vector<amrex::BCRec> bcs(1);
        bcs[0].setLo(0, amrex::BCType::ext_dir);
        bcs[0].setHi(0, amrex::BCType::ext_dir);
#if (AMREX_SPACEDIM >= 2)
        bcs[0].setLo(1, amrex::BCType::reflect_even);
        bcs[0].setHi(1, amrex::BCType::foextrap);
#endif
#if (AMREX_SPACEDIM == 3)
        bcs[0].setLo(2, amrex::BCType::int_dir);
        bcs[0].setHi(2, amrex::BCType::int_dir);
#endif
        // z periodic, must match the BCRec
        amrex::Array<int,AMREX_SPACEDIM> is_periodic{AMREX_D_DECL(0, 0, 1)};

        amrex::Box domain(amrex::IntVect(0), amrex::IntVect(n_cell-1));
        amrex::BoxArray ba(domain);
        ba.maxSize(max_grid_size);
        amrex::DistributionMapping dm(ba);
        amrex::Geometry geom(domain,
                             amrex::RealBox({AMREX_D_DECL(0.0_rt, 0.0_rt, 0.0_rt)},
                                            {AMREX_D_DECL(1.0_rt, 1.0_rt, 1.0_rt)}),

        amrex::Geometry geom(domain,
                             amrex::RealBox({AMREX_D_DECL(0.0_rt, 0.0_rt, 0.0_rt)},
                                            {AMREX_D_DECL(1.0_rt, 1.0_rt, 1.0_rt)}),
                             amrex::CoordSys::cartesian, is_periodic);
        auto const prob_lo = geom.ProbLoArray();
        auto const dx = geom.CellSizeArray();
        auto const dxinv = geom.InvCellSizeArray();

        // Physical boundary filler: AMReX handles foextrap, reflect_even, etc.
        // and calls DirichletFill for every ghost cell outside the domain.
        DirichletFill dirichlet_fill{};
        dirichlet_fill.phi_lo[0] = phi_lo;
        dirichlet_fill.phi_hi[0] = phi_hi;
        amrex::PhysBCFunct<amrex::GpuBndryFuncFab<DirichletFill>> physbc
            (geom, bcs, amrex::GpuBndryFuncFab<DirichletFill>(dirichlet_fill));

        amrex::MultiFab phi_old(ba, dm, 1, 1);
        amrex::MultiFab phi_new(ba, dm, 1, 1);

        auto const& init = phi_new.arrays();
        amrex::ParallelFor(phi_new, [=] AMREX_GPU_DEVICE (int b, int i, int j, int k)
        {
            Real x = prob_lo[0] + (i + 0.5_rt) * dx[0];
            init[b](i,j,k) = exact_solution(x, 0.0_rt, phi_lo, phi_hi, diffusion_coef);
        });

        Real const dt = cfl * dx[0] * dx[0] / (2.0_rt * AMREX_SPACEDIM * diffusion_coef);
        Real time = 0.0_rt;
        int step = 0;
        amrex::BCRec const bc = bcs[0];

        while (time < stop_time * (1.0_rt - 1.e-6_rt))
        {
            std::swap(phi_old, phi_new);
            Real const dt_step = std::min(dt, stop_time - time);

            // Ghost cells: first those inside the (periodic) domain, then
            // those outside the domain from the physical BCs.
            phi_old.FillBoundary(geom.periodicity());
            physbc(phi_old, 0, 1, phi_old.nGrowVect(), time, 0);

            Real const fac = dt_step * diffusion_coef;
#ifdef AMREX_USE_OMP
#pragma omp parallel if (amrex::Gpu::notInLaunchRegion())

            Real const fac = dt_step * diffusion_coef;
#ifdef AMREX_USE_OMP
#pragma omp parallel if (amrex::Gpu::notInLaunchRegion())
#endif
            for (amrex::MFIter mfi(phi_new, amrex::TilingIfNotGPU()); mfi.isValid(); ++mfi)
            {
                amrex::Box const& bx = mfi.tilebox();
                auto const& po = phi_old.const_array(mfi);
                auto const& pn = phi_new.array(mfi);
                amrex::ParallelFor(bx, [=] AMREX_GPU_DEVICE (amrex::IntVect const& iv)
                {
                    pn(iv) = po(iv) + fac * laplacian(iv, po, bc, domain, dxinv);
                });
            }

            time += dt_step;
            ++step;
            if (plot_int > 0 && step % plot_int == 0) {
                amrex::WriteSingleLevelPlotfile(amrex::Concatenate("plt", step, 5), phi_new,
                                                {"phi"}, geom, time, step);
            }
        }

        amrex::MultiFab error(ba, dm, 1, 0);
        auto const& pa = phi_new.const_arrays();
        auto const& ea = error.arrays();
        amrex::ParallelFor(error, [=] AMREX_GPU_DEVICE (int b, int i, int j, int k)
        {
            Real x = prob_lo[0] + (i + 0.5_rt) * dx[0];
            ea[b](i,j,k) = pa[b](i,j,k) - exact_solution(x, time, phi_lo, phi_hi, diffusion_coef);
        });
        Real const err = error.norm0();
        amrex::Print() << "Finished " << step << " steps at time " << time
                       << ", max error = " << err << "\n";

        if (err > 1.e-3_rt) {
            amrex::Print() << "FAILED\n";
            status = 1;
        } else {
            amrex::Print() << "PASSED\n";
        }
    }
    amrex::Finalize();
    return status;
}

// Write a checkpoint directory, e.g., chk00010/ with
//   Header           step, time and BoxArray
//   Level_0/phi_*    MultiFab data written by VisMF
void WriteCheckpoint (std::string const& name, int step, Real time, amrex::MultiFab const& phi)
{
    // Create name/ and name/Level_0/ (on the I/O rank, then barrier).
    amrex::PreBuildDirectorHierarchy(name, "Level_", 1, true);

    if (amrex::ParallelDescriptor::IOProcessor()) {
        std::ofstream header(name + "/Header");
        if (!header.good()) { amrex::FileOpenFailed(name + "/Header"); }
        header.precision(17);
        header << "CheckpointRestart checkpoint\n" << step << "\n" << time << "\n";
        phi.boxArray().writeOn(header);
        header << "\n";
    }

    // Every rank writes the data it owns.
    amrex::VisMF::Write(phi, amrex::MultiFabFileFullPrefix(0, name, "Level_", "phi"));
}

// Read a checkpoint written by WriteCheckpoint and define phi from it.
void ReadCheckpoint (std::string const& name, int& step, Real& time, amrex::MultiFab& phi,
                     int nghost)
{
    // Rank 0 reads the header and broadcasts it.
    amrex::Vector<char> buffer;
    amrex::ParallelDescriptor::ReadAndBcastFile(name + "/Header", buffer);
    std::istringstream is(buffer.dataPtr());

    std::string title;
    std::getline(is, title);
    is >> step >> time;
    is.ignore(std::numeric_limits<std::streamsize>::max(), '\n');

    amrex::BoxArray ba;
    ba.readFrom(is);

    // A new DistributionMapping; the run may use a different number of ranks.
    amrex::DistributionMapping dm(ba);
    phi.define(ba, dm, 1, nghost);
    amrex::VisMF::Read(phi, amrex::MultiFabFileFullPrefix(0, name, "Level_", "phi"));
}

// Advance the periodic heat equation from step to nsteps.
void Advance (amrex::MultiFab& phi, amrex::Geometry const& geom, int& step, Real& time,
              int nsteps, Real dt, int chk_int, std::string const& chk_file)
{
    auto const dxinv = geom.InvCellSizeArray();
    amrex::MultiFab phi_new(phi.boxArray(), phi.DistributionMap(), 1, phi.nGrowVect());

    while (step < nsteps) {
        phi.FillBoundary(geom.periodicity());
        auto const& po = phi.const_arrays();
        auto const& pn = phi_new.arrays();
        amrex::ParallelFor(phi_new, [=] AMREX_GPU_DEVICE (int b, int i, int j, int k)
        {
            auto const& p = po[b];
            pn[b](i,j,k) = p(i,j,k) + dt * (
                  AMREX_D_TERM((p(i+1,j,k) - 2.0_rt*p(i,j,k) + p(i-1,j,k)) * dxinv[0]*dxinv[0],
                             + (p(i,j+1,k) - 2.0_rt*p(i,j,k) + p(i,j-1,k)) * dxinv[1]*dxinv[1],
                             + (p(i,j,k+1) - 2.0_rt*p(i,j,k) + p(i,j,k-1)) * dxinv[2]*dxinv[2]));
        });
        std::swap(phi, phi_new);
        ++step;
        time += dt;

        if (chk_int > 0 && step % chk_int == 0) {
            std::string const name = amrex::Concatenate(chk_file, step, 5);
            amrex::Print() << "Writing checkpoint " << name << " at step " << step << "\n";
            WriteCheckpoint(name, step, time, phi);
        }
    }
}

