    amrex::Print() << "Restarted run vs. uninterrupted run: max diff = "
                   << restart_diff << ", time diff = " << time2 - time << "\n";

    // Read the plotfile back, again into phi's layout.
    amrex::PlotFileData pf(plotfile);

            // Read the plotfile back, again into phi's layout.
