// Laplacian of order 2 or 4. The branch is resolved at compile time.
template <int order>
AMREX_GPU_DEVICE AMREX_FORCE_INLINE
Real laplacian (amrex::IntVect const& iv, amrex::Array4<Real const> const& p,
                amrex::GpuArray<Real,AMREX_SPACEDIM> const& dxinv)
{
    Real r = 0.0_rt;
    for (int d = 0; d < AMREX_SPACEDIM; ++d) {
        auto const e = amrex::IntVect::TheDimensionVector(d);
        if constexpr (order == 2) {
            r += (p(iv+e) - 2.0_rt*p(iv) + p(iv-e)) * dxinv[d] * dxinv[d];
        } else {
            r += (-p(iv+2*e) + 16.0_rt*p(iv+e) - 30.0_rt*p(iv) + 16.0_rt*p(iv-e) - p(iv-2*e))
                * (dxinv[d] * dxinv[d] / 12.0_rt);
        }
    }
    return r;
}

int main (int argc, char* argv[])
{
    amrex::Initialize(argc, argv);
    int status = 0;
    {
        int n_cell = 32;
        int max_grid_size = 16;
        int nrepeat = 5;
        auto order = Order::second;
        bool absorption = false;
        Real sigma = 0.5_rt;
        {
            amrex::ParmParse pp;
            pp.query("n_cell", n_cell);
            pp.query("max_grid_size", max_grid_size);
            pp.query("nrepeat", nrepeat);
            pp.query_enum_case_insensitive("order", order);
            pp.query("absorption", absorption);
            pp.query("sigma", sigma);
        }
        amrex::Print() << "order = " << amrex::getEnumNameString(order)
                       << ", absorption = " << absorption << "\n";

        amrex::Box domain(amrex::IntVect(0), amrex::IntVect(n_cell-1));
        amrex::BoxArray ba(domain);
        ba.maxSize(max_grid_size);
        amrex::DistributionMapping dm(ba);
        amrex::Geometry geom(domain,
                             amrex::RealBox({AMREX_D_DECL(0.0_rt, 0.0_rt, 0.0_rt)},
                                            {AMREX_D_DECL(1.0_rt, 1.0_rt, 1.0_rt)}),
                             amrex::CoordSys::cartesian, {AMREX_D_DECL(1, 1, 1)});
        auto const prob_lo = geom.ProbLoArray();
        auto const dx = geom.CellSizeArray();
        auto const dxinv = geom.InvCellSizeArray();

        amrex::MultiFab phi(ba, dm, 1, 2); // 2 ghost cells for the 4th-order stencil
        auto const& pa = phi.arrays();
        amrex::ParallelFor(phi, [=] AMREX_GPU_DEVICE (int b, int i, int j, int k)
        {
            amrex::IntVect const iv(AMREX_D_DECL(i,j,k));
            Real r = 1.0_rt;
            for (int d = 0; d < AMREX_SPACEDIM; ++d) {
                r *= std::sin(2.0_rt * amrex::Math::pi<Real>() * (prob_lo[d] + (iv[d]+0.5_rt)*dx[d]));
            }
            pa[b](i,j,k) = r;
        });
        phi.FillBoundary(geom.periodicity());

        amrex::MultiFab out_runtime(ba, dm, 1, 0);

        phi.FillBoundary(geom.periodicity());

        amrex::MultiFab out_runtime(ba, dm, 1, 0);
        amrex::MultiFab out_cto(ba, dm, 1, 0);

        // 1. Runtime branches: one kernel tests the options for every cell.
        for (int n = 0; n < nrepeat; ++n) {
            BL_PROFILE("runtime_branches");
#ifdef AMREX_USE_OMP
#pragma omp parallel if (amrex::Gpu::notInLaunchRegion())
#endif
            for (amrex::MFIter mfi(out_runtime, amrex::TilingIfNotGPU()); mfi.isValid(); ++mfi) {
                amrex::Box const& bx = mfi.tilebox();
                auto const& p = phi.const_array(mfi);
                auto const& out = out_runtime.array(mfi);
                amrex::ParallelFor(bx, [=] AMREX_GPU_DEVICE (int i, int j, int k)
                {
                    amrex::IntVect const iv(AMREX_D_DECL(i,j,k));
                    Real r = (order == Order::second) ? laplacian<2>(iv, p, dxinv)
                                                      : laplacian<4>(iv, p, dxinv);
                    if (absorption) { r -= sigma * p(iv); }
                    out(i,j,k) = r;
                });
            }
            amrex::Gpu::streamSynchronize();
        }

        // 2. Compile-time options: a kernel is compiled for each of the 2x2
        //    combinations of the listed values, and the one matching the
        //    runtime values is launched. The extra kernel arguments are
        //    std::integral_constant<int,...>, so the options are constants.
        for (int n = 0; n < nrepeat; ++n) {
            BL_PROFILE("compile_time_options");
#ifdef AMREX_USE_OMP
#pragma omp parallel if (amrex::Gpu::notInLaunchRegion())
#endif
            for (amrex::MFIter mfi(out_cto, amrex::TilingIfNotGPU()); mfi.isValid(); ++mfi) {
                amrex::Box const& bx = mfi.tilebox();
                auto const& p = phi.const_array(mfi);
                auto const& out = out_cto.array(mfi);
                amrex::ParallelFor(

                auto const& p = phi.const_array(mfi);
                auto const& out = out_cto.array(mfi);
                amrex::ParallelFor(
                    amrex::TypeList<amrex::CompileTimeOptions<int(Order::second), int(Order::fourth)>,
                                    amrex::CompileTimeOptions<0, 1>>{},
                    {int(order), int(absorption)},
                    bx, [=] AMREX_GPU_DEVICE (int i, int j, int k, auto order_ct, auto absorption_ct)
                {
                    amrex::IntVect const iv(AMREX_D_DECL(i,j,k));
                    constexpr int ord = (order_ct.value == int(Order::second)) ? 2 : 4;
                    Real r = laplacian<ord>(iv, p, dxinv);
                    // A plain `if` on a compile-time constant is optimized out
                    // too. (nvcc does not allow `if constexpr` blocks to be
                    // the first to use a captured variable, here sigma.)
                    if (absorption_ct.value) { r -= sigma * p(iv); }
                    out(i,j,k) = r;
                });
            }
            amrex::Gpu::streamSynchronize();
        }

        amrex::MultiFab::Subtract(out_cto, out_runtime, 0, 0, 1, 0);
        Real const diff = out_cto.norm0();
        Real const scale = out_runtime.norm0();
        amrex::Print() << "max |result| = " << scale << ", max diff between the two kernels = "
                       << diff << "\n";

        Real const tol = 10.0_rt * std::numeric_limits<Real>::epsilon() * scale;
        if (diff > tol) {
            amrex::Print() << "FAILED\n";
            status = 1;
        } else {
            amrex::Print() << "PASSED\n";
        }
    }
    amrex::Finalize();
    return status;
}

int main (int argc, char* argv[])
{
    // The application initializes MPI itself.
    MPI_Init(&argc, &argv);
    int world_rank = 0;
    int world_size = 0;
    MPI_Comm_rank(MPI_COMM_WORLD, &world_rank);
    MPI_Comm_size(MPI_COMM_WORLD, &world_size);

    // Split the ranks into two groups (even and odd world ranks). Each group
    // runs its own AMReX on its own communicator.
    int const group = world_rank % 2;
    MPI_Comm group_comm;
    MPI_Comm_split(MPI_COMM_WORLD, group, world_rank, &group_comm);
    int group_size = 0;
    MPI_Comm_size(group_comm, &group_size);

    // The application handles its own command line; here the first argument
    // is an inputs file, unless it looks like `name=value`.
    std::string inputs_file;
    if (argc > 1 && std::string(argv[1]).find('=') == std::string::npos) {
        inputs_file = argv[1];
    }

    // Called by amrex::Initialize after the (empty) ParmParse database is
    // created, but before AMReX reads its own parameters.
    auto add_parameters = [&] ()
    {
        amrex::ParmParse pp_amrex("amrex");
        pp_amrex.add("verbose", 0);

        if (!inputs_file.empty()) {
            amrex::ParmParse::addfile(inputs_file);
        }

        amrex::ParmParse pp;
        pp.add("group", group);
    };

    // build_parm_parse = false: do not parse argc/argv into ParmParse.
    // AMReX uses a duplicate of group_comm.
    amrex::Initialize(argc, argv, false, group_comm, add_parameters);
    int status = 0;
    {
        int n_cell = 16;
        int my_group = -1;
        amrex::ParmParse pp;
        pp.query("n_cell", n_cell);
        pp.get("group", my_group);

        int const nprocs = amrex::ParallelDescriptor::NProcs();
        amrex::Print() << "Group " << my_group << ": AMReX runs on " << nprocs
                       << " of " << world_size << " MPI ranks\n";

        // A MultiFab distributed over this group's ranks only
        amrex::Box domain(amrex::IntVect(0), amrex::IntVect(n_cell-1));

        // A MultiFab distributed over this group's ranks only
        amrex::Box domain(amrex::IntVect(0), amrex::IntVect(n_cell-1));
        amrex::BoxArray ba(domain);
        ba.maxSize(n_cell/2);
        amrex::MultiFab mf(ba, amrex::DistributionMapping(ba), 1, 0);
        mf.setVal(amrex::Real(my_group + 1));
        amrex::Real const sum = mf.sum(0); // reduced over this group's ranks
        amrex::Real const exact = amrex::Real(my_group + 1) * amrex::Real(domain.numPts());
        amrex::Print() << "Group " << my_group << ": sum = " << sum
                       << " (exact " << exact << ")\n";

        if (nprocs != group_size || my_group != group || sum != exact) {
            amrex::Print() << "Group " << my_group << ": FAILED\n";
            status = 1;
        } else {
            amrex::Print() << "Group " << my_group << ": PASSED\n";
        }
    }
    amrex::Finalize();

    // The application created these, so it frees them.
    MPI_Comm_free(&group_comm);
    MPI_Finalize();
    return status;
}

int main (int argc, char* argv[])
{
    amrex::Initialize(argc, argv);
    int status = 0;
    {
        int n = 100000;
        Real threshold = 0.75_rt;
        {
            amrex::ParmParse pp;
            pp.query("n", n);
            pp.query("threshold", threshold);
        }

        // Gpu::DeviceVector lives in device memory (from The_Arena()) on GPU
        // and in host memory on CPU. Its elements must not be accessed on the
        // host in GPU builds; use its data() pointer in kernels.
        amrex::Gpu::DeviceVector<Real> values(n);
        Real* pv = values.data();

        // Uniform random numbers in [0,1); each GPU thread gets its own engine.
        amrex::ParallelForRNG(n, [=] AMREX_GPU_DEVICE (int i, amrex::RandomEngine const& engine)
        {
            pv[i] = amrex::Random(engine);
        });

        // Stream compaction: keep the values above threshold, in order. The
        // exclusive prefix sum of the keep flags is each kept value's output
        // position, and the total is the number of kept values.
        amrex::Gpu::DeviceVector<Real> kept(n);
        Real* pk = kept.data();
        int const nkept = amrex::Scan::PrefixSum<int>(n,
            [=] AMREX_GPU_DEVICE (int i) -> int { return pv[i] > threshold; },
            [=] AMREX_GPU_DEVICE (int i, int const& pos) {
                if (pv[i] > threshold) { pk[pos] = pv[i]; }
            },
            amrex::Scan::Type::exclusive, amrex::Scan::retSum);
        kept.resize(nkept);
        amrex::Print() << "Kept " << nkept << " of " << n << " values above " << threshold << "\n";

        // Copy to the host. Pinned (page-locked) host memory, from
        // The_Pinned_Arena(), makes asynchronous copies fast. The copy is
        // asynchronous on GPU, so wait for the stream before using the data.
        amrex::Gpu::PinnedVector<Real> h_values(n);
        amrex::Gpu::PinnedVector<Real> h_kept(nkept);

// asynchronous on GPU, so wait for the stream before using the data.
amrex::Gpu::PinnedVector<Real> h_values(n);
amrex::Gpu::PinnedVector<Real> h_kept(nkept);
amrex::Gpu::copyAsync(amrex::Gpu::deviceToHost, values.begin(), values.end(), h_values.begin());
amrex::Gpu::copyAsync(amrex::Gpu::deviceToHost, kept.begin(), kept.end(), h_kept.begin());
amrex::Gpu::streamSynchronize();

// Reference compaction on the host
std::vector<Real> ref;
for (int i = 0; i < n; ++i) {
    if (h_values[i] > threshold) { ref.push_back(h_values[i]); }
}
bool compaction_ok = (ref.size() == std::size_t(nkept));
for (int i = 0; compaction_ok && i < nkept; ++i) {
    compaction_ok = (ref[i] == h_kept[i]);
}
amrex::Print() << "Compaction matches the host result: "
               << (compaction_ok ? "yes" : "no") << "\n";

// Scan::ExclusiveSum on raw device memory. The_Async_Arena() is for
// temporaries: on GPU, free() is ordered on the stream, so there is
// no need to synchronize before freeing.
amrex::Gpu::PinnedVector<int> h_counts(n);
for (int i = 0; i < n; ++i) { h_counts[i] = i % 4; }
amrex::Gpu::DeviceVector<int> counts(n);
amrex::Gpu::copyAsync(amrex::Gpu::hostToDevice, h_counts.begin(), h_counts.end(), counts.begin());

auto* offsets = static_cast<int*>(amrex::The_Async_Arena()->alloc(sizeof(int)*n));
int const total = amrex::Scan::ExclusiveSum(n, counts.data(), offsets);
amrex::Gpu::PinnedVector<int> h_offsets(n);
amrex::Gpu::copyAsync(amrex::Gpu::deviceToHost, offsets, offsets+n, h_offsets.begin());
amrex::Gpu::streamSynchronize();
amrex::The_Async_Arena()->free(offsets);

// Reference exclusive scan on the host
bool scan_ok = true;
int running = 0;
for (int i = 0; i < n; ++i) {

        bool scan_ok = true;
        int running = 0;
        for (int i = 0; i < n; ++i) {
            if (h_offsets[i] != running) { scan_ok = false; }
            running += h_counts[i];
        }
        scan_ok = scan_ok && (total == running);
        amrex::Print() << "ExclusiveSum total = " << total << ", matches the host result: "
                       << (scan_ok ? "yes" : "no") << "\n";

        if (compaction_ok && scan_ok) {
            amrex::Print() << "PASSED\n";
        } else {
            amrex::Print() << "FAILED\n";
            status = 1;
        }
    }
    amrex::Finalize();
    return status;
}

// prod_d sin(2 pi x_d) at the center of cell iv
AMREX_GPU_HOST_DEVICE AMREX_FORCE_INLINE
amrex::Real sine_mode (amrex::IntVect const& iv,
                       amrex::GpuArray<amrex::Real,AMREX_SPACEDIM> const& prob_lo,
                       amrex::GpuArray<amrex::Real,AMREX_SPACEDIM> const& dx)
{
    using namespace amrex::literals;
    amrex::Real r = 1.0_rt;
    for (int d = 0; d < AMREX_SPACEDIM; ++d) {
        amrex::Real x = prob_lo[d] + (iv[d] + 0.5_rt) * dx[d];
        r *= std::sin(2.0_rt * amrex::Math::pi<amrex::Real>() * x);
    }
    return r;
}

int main (int argc, char* argv[])
{
    amrex::Initialize(argc, argv);
