// Invert the n x n row-major matrix a (stored in the first n*n entries)
// with Gauss-Jordan elimination.
GpuArray<Real,N*N> invert (GpuArray<Real,N*N> a, int n)
{
    GpuArray<Real,N*N> inv{};
    for (int i = 0; i < n; ++i) { inv[i*n+i] = 1; }
    for (int col = 0; col < n; ++col) {
        int piv = col;
        for (int r = col+1; r < n; ++r) {
            if (std::abs(a[r*n+col]) > std::abs(a[piv*n+col])) { piv = r; }
        }
        AMREX_ALWAYS_ASSERT_WITH_MESSAGE(a[piv*n+col] != 0, "MultiCompNodeLap: singular C");
        for (int c = 0; c < n; ++c) {
            std::swap(a[col*n+c], a[piv*n+c]);
            std::swap(inv[col*n+c], inv[piv*n+c]);
        }
        Real const p = a[col*n+col];
        for (int c = 0; c < n; ++c) { a[col*n+c] /= p; inv[col*n+c] /= p; }
        for (int r = 0; r < n; ++r) {
            if (r == col) { continue; }
            Real const f = a[r*n+col];
            for (int c = 0; c < n; ++c) {
                a[r*n+c] -= f*a[col*n+c];
                inv[r*n+c] -= f*inv[col*n+c];
            }
        }
    }
    return inv;
}

MultiCompNodeLap::MultiCompNodeLap (Vector<Geometry> const& a_geom,
                                    Vector<BoxArray> const& a_grids,
                                    Vector<DistributionMapping> const& a_dmap,
                                    Vector<Real> const& a_coeff,
                                    LPInfo const& a_info)
{
    m_ncomp = int(std::sqrt(a_coeff.size()));
    AMREX_ALWAYS_ASSERT_WITH_MESSAGE(m_ncomp >= 1 && m_ncomp <= max_ncomp &&
                                     m_ncomp*m_ncomp == int(a_coeff.size()),
                                     "MultiCompNodeLap: coeff must have N*N entries, N <= 4");
    for (int i = 0; i < m_ncomp*m_ncomp; ++i) { m_coeff[i] = a_coeff[i]; }
    m_coeff_inv = invert(m_coeff, m_ncomp);

    // getNComp() must be valid before define, which allocates internal data.
    MLNodeLinOp::define(a_geom, a_grids, a_dmap, a_info);
}

void
MultiCompNodeLap::prepareForSolve ()
{
    MLNodeLinOp::prepareForSolve();
    buildMasks(); // e.g., m_dirichlet_mask, which is 1 on Dirichlet nodes
}

void
MultiCompNodeLap::Fapply (int amrlev, int mglev, MultiFab& out, MultiFab const& in) const
{
    int const ncomp = m_ncomp;
    auto const coeff = m_coeff;
    auto const dxinv = m_geom[amrlev][mglev].InvCellSizeArray();
    auto const& out_a = out.arrays();
    auto const& in_a = in.const_arrays();
    auto const& msk_a = m_dirichlet_mask[amrlev][mglev]->const_arrays();

    ParallelFor(out, [=] AMREX_GPU_DEVICE (int b, int i, int j, int k)
    {
        if (msk_a[b](i,j,k)) { // Dirichlet node
            for (int n = 0; n < ncomp; ++n) { out_a[b](i,j,k,n) = Real(0); }
            return;
        }
        auto const& x = in_a[b];
        GpuArray<Real,max_ncomp> lap{};
        for (int m = 0; m < ncomp; ++m) {
            lap[m] = AMREX_D_TERM(
                (x(i-1,j,k,m) - Real(2)*x(i,j,k,m) + x(i+1,j,k,m)) * dxinv[0]*dxinv[0],
              + (x(i,j-1,k,m) - Real(2)*x(i,j,k,m) + x(i,j+1,k,m)) * dxinv[1]*dxinv[1],
              + (x(i,j,k-1,m) - Real(2)*x(i,j,k,m) + x(i,j,k+1,m)) * dxinv[2]*dxinv[2]);
        }
        for (int n = 0; n < ncomp; ++n) {
            Real r = 0;
            for (int m = 0; m < ncomp; ++m) { r += coeff[n*ncomp+m] * lap[m]; }
            out_a[b](i,j,k,n) = r;
        }
    });
}

void
MultiCompNodeLap::Fsmooth (int amrlev, int mglev, MultiFab& sol, MultiFab const& rhs) const
{
    // Jacobi with the diagonal blocks D = C * diag(lap):
    //     sol += omega * D^{-1} (rhs - L(sol))
    MultiFab Lsol(sol.boxArray(), sol.DistributionMap(), m_ncomp, 0);
    Fapply(amrlev, mglev, Lsol, sol);

    int const ncomp = m_ncomp;
    auto const cinv = m_coeff_inv;
    auto const dxinv = m_geom[amrlev][mglev].InvCellSizeArray();
    Real diag_lap = 0;
    for (int d = 0; d < AMREX_SPACEDIM; ++d) { diag_lap -= Real(2)*dxinv[d]*dxinv[d]; }
    // Damping factor with good smoothing for the Laplacian: 2/3, 4/5, 6/7 in 1D-3D
    Real const omega = Real(2*AMREX_SPACEDIM)/Real(2*AMREX_SPACEDIM+1);

    auto const& sol_a = sol.arrays();
    auto const& rhs_a = rhs.const_arrays();
    auto const& Lsol_a = Lsol.const_arrays();
    auto const& msk_a = m_dirichlet_mask[amrlev][mglev]->const_arrays();

    ParallelFor(sol, [=] AMREX_GPU_DEVICE (int b, int i, int j, int k)
    {
        if (msk_a[b](i,j,k)) { return; }
        GpuArray<Real,max_ncomp> res{};
        for (int m = 0; m < ncomp; ++m) {
            res[m] = rhs_a[b](i,j,k,m) - Lsol_a[b](i,j,k,m);
        }
        for (int n = 0; n < ncomp; ++n) {
            Real z = 0;
            for (int m = 0; m < ncomp; ++m) { z += cinv[n*ncomp+m] * res[m]; }
            sol_a[b](i,j,k,n) += omega * z / diag_lap;
        }
    });

    // Make nodes shared by several boxes consistent.
    nodalSync(amrlev, mglev, sol);
}

void
MultiCompNodeLap::restriction (int amrlev, int cmglev, MultiFab& crse, MultiFab& fine) const
{
    // Fill the ghost nodes of the fine residual.
    applyBC(amrlev, cmglev-1, fine, BCMode::Homogeneous, StateMode::Solution);

    // crse and fine may have different layouts, e.g., after agglomeration.
    bool const need_parallel_copy = !amrex::isMFIterSafe(crse, fine);
    MultiFab cfine;
    if (need_parallel_copy) {
        cfine.define(amrex::coarsen(fine.boxArray(), 2), fine.DistributionMap(), m_ncomp, 0);
    }
    MultiFab& cmf = need_parallel_copy ? cfine : crse;

    // Fine nodes with valid data: the nodal domain, plus one layer of ghost
    // nodes in periodic directions.
    Box const fdomain = amrex::surroundingNodes(m_geom[amrlev][cmglev-1].growPeriodicDomain(1));

    int const ncomp = m_ncomp;
    auto const& c_a = cmf.arrays();
    auto const& f_a = fine.const_arrays();

    // Weights 1/4, 1/2, 1/4 in each direction
    constexpr int dj = (AMREX_SPACEDIM > 1) ? 1 : 0;
    constexpr int dk = (AMREX_SPACEDIM > 2) ? 1 : 0;
    ParallelFor(cmf, IntVect(0), ncomp, [=] AMREX_GPU_DEVICE (int b, int i, int j, int k, int n)
    {
        Real r = 0;
        for (int kk = -dk; kk <= dk; ++kk) {
        for (int jj = -dj; jj <= dj; ++jj) {
        for (int ii = -1; ii <= 1; ++ii) {
            if (fdomain.contains(2*i+ii, 2*j+jj, 2*k+kk)) {
                Real w = Real(2-std::abs(ii)) * Real(0.25);
                if (dj) { w *= Real(2-std::abs(jj)) * Real(0.25); }
                if (dk) { w *= Real(2-std::abs(kk)) * Real(0.25); }
                r += w * f_a[b](2*i+ii, 2*j+jj, 2*k+kk, n);
            }
        }}}
        c_a[b](i,j,k,n) = r;
    });

    if (need_parallel_copy) {
        crse.ParallelCopy(cfine);
    }
    setDirichletNodesToZero(amrlev, cmglev, crse);
}

void
MultiCompNodeLap::interpolation (int amrlev, int fmglev, MultiFab& fine, MultiFab const& crse) const
{
    bool const need_parallel_copy = !amrex::isMFIterSafe(crse, fine);
    MultiFab cfine;
    if (need_parallel_copy) {
        cfine.define(amrex::coarsen(fine.boxArray(), 2), fine.DistributionMap(), m_ncomp, 0);
        cfine.ParallelCopy(crse);
    }
    MultiFab const& cmf = need_parallel_copy ? cfine : crse;

    auto const& f_a = fine.arrays();
    auto const& c_a = cmf.const_arrays();
    auto const& msk_a = m_dirichlet_mask[amrlev][fmglev]->const_arrays();

    // A fine node coincides with a coarse node, or lies between 2, 4 or 8 of
    // them.  coarsen(i,2) and coarsen(i+1,2) are equal for even i and are the two
    // neighbors for odd i, so averaging over them handles all cases.
    ParallelFor(fine, IntVect(0), m_ncomp,
    [=] AMREX_GPU_DEVICE (int b, int i, int j, int k, int n)
    {
        if (msk_a[b](i,j,k)) { return; }
        int const ic[2] = {amrex::coarsen(i,2), amrex::coarsen(i+1,2)};
        int const jc[2] = {amrex::coarsen(j,2), amrex::coarsen(j+1,2)};
        int const kc[2] = {amrex::coarsen(k,2), amrex::coarsen(k+1,2)};
        Real r = 0;
        for (int kk = 0; kk < 2; ++kk) {
        for (int jj = 0; jj < 2; ++jj) {
        for (int ii = 0; ii < 2; ++ii) {
            r += c_a[b](ic[ii],jc[jj],kc[kk],n);
        }}}
        f_a[b](i,j,k,n) += Real(0.125) * r;
    });
}

/**
 * A user-defined nodal linear operator with N coupled components,
 *
 *     L(phi)_n = sum_m C_nm lap(phi_m),
 *
 * where C is a constant, invertible N x N matrix.  lap is the standard
 * (2D+1)-point Laplacian on the nodes.
 *
 * MLNodeLinOp provides the multigrid machinery, ghost node exchange,
 * Dirichlet node masks and dot products.  A derived class implements
 * the operator (Fapply), a smoother (Fsmooth), and the transfers between
 * multigrid levels (restriction and interpolation).  This class only
 * supports single-level solves.  Non-periodic boundaries must be Dirichlet.
 */
class MultiCompNodeLap
    : public amrex::MLNodeLinOp
{
public:
    static constexpr int max_ncomp = 4;

    /**
     * \param a_grids cell-centered BoxArrays; the unknowns live on their nodes.
     * \param a_coeff the matrix C in row-major order, with N*N entries.
     */
    MultiCompNodeLap (amrex::Vector<amrex::Geometry> const& a_geom,
                      amrex::Vector<amrex::BoxArray> const& a_grids,
                      amrex::Vector<amrex::DistributionMapping> const& a_dmap,
                      amrex::Vector<amrex::Real> const& a_coeff,
                      amrex::LPInfo const& a_info = amrex::LPInfo());

    [[nodiscard]] std::string name () const override { return "MultiCompNodeLap"; }

    [[nodiscard]] int getNComp () const override { return m_ncomp; }

    // out = L(in).  The ghost nodes of in have been filled.
    void Fapply (int amrlev, int mglev, amrex::MultiFab& out,
                 amrex::MultiFab const& in) const override;

    // One sweep of block Jacobi on L(sol) = rhs.
    void Fsmooth (int amrlev, int mglev, amrex::MultiFab& sol,
                  amrex::MultiFab const& rhs) const override;

    // Full-weighting restriction of the residual to MG level cmglev.
    void restriction (int amrlev, int cmglev, amrex::MultiFab& crse,
                      amrex::MultiFab& fine) const override;

    void restriction (int amrlev, int cmglev, amrex::MultiFab& crse,
                      amrex::MultiFab& fine) const override;

    // fine += linear interpolation of the coarse correction.
    void interpolation (int amrlev, int fmglev, amrex::MultiFab& fine,
                        amrex::MultiFab const& crse) const override;

    void prepareForSolve () override;

private:
    int m_ncomp = 0;
    amrex::GpuArray<amrex::Real,max_ncomp*max_ncomp> m_coeff{};     // C
    amrex::GpuArray<amrex::Real,max_ncomp*max_ncomp> m_coeff_inv{}; // C^{-1}
}

void ConvDiffOp::apply (MultiFab& Ax, MultiFab const& x) const
{
    // GMRES allows us to fill the ghost cells of x.
    const_cast<MultiFab&>(x).FillBoundary(m_geom.periodicity());

    auto const dxinv = m_geom.InvCellSizeArray();
    auto const vel = m_vel;
    Box const domain = m_geom.Domain();
    auto const& x_a = x.const_arrays();
    auto const& ax_a = Ax.arrays();
    ParallelFor(Ax, [=] AMREX_GPU_DEVICE (int b, int i, int j, int k)
    {
        auto const& xa = x_a[b];
        IntVect const iv(AMREX_D_DECL(i,j,k));
        Real const xc = xa(iv);
        Real lap = 0, adv = 0;
        for (int d = 0; d < AMREX_SPACEDIM; ++d) {
            IntVect const ivm = iv - IntVect::TheDimensionVector(d);
            IntVect const ivp = iv + IntVect::TheDimensionVector(d);
            // Dirichlet u = 0 on the domain face: the ghost value is -xc.
            Real const xm = (ivm[d] < domain.smallEnd(d)) ? -xc : xa(ivm);
            Real const xp = (ivp[d] > domain.bigEnd(d))   ? -xc : xa(ivp);
            lap += (xm - Real(2)*xc + xp) * dxinv[d]*dxinv[d];
            adv += vel[d] * (xp - xm) * Real(0.5)*dxinv[d];
        }
        ax_a[b](i,j,k) = lap - adv;
    });
}

void ConvDiffOp::precond (MultiFab& lhs, MultiFab const& rhs) const
{
    if (m_use_precond) {
        // Approximately solve lap(lhs) = rhs with one V-cycle, starting
        // from zero.  A fixed number of cycles keeps the preconditioner a
        // linear operator, as GMRES requires.
        lhs.setVal(0);
        m_mlmg->setPrecondIter(1);
        m_mlmg->precond({&lhs}, {&rhs}, Real(0), Real(0));
    } else {
        MultiFab::Copy(lhs, rhs, 0, 0, 1, 0);
    }
}

/**
 * Matrix-free convection-diffusion operator A(u) = lap(u) - c.grad(u)
 * with homogeneous Dirichlet boundaries, discretized with central
 * differences on cell centers.  A is not symmetric, so we solve with GMRES.
 *
 * The class provides the vector operations and the matrix-vector product
 * that amrex::GMRES<MultiFab,ConvDiffOp> needs.  The preconditioner is one
 * MLMG V-cycle of the Laplacian alone.
 */
class ConvDiffOp
{
public:
    using RT = amrex::Real; // required by amrex::GMRES

    ConvDiffOp (amrex::Geometry const& geom, amrex::BoxArray const& ba,
                amrex::DistributionMapping const& dm,
                amrex::GpuArray<amrex::Real,AMREX_SPACEDIM> const& velocity,
                amrex::MLMG& precond_mlmg)
        : m_geom(geom), m_ba(ba), m_dm(dm), m_vel(velocity), m_mlmg(&precond_mlmg)
    {}

    void usePrecond (bool flag) { m_use_precond = flag; }

    // Vectors for the right-hand side b and the unknowns x of A x = b.  x
    // has a ghost cell, so that apply can fill it.
    [[nodiscard]] amrex::MultiFab makeVecRHS () const
    {
        return amrex::MultiFab(m_ba, m_dm, 1, 0);
    }

    [[nodiscard]] amrex::MultiFab makeVecLHS () const
    {
        amrex::MultiFab mf(m_ba, m_dm, 1, 1);
        mf.setBndry(0);
        return mf;
    }

    // Linear algebra
    [[nodiscard]] RT norm2 (amrex::MultiFab const& mf) const { return mf.norm2(); }

    [[nodiscard]] RT dotProduct (amrex::MultiFab const& a, amrex::MultiFab const& b) const
    {
        return amrex::MultiFab::Dot(a, 0, b, 0, 1, 0);
    }

    static void scale (amrex::MultiFab& mf, RT fac) { mf.mult(fac); }

    static void setToZero (amrex::MultiFab& mf) { mf.setVal(0); }

    static void assign (amrex::MultiFab& lhs, amrex::MultiFab const& rhs)
    {
        amrex::MultiFab::Copy(lhs, rhs, 0, 0, 1, 0);
    }

    // lhs += a*rhs
    static void increment (amrex::MultiFab& lhs, amrex::MultiFab const& rhs, RT a)
    {

    // lhs += a*rhs
    static void increment (amrex::MultiFab& lhs, amrex::MultiFab const& rhs, RT a)
    {
        amrex::MultiFab::Saxpy(lhs, a, rhs, 0, 0, 1, 0);
    }

    // lhs = a*rhs_a + b*rhs_b
    static void linComb (amrex::MultiFab& lhs, RT a, amrex::MultiFab const& rhs_a,
                         RT b, amrex::MultiFab const& rhs_b)
    {
        amrex::MultiFab::LinComb(lhs, a, rhs_a, 0, b, rhs_b, 0, 0, 1, 0);
    }

    // Ax = A(x).  x was made by makeVecLHS.
    void apply (amrex::MultiFab& Ax, amrex::MultiFab const& x) const;

    // Right preconditioning: lhs = P^{-1}(rhs), where P approximates A.
    void precond (amrex::MultiFab& lhs, amrex::MultiFab const& rhs) const;

private:
    amrex::Geometry m_geom;
    amrex::BoxArray m_ba;
    amrex::DistributionMapping m_dm;
    amrex::GpuArray<amrex::Real,AMREX_SPACEDIM> m_vel;
    amrex::MLMG* m_mlmg;
    bool m_use_precond = true;
}

// Exact solution u = prod_d sin(pi x_d), zero on the boundary of the unit
// square/cube.
AMREX_GPU_HOST_DEVICE AMREX_FORCE_INLINE
Real exact_u (RealVect_t const& x)
{
    Real r = 1;
    for (int d = 0; d < AMREX_SPACEDIM; ++d) { r *= std::sin(Math::pi<Real>()*x[d]); }
    return r;
}

AMREX_GPU_HOST_DEVICE AMREX_FORCE_INLINE
Real exact_du (RealVect_t const& x, int dir)
{
    constexpr Real pi = Math::pi<Real>();
    Real r = 1;
    for (int d = 0; d < AMREX_SPACEDIM; ++d) {
        r *= (d == dir) ? pi*std::cos(pi*x[d]) : std::sin(pi*x[d]);
    }
    return r;
}

// Fill exact with u and rhs with lap(u) - c.grad(u).
void init_problem (MultiFab& exact, MultiFab& rhs, Geometry const& geom,
                   RealVect_t const& vel)
{
    auto const problo = geom.ProbLoArray();
    auto const dx = geom.CellSizeArray();
    auto const& exact_a = exact.arrays();
    auto const& rhs_a = rhs.arrays();
    ParallelFor(rhs, [=] AMREX_GPU_DEVICE (int b, int i, int j, int k)
    {
        IntVect const iv(AMREX_D_DECL(i,j,k));
        RealVect_t x;
        for (int d = 0; d < AMREX_SPACEDIM; ++d) {
            x[d] = problo[d] + (Real(iv[d])+Real(0.5))*dx[d];
        }
        Real const u = exact_u(x);
        Real r = -Real(AMREX_SPACEDIM)*Math::pi<Real>()*Math::pi<Real>()*u;
        for (int d = 0; d < AMREX_SPACEDIM; ++d) { r -= vel[d]*exact_du(x,d); }
        exact_a[b](i,j,k) = u;
        rhs_a[b](i,j,k) = r;
    });
}

