// Advance one level by dt_lev with Heun's method (second-order SSP
// Runge-Kutta), and record the fluxes in the flux registers.
void
AmrCoreAdv::AdvanceLevel (int lev, Real time, Real dt_lev)
{
    std::swap(phi_old[lev], phi_new[lev]);
    t_old[lev] = time;
    t_new[lev] = time + dt_lev;

    // Two ghost cells for the limited slopes of the upwind cells.
    MultiFab Sborder(grids[lev], dmap[lev], 1, 2);
    Array<MultiFab,AMREX_SPACEDIM> flux;
    for (int idim = 0; idim < AMREX_SPACEDIM; ++idim) {
        flux[idim].define(amrex::convert(grids[lev], IntVect::TheDimensionVector(idim)),
                          dmap[lev], 1, 0);
    }

    auto const& pold = phi_old[lev].const_arrays();
    auto const& pnew = phi_new[lev].arrays();
    AMREX_D_TERM(auto const& fx = flux[0].const_arrays();,
                 auto const& fy = flux[1].const_arrays();,
                 auto const& fz = flux[2].const_arrays();)
    GpuArray<Real,AMREX_SPACEDIM> dtdx;
    for (int idim = 0; idim < AMREX_SPACEDIM; ++idim) {
        dtdx[idim] = dt_lev * geom[lev].InvCellSize(idim);
    }

    // Stage 0: phi_new = phi_old - dt div F(phi_old)
    // Stage 1: phi_new = phi_old - dt div (F(phi_old) + F(phi_new))/2, where
    //          FillPatch at t_new uses the stage 0 result stored in phi_new.
    for (int stage = 0; stage < 2; ++stage) {
        Real const stage_time = time + stage*dt_lev;
        FillPatch(lev, stage_time, Sborder);
        ComputeFluxes(lev, Sborder, stage_time, flux, stage == 1);

        ParallelFor(phi_new[lev], [=] AMREX_GPU_DEVICE (int b, int i, int j, int k)
        {
            pnew[b](i,j,k) = pold[b](i,j,k)
                - (AMREX_D_TERM(  dtdx[0] * (fx[b](i+1,j,k) - fx[b](i,j,k)),
                                + dtdx[1] * (fy[b](i,j+1,k) - fy[b](i,j,k)),
                                + dtdx[2] * (fz[b](i,j,k+1) - fz[b](i,j,k))));
        });
    }

    if (do_reflux) {
        // The registers hold flux * area * dt. The coarse level of an

    if (do_reflux) {
        // The registers hold flux * area * dt. The coarse level of an
        // interface subtracts its flux, and the fine level adds its fluxes.
        for (int idim = 0; idim < AMREX_SPACEDIM; ++idim) {
            Real area = 1.0_rt;
            for (int d = 0; d < AMREX_SPACEDIM; ++d) {
                if (d != idim) { area *= geom[lev].CellSize(d); }
            }
            if (lev < finest_level) {
                flux_reg[lev+1]->CrseInit(flux[idim], idim, 0, 0, 1, -dt_lev*area);
            }
            if (lev > 0) {
                flux_reg[lev]->FineAdd(flux[idim], idim, 0, 0, 1, dt_lev*area);
            }
        }
    }

    // Sborder and flux are freed on return while kernels may still be running.
    Gpu::streamSynchronize();
}

// Upwind fluxes u*phi on all faces of level lev. With average = true, the
// result is averaged with the fluxes already in flux.
void
AmrCoreAdv::ComputeFluxes (int lev, MultiFab const& state, Real time,
                           Array<MultiFab,AMREX_SPACEDIM>& flux, bool average) const
{
    auto const& q = state.const_arrays();
    auto const problo = Geom(lev).ProbLoArray();
    auto const dx = Geom(lev).CellSizeArray();
    for (int idim = 0; idim < AMREX_SPACEDIM; ++idim) {
        auto const& f = flux[idim].arrays();
        Dim3 const e = IntVect::TheDimensionVector(idim).dim3();
        ParallelFor(flux[idim], [=] AMREX_GPU_DEVICE (int b, int i, int j, int k)
        {
            Real const u = adv::face_velocity(idim, i, j, problo, dx, time);
            Real const fnew = adv::upwind_flux(q[b], i, j, k, e, u);
            f[b](i,j,k) = average ? 0.5_rt*(f[b](i,j,k) + fnew) : fnew;
        });
    }
}

// Stable time step on level lev: cfl / max over cells of sum_d |u_d|/dx_d.
Real
AmrCoreAdv::EstTimeStep (int lev, Real time) const
{
    auto const problo = Geom(lev).ProbLoArray();
    auto const dx = Geom(lev).CellSizeArray();
    auto const dxinv = Geom(lev).InvCellSizeArray();
    Real rate = ParReduce(TypeList<ReduceOpMax>{}, TypeList<Real>{}, phi_new[lev], IntVect(0),
        [=] AMREX_GPU_DEVICE (int, int i, int j, int) -> GpuTuple<Real>
        {
            Real r = 0.0_rt;
            for (int idim = 0; idim < AMREX_SPACEDIM; ++idim) {
                IntVect const e = IntVect::TheDimensionVector(idim);
                Real const ulo = adv::face_velocity(idim, i,      j,      problo, dx, time);
                Real const uhi = adv::face_velocity(idim, i+e[0], j+e[1], problo, dx, time);
                r += amrex::max(std::abs(ulo), std::abs(uhi)) * dxinv[idim];
            }
            return {r};
        });
    ParallelDescriptor::ReduceRealMax(rate);
    return (rate > 0.0_rt) ? cfl / rate : stop_time;
}

AmrCoreAdv::AmrCoreAdv ()
{
    // The AmrCore constructor has read amr.* and geometry.* and defined the
    // Geometry of every level. No grids exist yet.
    ReadParameters();

    int const nlevs_max = max_level + 1;

    istep.resize(nlevs_max, 0);
    last_regrid_step.resize(nlevs_max, 0);
    nsubsteps.resize(nlevs_max, 1);
    if (do_subcycle) {
        for (int lev = 1; lev <= max_level; ++lev) {
            nsubsteps[lev] = MaxRefRatio(lev-1);
        }
    }

    t_new.resize(nlevs_max, 0.0_rt);
    t_old.resize(nlevs_max, 0.0_rt);
    dt.resize(nlevs_max, 0.0_rt);

    phi_new.resize(nlevs_max);
    phi_old.resize(nlevs_max);
    flux_reg.resize(nlevs_max);

    // Periodic directions use int_dir. Otherwise, walls with zero gradient.
    bcs.resize(1);
    for (int idim = 0; idim < AMREX_SPACEDIM; ++idim) {
        int const bc = Geom(0).isPeriodic(idim) ? BCType::int_dir : BCType::foextrap;
        bcs[0].setLo(idim, bc);
        bcs[0].setHi(idim, bc);
    }
}

void
AmrCoreAdv::ReadParameters ()
{
    {
        ParmParse pp;
        pp.query("max_step", max_step);
        pp.query("stop_time", stop_time);
    }
    {
        ParmParse pp("amr");
        pp.query("regrid_int", regrid_int);
        pp.query("plot_file", plot_file);
        pp.query("plot_int", plot_int);
        pp.query("chk_file", chk_file);
        pp.query("chk_int", chk_int);
        pp.query("restart", restart_chkfile);
    }
    {
        ParmParse pp("adv");
        pp.query("cfl", cfl);
        pp.query("do_reflux", do_reflux);
        pp.query("do_subcycle", do_subcycle);

        // Refine where phi > phierr[lev]. The last value is used for finer levels.
        Vector<Real> phierr{0.01_rt, 0.1_rt, 0.5_rt};
        Vector<Real> phierr_in;
        if (pp.queryarr("phierr", phierr_in)) { phierr = phierr_in; } // replace all
        error_tags.emplace_back(phierr, AMRErrorTag::GREATER, "phi");
    }
}

void
AmrCoreAdv::InitData ()
{
    if (restart_chkfile.empty()) {
        // Calls ErrorEst and MakeNewLevelFromScratch level by level.
        InitFromScratch(0.0_rt);
        for (int lev = finest_level-1; lev >= 0; --lev) {
            AverageDownTo(lev);
        }
        if (chk_int > 0) {
            WriteCheckpointFile();
        }
    } else {
        ReadCheckpointFile();
    }

    if (plot_int > 0) {
        WritePlotFile();
    }
}

void
AmrCoreAdv::Evolve ()
{
    Real cur_time = t_new[0];
    int last_plot_file_step = istep[0];

    for (int step = istep[0]; step < max_step && cur_time < stop_time; ++step)
    {
        if (do_subcycle) {
            ComputeDt();
            TimeStepWithSubcycling(0, cur_time);
        } else {
            TimeStepNoSubcycling(cur_time);
        }

        cur_time += dt[0];
        for (int lev = 0; lev <= finest_level; ++lev) {
            t_new[lev] = cur_time;  // remove roundoff differences between levels
        }

        amrex::Print() << "Coarse step " << step+1 << " time = " << cur_time
                       << " dt = " << dt[0] << " levels = " << finest_level+1
                       << " mass = " << TotalMass() << "\n";

        if (plot_int > 0 && (step+1) % plot_int == 0) {
            last_plot_file_step = step+1;
            WritePlotFile();
        }

        if (chk_int > 0 && (step+1) % chk_int == 0) {
            WriteCheckpointFile();
        }

        if (cur_time >= stop_time - 1.e-6_rt*dt[0]) { break; }
    }

    if (plot_int > 0 && istep[0] > last_plot_file_step) {
        WritePlotFile();
    }
}

Real
AmrCoreAdv::TotalMass () const
{
    // Level 0 covers the domain and holds the average of finer levels.
    Real const vol = AMREX_D_TERM(Geom(0).CellSize(0), *Geom(0).CellSize(1), *Geom(0).CellSize(2));
    return phi_new[0].sum(0) * vol;
}

void
AmrCoreAdv::DefineLevel (int lev, const BoxArray& ba, const DistributionMapping& dm)
{
    phi_new[lev].define(ba, dm, 1, 0);
    phi_old[lev].define(ba, dm, 1, 0);
    if (lev > 0 && do_reflux) {
        flux_reg[lev] = std::make_unique<FluxRegister>(ba, dm, refRatio(lev-1), lev, 1);
    }
}

void
AmrCoreAdv::MakeNewLevelFromScratch (int lev, Real time, const BoxArray& ba,
                                     const DistributionMapping& dm)
{
    DefineLevel(lev, ba, dm);
    t_new[lev] = t_old[lev] = time;

    auto const& phi = phi_new[lev].arrays();
    auto const problo = Geom(lev).ProbLoArray();
    auto const dx = Geom(lev).CellSizeArray();
    ParallelFor(phi_new[lev], [=] AMREX_GPU_DEVICE (int b, int i, int j, int k)
    {
        Real const x = problo[0] + (i+0.5_rt)*dx[0];
        Real const y = problo[1] + (j+0.5_rt)*dx[1];
        phi[b](i,j,k) = adv::initial_phi(x, y);
    });
}

void
AmrCoreAdv::MakeNewLevelFromCoarse (int lev, Real time, const BoxArray& ba,
                                    const DistributionMapping& dm)
{
    DefineLevel(lev, ba, dm);
    t_new[lev] = t_old[lev] = time;
    FillCoarsePatch(lev, time, phi_new[lev]);
}

void
AmrCoreAdv::RemakeLevel (int lev, Real time, const BoxArray& ba,
                         const DistributionMapping& dm)
{
    MultiFab new_state(ba, dm, 1, 0);
    FillPatch(lev, time, new_state);

    DefineLevel(lev, ba, dm);
    std::swap(new_state, phi_new[lev]);
    t_new[lev] = t_old[lev] = time;
}

void
AmrCoreAdv::ClearLevel (int lev)
{
    phi_new[lev].clear();
    phi_old[lev].clear();
    flux_reg[lev].reset();
}

void
AmrCoreAdv::ErrorEst (int lev, TagBoxArray& tags, Real time, int /*ngrow*/)
{
    for (auto const& tag : error_tags) {
        tag(tags, &phi_new[lev], TagBox::CLEAR, TagBox::SET, time, lev, Geom(lev));
    }
}

void
AmrCoreAdv::GetData (int lev, Real time, Vector<MultiFab*>& data, Vector<Real>& datatime)
{
    data.clear();
    datatime.clear();

    Real const teps = (t_new[lev] - t_old[lev]) * 1.e-3_rt;
    if (t_new[lev] == t_old[lev] || std::abs(time - t_new[lev]) <= teps) {
        data.push_back(&phi_new[lev]);
        datatime.push_back(t_new[lev]);
    } else if (std::abs(time - t_old[lev]) <= teps) {
        data.push_back(&phi_old[lev]);
        datatime.push_back(t_old[lev]);
    } else {
        // FillPatch interpolates linearly in time.
        data.push_back(&phi_old[lev]);
        data.push_back(&phi_new[lev]);
        datatime.push_back(t_old[lev]);
        datatime.push_back(t_new[lev]);
    }
}

void
AmrCoreAdv::FillPatch (int lev, Real time, MultiFab& mf)
{
    if (lev == 0) {
        Vector<MultiFab*> smf;
        Vector<Real> stime;
        GetData(0, time, smf, stime);

        PhysBCFunct<BndryFunc> physbc(geom[0], bcs, BndryFunc(FabFillNoOp{}));
        FillPatchSingleLevel(mf, time, smf, stime, 0, 0, mf.nComp(), geom[0], physbc, 0);
    } else {
        Vector<MultiFab*> cmf, fmf;
        Vector<Real> ctime, ftime;
        GetData(lev-1, time, cmf, ctime);
        GetData(lev  , time, fmf, ftime);

        PhysBCFunct<BndryFunc> cphysbc(geom[lev-1], bcs, BndryFunc(FabFillNoOp{}));
        PhysBCFunct<BndryFunc> fphysbc(geom[lev  ], bcs, BndryFunc(FabFillNoOp{}));
        // Conservative linear interpolation from the coarse level where
        // there is no fine data.
        FillPatchTwoLevels(mf, time, cmf, ctime, fmf, ftime, 0, 0, mf.nComp(),
                           geom[lev-1], geom[lev], cphysbc, 0, fphysbc, 0,
                           refRatio(lev-1), &cell_cons_interp, bcs, 0);
    }
}

void
AmrCoreAdv::FillCoarsePatch (int lev, Real time, MultiFab& mf)
{
    AMREX_ASSERT(lev > 0);

    Vector<MultiFab*> cmf;
    Vector<Real> ctime;
    GetData(lev-1, time, cmf, ctime);
    AMREX_ALWAYS_ASSERT(cmf.size() == 1);

    PhysBCFunct<BndryFunc> cphysbc(geom[lev-1], bcs, BndryFunc(FabFillNoOp{}));
    PhysBCFunct<BndryFunc> fphysbc(geom[lev  ], bcs, BndryFunc(FabFillNoOp{}));
    InterpFromCoarseLevel(mf, time, *cmf[0], 0, 0, mf.nComp(), geom[lev-1], geom[lev],
                          cphysbc, 0, fphysbc, 0, refRatio(lev-1),
                          &cell_cons_interp, bcs, 0);
}

void
AmrCoreAdv::AverageDownTo (int crse_lev)
{
    amrex::average_down(phi_new[crse_lev+1], phi_new[crse_lev],
                        geom[crse_lev+1], geom[crse_lev],
                        0, phi_new[crse_lev].nComp(), refRatio(crse_lev));
}

// Advance level lev by one step, then its finer levels by nsubsteps steps
// each (recursively), then synchronize lev with lev+1.
void
AmrCoreAdv::TimeStepWithSubcycling (int lev, Real time)
{
    // Regrid levels finer than lev every regrid_int steps of lev, unless a
    // coarser level has just done it.
    if (regrid_int > 0 && lev < max_level && istep[lev] > last_regrid_step[lev]
        && istep[lev] % regrid_int == 0)
    {
        int const old_finest = finest_level;
        regrid(lev, time);
        for (int k = lev; k <= finest_level; ++k) {
            last_regrid_step[k] = istep[k];
        }
        for (int k = old_finest+1; k <= finest_level; ++k) {
            dt[k] = dt[k-1] / nsubsteps[k];
        }
    }

    AdvanceLevel(lev, time, dt[lev]);
    ++istep[lev];

    if (Verbose()) {
        amrex::Print() << "  [Level " << lev << " step " << istep[lev] << "] advanced "
                       << CountCells(lev) << " cells with dt = " << dt[lev] << "\n";
    }

    if (lev < finest_level)
    {
        for (int i = 1; i <= nsubsteps[lev+1]; ++i) {
            TimeStepWithSubcycling(lev+1, time + (i-1)*dt[lev+1]);
        }

        if (do_reflux) {
            // Replace the coarse flux with the time and area averaged fine flux
            // on the coarse/fine boundary.
            flux_reg[lev+1]->Reflux(phi_new[lev], 1.0_rt, 0, 0, 1, geom[lev]);
        }

        AverageDownTo(lev);
    }
}

// Regrid, then advance all levels with the same dt. dt is computed after
// regridding so that it is stable on new and remade levels too.
void
AmrCoreAdv::TimeStepNoSubcycling (Real time)
{
    if (regrid_int > 0 && max_level > 0 && istep[0] > last_regrid_step[0]
        && istep[0] % regrid_int == 0)
    {
        regrid(0, time);
        last_regrid_step[0] = istep[0];
    }

    ComputeDt();

    for (int lev = 0; lev <= finest_level; ++lev) {
        AdvanceLevel(lev, time, dt[0]);
        ++istep[lev];
    }

    if (Verbose()) {
        for (int lev = 0; lev <= finest_level; ++lev) {
            amrex::Print() << "  [Level " << lev << " step " << istep[lev] << "] advanced "
                           << CountCells(lev) << " cells with dt = " << dt[0] << "\n";
        }
    }

    for (int lev = finest_level-1; lev >= 0; --lev) {
        if (do_reflux) {
            flux_reg[lev+1]->Reflux(phi_new[lev], 1.0_rt, 0, 0, 1, geom[lev]);
        }
        AverageDownTo(lev);
    }
}

void
AmrCoreAdv::ComputeDt ()
{
    Vector<Real> dt_tmp(finest_level+1);
    for (int lev = 0; lev <= finest_level; ++lev) {
        dt_tmp[lev] = EstTimeStep(lev, t_new[lev]);
    }

    // Let dt grow by at most 10% per step. The coarse dt must be stable on
    // every level after dividing by the number of substeps.
    constexpr Real change_max = 1.1_rt;
    Real dt_0 = dt_tmp[0];
    int n_factor = 1;
    for (int lev = 0; lev <= finest_level; ++lev) {
        if (dt[lev] > 0.0_rt) {
            dt_tmp[lev] = std::min(dt_tmp[lev], change_max*dt[lev]);
        }
        n_factor *= nsubsteps[lev];
        dt_0 = std::min(dt_0, n_factor*dt_tmp[lev]);
    }

    // Do not step past stop_time.
    Real const eps = 1.e-3_rt*dt_0;
    if (t_new[0] + dt_0 > stop_time - eps) {
        dt_0 = stop_time - t_new[0];
    }

    dt[0] = dt_0;
    for (int lev = 1; lev <= finest_level; ++lev) {
        dt[lev] = dt[lev-1] / nsubsteps[lev];
    }
}

// Advection of a scalar phi on an adaptive hierarchy. AmrCore owns the grids
// and geometry of all levels; this class owns the data and implements the
// virtual functions AmrCore calls when it creates, remakes or deletes levels.
class AmrCoreAdv
    : public amrex::AmrCore
{
public:

    AmrCoreAdv ();

    // Build the initial hierarchy, or read it from a checkpoint.
    void InitData ();

    // Advance to stop_time or max_step.
    void Evolve ();

    // Integral of phi over the domain.
    [[nodiscard]] amrex::Real TotalMass () const;

    // The functions below are public because CUDA does not allow device
    // lambdas in private or protected member functions.

    // AmrCore interface
    void MakeNewLevelFromScratch (int lev, amrex::Real time, const amrex::BoxArray& ba,
                                  const amrex::DistributionMapping& dm) override;
    void MakeNewLevelFromCoarse (int lev, amrex::Real time, const amrex::BoxArray& ba,
                                 const amrex::DistributionMapping& dm) override;
    void RemakeLevel (int lev, amrex::Real time, const amrex::BoxArray& ba,
                      const amrex::DistributionMapping& dm) override;
    void ClearLevel (int lev) override;
    void ErrorEst (int lev, amrex::TagBoxArray& tags, amrex::Real time, int ngrow) override;

    void ReadParameters ();

    // Allocate phi and the flux register of a level.
    void DefineLevel (int lev, const amrex::BoxArray& ba, const amrex::DistributionMapping& dm);

    // Time stepping
    void ComputeDt ();
    [[nodiscard]] amrex::Real EstTimeStep (int lev, amrex::Real time) const;
    void TimeStepWithSubcycling (int lev, amrex::Real time);
    void TimeStepNoSubcycling (amrex::Real time);
    void AdvanceLevel (int lev, amrex::Real time, amrex::Real dt_lev);
    void ComputeFluxes (int lev, amrex::MultiFab const& state, amrex::Real time,
                        amrex::Array<amrex::MultiFab,AMREX_SPACEDIM>& flux, bool average) const;

    void AdvanceLevel (int lev, amrex::Real time, amrex::Real dt_lev);
    void ComputeFluxes (int lev, amrex::MultiFab const& state, amrex::Real time,
                        amrex::Array<amrex::MultiFab,AMREX_SPACEDIM>& flux, bool average) const;
    void AverageDownTo (int crse_lev);

    // Fill a MultiFab including ghost cells from this level and the level below.
    void FillPatch (int lev, amrex::Real time, amrex::MultiFab& mf);
    // Fill a MultiFab entirely from the level below (for a new level).
    void FillCoarsePatch (int lev, amrex::Real time, amrex::MultiFab& mf);
    // phi_old and/or phi_new, whichever brackets time.
    void GetData (int lev, amrex::Real time, amrex::Vector<amrex::MultiFab*>& data,
                  amrex::Vector<amrex::Real>& datatime);

    // I/O
    void WritePlotFile () const;
    void WriteCheckpointFile () const;
    void ReadCheckpointFile ();

private:

    amrex::Vector<int> istep;      // steps taken on each level
    amrex::Vector<int> nsubsteps;  // substeps per step of the next coarser level
    amrex::Vector<int> last_regrid_step;

    amrex::Vector<amrex::Real> t_new;
    amrex::Vector<amrex::Real> t_old;
    amrex::Vector<amrex::Real> dt;

    amrex::Vector<amrex::MultiFab> phi_new;
    amrex::Vector<amrex::MultiFab> phi_old;

    // Physical boundary types of phi (periodic or first-order extrapolation)
    amrex::Vector<amrex::BCRec> bcs;

    // flux_reg[lev] holds the flux mismatch on the boundary between
    // levels lev and lev-1. flux_reg[0] is never used.
    amrex::Vector<std::unique_ptr<amrex::FluxRegister>> flux_reg;

    // Refinement criteria
    amrex::Vector<amrex::AMRErrorTag> error_tags;

    // Runtime parameters
    int max_step = 10;
    amrex::Real stop_time = 2.0;
    amrex::Real cfl = 0.5;
    int regrid_int = 2;
    int do_reflux = 1;
    int do_subcycle = 1;
    std::string restart_chkfile;
    std::string plot_file {"plt"};
    int plot_int = -1;
    std::string chk_file {"chk"};

    std::string plot_file {"plt"};
    int plot_int = -1;
    std::string chk_file {"chk"};
    int chk_int = -1;
}

void
AmrCoreAdv::WritePlotFile () const
{
    std::string const plotfilename = amrex::Concatenate(plot_file, istep[0], 5);
    amrex::Print() << "Writing plotfile " << plotfilename << "\n";
    amrex::WriteMultiLevelPlotfile(plotfilename, finest_level+1,
                                   GetVecOfConstPtrs(phi_new), {"phi"},
                                   Geom(), t_new[0], istep, refRatio());
}

// A checkpoint is a directory, e.g., chk00010, containing a Header with the
// time stepping state and the BoxArrays, and Level_<lev>/phi MultiFab files.
void
AmrCoreAdv::WriteCheckpointFile () const
{
    std::string const checkpointname = amrex::Concatenate(chk_file, istep[0], 5);
    amrex::Print() << "Writing checkpoint " << checkpointname << "\n";

    int const nlevels = finest_level+1;

    // The I/O rank creates the directories, followed by a barrier.
    amrex::PreBuildDirectorHierarchy(checkpointname, "Level_", nlevels, true);

    if (ParallelDescriptor::IOProcessor()) {
        std::ofstream header(checkpointname + "/Header");
        if (!header.good()) {
            amrex::FileOpenFailed(checkpointname + "/Header");
        }
        header.precision(std::numeric_limits<Real>::max_digits10);

        header << "Checkpoint file for AmrCoreAdv\n";
        header << finest_level << "\n";
        for (int lev = 0; lev < nlevels; ++lev) { header << istep[lev] << " "; }
        header << "\n";
        for (int lev = 0; lev < nlevels; ++lev) { header << dt[lev] << " "; }
        header << "\n";
        for (int lev = 0; lev < nlevels; ++lev) { header << t_new[lev] << " "; }
        header << "\n";
        for (int lev = 0; lev < nlevels; ++lev) {
            boxArray(lev).writeOn(header);
            header << "\n";
        }
    }

    for (int lev = 0; lev < nlevels; ++lev) {
        VisMF::Write(phi_new[lev],
                     amrex::MultiFabFileFullPrefix(lev, checkpointname, "Level_", "phi"));
    }
}

void
AmrCoreAdv::ReadCheckpointFile ()
{
    amrex::Print() << "Restart from checkpoint " << restart_chkfile << "\n";

    // The I/O rank reads the Header and broadcasts it.
    Vector<char> file_chars;
    ParallelDescriptor::ReadAndBcastFile(restart_chkfile + "/Header", file_chars);
    std::istringstream is(std::string(file_chars.dataPtr()));

    std::string line;
    std::getline(is, line);  // title

    is >> finest_level;
    if (finest_level > max_level) {
        amrex::Abort("Checkpoint has finest_level = " + std::to_string(finest_level)
                     + " but amr.max_level = " + std::to_string(max_level));
    }
    for (int lev = 0; lev <= finest_level; ++lev) { is >> istep[lev]; }
    for (int lev = 0; lev <= finest_level; ++lev) { is >> dt[lev]; }
    for (int lev = 0; lev <= finest_level; ++lev) { is >> t_new[lev]; }

    for (int lev = 0; lev <= finest_level; ++lev) {
        BoxArray ba;
        ba.readFrom(is);
        DistributionMapping dm(ba, ParallelDescriptor::NProcs());

        // Tell AmrCore about the grids, then allocate the data.
        SetBoxArray(lev, ba);
        SetDistributionMap(lev, dm);
        DefineLevel(lev, ba, dm);
        t_old[lev] = t_new[lev];

        VisMF::Read(phi_new[lev],
                    amrex::MultiFabFileFullPrefix(lev, restart_chkfile, "Level_", "phi"));
    }
}

// Gaussian centered at (0.5, 0.75), independent of z.
AMREX_GPU_HOST_DEVICE AMREX_FORCE_INLINE
Real initial_phi (Real x, Real y) noexcept
{
    Real const r2 = (x-0.5_rt)*(x-0.5_rt) + (y-0.75_rt)*(y-0.75_rt);
    return std::exp(-r2 / 0.01_rt);
}

// Stream function of a swirling flow in the x-y plane. The flow reverses
// at t = 1, so phi returns to its initial state at t = 2.
AMREX_GPU_HOST_DEVICE AMREX_FORCE_INLINE
Real streamfunction (Real x, Real y, Real t) noexcept
{
    constexpr Real pi = amrex::Math::pi<Real>();
    Real const sx = std::sin(pi*x);
    Real const sy = std::sin(pi*y);
    return sx*sx * sy*sy * std::cos(0.5_rt*pi*t) / pi;
}

// Normal velocity on face (i,j) of direction dir. It is computed from the
// stream function at the nodes of the face, so its discrete divergence is zero.
AMREX_GPU_HOST_DEVICE AMREX_FORCE_INLINE
Real face_velocity (int dir, int i, int j,
                    amrex::GpuArray<Real,AMREX_SPACEDIM> const& problo,
                    amrex::GpuArray<Real,AMREX_SPACEDIM> const& dx, Real t) noexcept
{
    Real const x = problo[0] + i*dx[0];
    Real const y = problo[1] + j*dx[1];
    if (dir == 0) {
        return -(streamfunction(x, y+dx[1], t) - streamfunction(x, y, t)) / dx[1];
    } else if (dir == 1) {
        return  (streamfunction(x+dx[0], y, t) - streamfunction(x, y, t)) / dx[0];
    } else {
        return 0.0_rt;
    }
}

// Monotonized central (MC) limited slope.
AMREX_GPU_HOST_DEVICE AMREX_FORCE_INLINE
Real mc_slope (Real qm, Real q0, Real qp) noexcept
{
    Real const dl = q0 - qm;
    Real const dr = qp - q0;
    if (dl*dr <= 0.0_rt) { return 0.0_rt; }
    Real const dc = 0.5_rt*(qp - qm);
    Real const s = amrex::min(2.0_rt*std::abs(dl), 2.0_rt*std::abs(dr), std::abs(dc));
    return (dc > 0.0_rt) ? s : -s;
}

// Upwind flux u*phi on the face between cells (i,j,k)-e and (i,j,k), with
// phi reconstructed linearly from the upwind cell.
AMREX_GPU_HOST_DEVICE AMREX_FORCE_INLINE
Real upwind_flux (amrex::Array4<Real const> const& q, int i, int j, int k,
                  amrex::Dim3 const& e, Real u) noexcept
{
    if (u > 0.0_rt) {
        int const il = i-e.x, jl = j-e.y, kl = k-e.z;
        Real const s = mc_slope(q(il-e.x,jl-e.y,kl-e.z), q(il,jl,kl), q(i,j,k));
        return u * (q(il,jl,kl) + 0.5_rt*s);
    } else {
        Real const s = mc_slope(q(i-e.x,j-e.y,k-e.z), q(i,j,k), q(i+e.x,j+e.y,k+e.z));
        return u * (q(i,j,k) - 0.5_rt*s);
    }
}

// Defaults for the parameters AmrCore requires, so that the code runs
// without an inputs file. Values from inputs or the command line win.
void add_default_parameters ()
{
    {
        ParmParse pp("amr");
        std::vector<int> n_cell{AMREX_D_DECL(32, 32, 8)};
        pp.queryAdd("n_cell", n_cell);
        int max_level = 2;
        pp.queryAdd("max_level", max_level);
    }
    {
        ParmParse pp("geometry");
        std::vector<Real> prob_hi{AMREX_D_DECL(1.0_rt, 1.0_rt, 0.25_rt)};
        pp.queryAdd("prob_hi", prob_hi);
        std::vector<int> is_periodic(AMREX_SPACEDIM, 1);
        pp.queryAdd("is_periodic", is_periodic);
    }
}

int main (int argc, char* argv[])
{
    amrex::Initialize(argc, argv);
    int status = 0;
    {
        add_default_parameters();

        // Reads amr.* and geometry.* and builds the Geometry of all levels.
        AmrCoreAdv amr_core_adv;

        amr_core_adv.InitData();
        Real const mass0 = amr_core_adv.TotalMass();

        amr_core_adv.Evolve();
        Real const mass = amr_core_adv.TotalMass();

        // Reflux and conservative interpolation keep the total mass constant.
        Real const rel_err = std::abs(mass - mass0) / mass0;
        amrex::Print() << "Relative change in mass: " << rel_err << "\n";
        Real const tol = std::is_same_v<Real,float> ? 1.e-5_rt : 1.e-12_rt;
        if (rel_err > tol) {
            amrex::Print() << "FAILED: mass is not conserved\n";
            status = 1;
        } else {
            amrex::Print() << "PASSED\n";
        }
    }
    amrex::Finalize();
    return status;
}

// Initial condition: a Gaussian that straddles the coarse/fine interface.
void init_phi (MultiFab& phi, Geometry const& geom)
{
    auto const& a = phi.arrays();
    auto const problo = geom.ProbLoArray();
    auto const dx = geom.CellSizeArray();
    ParallelFor(phi, [=] AMREX_GPU_DEVICE (int b, int i, int j, int k)
    {
        IntVect iv(AMREX_D_DECL(i,j,k));
        Real r2 = 0.0_rt;
        for (int d = 0; d < AMREX_SPACEDIM; ++d) {
            Real x = problo[d] + (iv[d] + 0.5_rt) * dx[d];
            r2 += (x - 0.35_rt) * (x - 0.35_rt);
        }
        a[b](i,j,k) = std::exp(-r2 / 0.01_rt);
    });
}

// Diffusive flux F = -D grad(phi) on every face of the level.
void compute_flux (MultiFab const& phi, Array<MultiFab,AMREX_SPACEDIM>& flux,
                   Geometry const& geom, Real diff_coef)
{
    auto const& p = phi.const_arrays();
    for (int d = 0; d < AMREX_SPACEDIM; ++d) {
        auto const& f = flux[d].arrays();
        Real const fac = -diff_coef * geom.InvCellSize(d);
        Dim3 const e = IntVect::TheDimensionVector(d).dim3();
        ParallelFor(flux[d], [=] AMREX_GPU_DEVICE (int b, int i, int j, int k)
        {
            f[b](i,j,k) = fac * (p[b](i,j,k) - p[b](i-e.x,j-e.y,k-e.z));
        });
    }
}

// Conservative update phi -= dt * div(F).
void update (MultiFab& phi, Array<MultiFab,AMREX_SPACEDIM> const& flux,
             Geometry const& geom, Real dt)
{
    auto const& p = phi.arrays();
    AMREX_D_TERM(auto const& fx = flux[0].const_arrays();,
                 auto const& fy = flux[1].const_arrays();,
                 auto const& fz = flux[2].const_arrays();)
    auto const dxinv = geom.InvCellSizeArray();
    ParallelFor(phi, [=] AMREX_GPU_DEVICE (int b, int i, int j, int k)
    {
        p[b](i,j,k) -= dt * (AMREX_D_TERM(  dxinv[0] * (fx[b](i+1,j,k) - fx[b](i,j,k)),
                                          + dxinv[1] * (fy[b](i,j+1,k) - fy[b](i,j,k)),
                                          + dxinv[2] * (fz[b](i,j,k+1) - fz[b](i,j,k))));
    });
}

Real total_mass (MultiFab const& phi_crse, Geometry const& geom)
{
    // Level 0 covers the domain, and average_down keeps it consistent with level 1.
    return phi_crse.sum(0) * AMREX_D_TERM(geom.CellSize(0), *geom.CellSize(1), *geom.CellSize(2));
}

